macro_rules! session_interned_fact_row {
    ($row:ty, $field:ident) => {
        impl SessionInternedFactRow for $row {
            fn from_cache(cache: &FactReadCache, row: InternedFactRow<Self>) -> &Self {
                cache.$field.row(row)
            }
        }
    };
}

