#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum HierarchyCandidateExprNode {
    Here(SemanticId),
    Via {
        reference: SemanticId,
        target: SemanticId,
        child: usize,
    },
    Union {
        left: usize,
        right: usize,
    },
}

/// The candidate expressions one hierarchy resolution has built.
///
/// An expression's identity is its position in `nodes`. `ids` already
/// deduplicates by structure, so two structurally equal expressions are one
/// position, which is the whole of what an identity has to give here: the
/// position is never written, never compared across operations and never
/// leaves the arena. It used to carry a 32-byte digest beside it, hashing the
/// structure `ids` had just interned, and the digest's only two readers were
/// the next digest and the tie-break below.
#[derive(Debug, Default)]
struct HierarchyCandidateArena {
    nodes: Vec<HierarchyCandidateExprNode>,
    ids: HashMap<HierarchyCandidateExprNode, usize>,
    owner_membership: HashMap<(usize, SemanticId), bool>,
}

impl HierarchyCandidateArena {
    fn intern(&mut self, node: HierarchyCandidateExprNode) -> usize {
        if let Some(&id) = self.ids.get(&node) {
            return id;
        }
        let id = self.nodes.len();
        self.nodes.push(node);
        self.ids.insert(node, id);
        id
    }

    fn here(&mut self, owner: SemanticId) -> usize {
        self.intern(HierarchyCandidateExprNode::Here(owner))
    }

    fn via(&mut self, reference: SemanticId, target: SemanticId, child: usize) -> usize {
        self.intern(HierarchyCandidateExprNode::Via {
            reference,
            target,
            child,
        })
    }

    fn union(&mut self, left: Option<usize>, right: Option<usize>) -> Option<usize> {
        match (left, right) {
            (None, other) | (other, None) => other,
            (Some(left), Some(right)) if left == right => Some(left),
            (Some(left), Some(right)) => {
                // A union is commutative, so the pair is ordered before it is
                // interned and `a | b` and `b | a` reach one position. The
                // order used to be the two operands' digests; their positions
                // are a total order too and are what the tie-break already
                // was.
                let (left, right) = if left < right {
                    (left, right)
                } else {
                    (right, left)
                };
                Some(self.intern(HierarchyCandidateExprNode::Union { left, right }))
            }
        }
    }

    fn contains_owner(
        &mut self,
        expression: usize,
        target: SemanticId,
        cancelled: &mut dyn FnMut() -> bool,
    ) -> Option<(bool, usize)> {
        if let Some(&contains) = self.owner_membership.get(&(expression, target)) {
            return Some((contains, 0));
        }
        let mut pending = vec![(expression, false)];
        let mut scheduled = HashSet::default();
        let mut staged = BTreeMap::<usize, bool>::new();
        let mut node_visits = 0_usize;
        while let Some((node, ready)) = pending.pop() {
            if cancelled() {
                return None;
            }
            if self.owner_membership.contains_key(&(node, target)) || staged.contains_key(&node) {
                continue;
            }
            if !ready {
                if !scheduled.insert(node) {
                    continue;
                }
                pending.push((node, true));
                match self.nodes[node] {
                    HierarchyCandidateExprNode::Here(_) => {}
                    HierarchyCandidateExprNode::Via { child, .. } => {
                        pending.push((child, false));
                    }
                    HierarchyCandidateExprNode::Union { left, right } => {
                        pending.push((right, false));
                        pending.push((left, false));
                    }
                }
                continue;
            }
            let child_contains = |child: usize, staged: &BTreeMap<usize, bool>| {
                staged.get(&child).copied().unwrap_or_else(|| {
                    *self
                        .owner_membership
                        .get(&(child, target))
                        .expect("postorder candidate membership computes every child first")
                })
            };
            let contains = match self.nodes[node] {
                HierarchyCandidateExprNode::Here(owner) => owner == target,
                HierarchyCandidateExprNode::Via { child, .. } => child_contains(child, &staged),
                HierarchyCandidateExprNode::Union { left, right } => {
                    child_contains(left, &staged) || child_contains(right, &staged)
                }
            };
            assert!(
                staged.insert(node, contains).is_none(),
                "one candidate membership node is staged once"
            );
            node_visits = node_visits
                .checked_add(1)
                .expect("hierarchy candidate membership node visits must fit usize");
        }
        for (node, contains) in staged {
            if cancelled() {
                return None;
            }
            if let Some(previous) = self.owner_membership.insert((node, target), contains) {
                assert_eq!(
                    previous, contains,
                    "one candidate node/owner membership has one exact result"
                );
            }
        }
        Some((
            *self
                .owner_membership
                .get(&(expression, target))
                .expect("the requested candidate membership was just published"),
            node_visits,
        ))
    }
}

