    fn visit_deferred_member_owner_pages_for_lookup_names(
        &self,
        lookups: TypedFactRequest<'_, DeferredMemberOwnerLookupName>,
        cancellation: &CancellationToken,
        visitor: &mut TypedFactPageVisitor<'_, SelectedTypedRow<LoweredDeferredMemberOwner>>,
    ) -> StoreResult<TypedFactReadOutcome> {
        let mut rows = Vec::new();
        for lookup in lookups.as_slice() {
            if cancellation.is_cancelled() {
                return Ok(TypedFactReadOutcome::cancelled(
                    ResolutionCompletion::Complete,
                ));
            }
            rows.extend(
                self.typed
                    .deferred_member_owners_by_lookup
                    .get(&lookup.lookup())
                    .into_iter()
                    .flat_map(|candidates| candidates.iter().copied()),
            );
        }
        rows.sort_by_key(|row| {
            (
                self.typed.source_fragment(row.definition()),
                row.owner_frontier(),
                row.lookup(),
                row.definition(),
                row.kind(),
                row.access(),
                row.qualifier_compatibility(),
            )
        });
        rows.dedup();
        let streams = [rows.as_slice()];
        visit_preloaded_typed_pages(
            &streams,
            |row| {
                (
                    self.typed.source_fragment(row.definition()),
                    row.owner_frontier(),
                    row.lookup(),
                    row.definition(),
                    row.kind(),
                    row.access(),
                    row.qualifier_compatibility(),
                )
            },
            no_preloaded_typed_evidence,
            |row, _| Some(self.typed.selected_source_row(row.definition(), *row)),
            cancellation,
            visitor,
        )
    }

