    fn visit_supertype_pages_for_definitions(
        &self,
        definitions: TypedFactRequest<'_, SemanticId>,
        cancellation: &CancellationToken,
        visitor: &mut TypedFactPageVisitor<'_, SelectedTypedRow<LoweredSupertypeProperty>>,
    ) -> StoreResult<TypedFactReadOutcome> {
        let streams = definitions
            .as_slice()
            .iter()
            .filter_map(|definition| {
                self.typed
                    .supertypes_by_definition
                    .get(definition)
                    .map(Vec::as_slice)
            })
            .collect::<Vec<_>>();
        let outcome = visit_preloaded_typed_pages(
            &streams,
            |row| {
                self.typed
                    .selected_source_row(row.reference(), *row)
                    .natural_identity()
            },
            no_preloaded_typed_evidence,
            |row, _| Some(self.typed.selected_source_row(row.reference(), *row)),
            cancellation,
            visitor,
        )?;
        #[cfg(test)]
        if let Some(test_completion) = &self.supertype_test_completion {
            let (terminal, evidence) = outcome.into_parts();
            assert_eq!(
                terminal,
                TypedFactReadTerminal::Exhausted,
                "injected supertype support evidence requires an exhausted test read"
            );
            return Ok(TypedFactReadOutcome::exhausted(
                evidence.combine(test_completion),
            ));
        }
        Ok(outcome)
    }

