    fn visit_call_applicability_pages_for_gap_reasons(
        &self,
        reasons: TypedFactRequest<'_, SemanticId>,
        cancellation: &CancellationToken,
        visitor: &mut TypedFactPageVisitor<
            '_,
            SelectedTypedRow<LoweredCallApplicabilityObligation>,
        >,
    ) -> StoreResult<TypedFactReadOutcome> {
        let mut rows = reasons
            .as_slice()
            .iter()
            .filter_map(|reason| {
                let provenance = self.typed.gap_reason_provenance_by_reason.get(reason)?;
                if provenance.origin()
                    != LoweringGapOrigin::Extracted(ResolutionGapKind::UnsupportedCallApplicability)
                {
                    return None;
                }
                let reference = super::fact_lowering::site_semantic(
                    provenance.fragment(),
                    provenance.source_site(),
                );
                let row = self.typed.call_obligation_by_reference.get(&reference)?;
                (row.applicability_reason() == *reason
                    && self.typed.source_fragment(row.call()) == provenance.fragment())
                .then_some(row)
            })
            .collect::<Vec<_>>();
        rows.sort_unstable_by_key(|row| (self.typed.source_fragment(row.call()), row.call()));
        let streams = [rows.as_slice()];
        visit_preloaded_typed_pages(
            &streams,
            |row| (self.typed.source_fragment(row.call()), row.call()),
            |row, evidence, token, work| evidence.include(row.completion(), token, work),
            |row, cancelled| {
                Some(self.typed.selected_source_row(
                    row.call(),
                    clone_call_obligation_with_poll(row, cancelled)?,
                ))
            },
            cancellation,
            visitor,
        )
    }

