fn hierarchy_iterative_scc_terminals(
    arena: &HierarchyOperationArena,
    owners: &BTreeSet<SemanticId>,
    adjacency: &BTreeMap<SemanticId, BTreeSet<SemanticId>>,
    metrics: &mut HierarchyDerivedWork,
    cancelled: &mut dyn FnMut() -> bool,
) -> Option<HashMap<SemanticId, PartialPathId>> {
    #[derive(Debug, Clone, Copy)]
    struct Frame {
        owner: SemanticId,
        parent: Option<SemanticId>,
        next_target: usize,
    }

    let mut ordered_adjacency = BTreeMap::<SemanticId, Box<[SemanticId]>>::new();
    for &owner in owners {
        if cancelled() {
            return None;
        }
        let mut ordered = Vec::new();
        for &target in adjacency.get(&owner).into_iter().flatten() {
            if cancelled() {
                return None;
            }
            assert!(
                owners.contains(&target),
                "Tarjan adjacency is closed over the staged owner set"
            );
            ordered.push(target);
        }
        ordered_adjacency.insert(owner, ordered.into_boxed_slice());
    }

    let mut next_index = 0_usize;
    let mut indices = HashMap::<SemanticId, usize>::default();
    let mut lowlinks = HashMap::<SemanticId, usize>::default();
    let mut active = HashSet::default();
    let mut component_stack = Vec::new();
    let mut cycles = HashMap::default();
    for &root in owners {
        if cancelled() {
            return None;
        }
        if indices.contains_key(&root) {
            continue;
        }
        indices.insert(root, next_index);
        lowlinks.insert(root, next_index);
        next_index += 1;
        metrics.scc_owner_visits += 1;
        component_stack.push(root);
        active.insert(root);
        let mut dfs = vec![Frame {
            owner: root,
            parent: None,
            next_target: 0,
        }];
        while !dfs.is_empty() {
            // This gate covers terminal owners with no outgoing targets too.
            if cancelled() {
                return None;
            }
            let frame_index = dfs.len() - 1;
            let owner = dfs[frame_index].owner;
            let targets = &ordered_adjacency[&owner];
            if dfs[frame_index].next_target < targets.len() {
                let target = targets[dfs[frame_index].next_target];
                dfs[frame_index].next_target += 1;
                metrics.scc_arc_visits += 1;
                if let std::collections::hash_map::Entry::Vacant(entry) = indices.entry(target) {
                    entry.insert(next_index);
                    lowlinks.insert(target, next_index);
                    next_index += 1;
                    metrics.scc_owner_visits += 1;
                    component_stack.push(target);
                    active.insert(target);
                    dfs.push(Frame {
                        owner: target,
                        parent: Some(owner),
                        next_target: 0,
                    });
                } else if active.contains(&target) {
                    let target_index = indices[&target];
                    let lowlink = lowlinks
                        .get_mut(&owner)
                        .expect("an active Tarjan owner has a lowlink");
                    *lowlink = (*lowlink).min(target_index);
                }
                continue;
            }

            let finished = dfs.pop().expect("the Tarjan DFS frame is nonempty");
            let owner_lowlink = lowlinks[&finished.owner];
            if let Some(parent) = finished.parent {
                let parent_lowlink = lowlinks
                    .get_mut(&parent)
                    .expect("a Tarjan parent has a lowlink");
                *parent_lowlink = (*parent_lowlink).min(owner_lowlink);
            }
            if owner_lowlink != indices[&finished.owner] {
                continue;
            }
            let mut component = BTreeSet::new();
            loop {
                if cancelled() {
                    return None;
                }
                let member = component_stack
                    .pop()
                    .expect("a Tarjan root has an active component member");
                active.remove(&member);
                component.insert(member);
                if member == finished.owner {
                    break;
                }
            }
            let cyclic = component.len() > 1
                || ordered_adjacency[&finished.owner]
                    .binary_search(&finished.owner)
                    .is_ok();
            if !cyclic {
                continue;
            }
            let mut hasher = CanonicalHasher::new(b"bifrost-resolution-hierarchy-scc:v1");
            hasher.field(
                "owner-count",
                &u64::try_from(component.len())
                    .expect("hierarchy SCC owner count fits u64")
                    .to_le_bytes(),
            );
            for &member in &component {
                if cancelled() {
                    return None;
                }
                hasher.field("owner", &member.as_bytes());
            }
            let cycle = arena.operation_path(hasher.finish());
            while let Some(member) = component.pop_first() {
                if cancelled() {
                    return None;
                }
                assert!(
                    cycles.insert(member, cycle).is_none(),
                    "one hierarchy owner belongs to one Tarjan component"
                );
            }
        }
    }
    Some(cycles)
}

fn qualifier_compatible(
    compatibility: ResolutionMemberQualifierCompatibility,
    category: QualifierCategory,
) -> bool {
    match compatibility {
        ResolutionMemberQualifierCompatibility::RuntimeOnly => {
            category == QualifierCategory::Runtime
        }
        ResolutionMemberQualifierCompatibility::TypeOnly => category == QualifierCategory::Type,
        ResolutionMemberQualifierCompatibility::RuntimeOrType => true,
    }
}

/// The methods one qualifier type found, split by where they are declared.
#[derive(Debug, Default)]
struct FoundMethods {
    inherent: BTreeSet<SemanticId>,
    trait_items: BTreeSet<SemanticId>,
}

/// The arguments of one call that can decide its result type, in binding
/// order, each with the parameter binding that says how.
#[derive(Debug)]
struct CallResultInstantiation {
    arguments: Vec<(
        SemanticId,
        super::typed_fact_lowering::LoweredCallableResultBinding,
    )>,
}

/// Selected callable result facts, shared by the demanded result slots in one
/// evaluation round. Positional result slots are present only when a callable
/// signature publishes them.
#[derive(Debug, Default)]
struct CallResultProjectionFacts {
    instantiations: HashMap<SemanticId, CallResultInstantiation>,
    result_type_slots_by_output: HashMap<SemanticId, HashMap<SemanticId, Option<SemanticId>>>,
}

/// What in a callee's signature can decide a call's result type: the
/// parameters its result bindings name, and the type parameter its result is,
/// the callable's own or its impl's.
#[derive(Debug)]
struct CallResultDeciders {
    parameter_count: usize,
    takes_receiver: bool,
    bindings: Vec<super::typed_fact_lowering::LoweredCallableResultBinding>,
    type_parameter: Option<super::typed_fact_lowering::LoweredCallableResultBinding>,
    owner_type_parameter: Option<super::typed_fact_lowering::LoweredCallableResultBinding>,
}

impl CallResultDeciders {
    /// `None` when nothing a call writes can decide the callee's result: its
    /// result is not a type parameter.
    fn of(signature: &LoweredCallableSignatureProperty) -> Option<Self> {
        (!signature.result_bindings().is_empty()
            || signature.result_type_parameter().is_some()
            || signature.result_owner_type_parameter().is_some())
        .then(|| Self {
            parameter_count: signature.parameters().len(),
            takes_receiver: signature.receiver().is_some(),
            bindings: signature.result_bindings().to_vec(),
            type_parameter: signature.result_type_parameter(),
            owner_type_parameter: signature.result_owner_type_parameter(),
        })
    }

    /// The slots of one call that can decide its result type, in the order
    /// they are tried:
    ///
    /// 1. each value argument the result bindings name. A call that writes
    ///    one argument more than the parameters, to a callee that takes a
    ///    receiver, is a method called in path form (`Square::echo(&square,
    ///    value)`): its first argument is the receiver, so parameter `k` is
    ///    argument `k + 1`. Any other count lines nothing up;
    /// 2. the explicit type argument at the result type parameter's position,
    ///    among the callable's own (`make::<Square>()`) or, for an impl's
    ///    parameter, `owner_type_arguments`: the arguments the path's type
    ///    segment writes (`Wrapper::<Square>::make()`), when the caller
    ///    accepts them as the type's own;
    /// 3. the type the call's context expects (`let value: Square = make();`),
    ///    which is the whole result, so its binding adds no layers.
    ///
    /// A type argument is the type parameter itself, so its binding carries
    /// only the result's own layers.
    fn deciding_slots(
        &self,
        obligation: &LoweredCallApplicabilityObligation,
        owner_type_arguments: &[SemanticId],
    ) -> Vec<(
        SemanticId,
        super::typed_fact_lowering::LoweredCallableResultBinding,
    )> {
        let mut slots = Vec::new();
        let arguments = obligation.argument_slots();
        let receiver_arguments = if arguments.len() == self.parameter_count {
            Some(0)
        } else if self.takes_receiver && arguments.len() == self.parameter_count + 1 {
            Some(1)
        } else {
            None
        };
        if let Some(offset) = receiver_arguments {
            slots.extend(self.bindings.iter().map(|binding| {
                (
                    arguments[offset
                        + usize::try_from(binding.ordinal()).expect("u32 ordinal fits usize")],
                    *binding,
                )
            }));
        }
        for (parameter, type_arguments) in [
            (self.type_parameter, obligation.type_argument_slots()),
            (self.owner_type_parameter, owner_type_arguments),
        ] {
            if let Some(parameter) = parameter
                && let Some(&slot) = type_arguments
                    .get(usize::try_from(parameter.ordinal()).expect("u32 position fits usize"))
            {
                slots.push((slot, parameter));
            }
        }
        if (self.type_parameter.is_some() || self.owner_type_parameter.is_some())
            && let Some(expected) = obligation.expected_result_slot()
        {
            slots.push((
                expected,
                super::typed_fact_lowering::LoweredCallableResultBinding::new(0, 0, 0),
            ));
        }
        slots
    }
}

/// Why a Rust member answer keeps several impl items of traits the rows
/// cannot name: which of them applies is decided by the call's argument
/// types, as rustc picks among the impls of one generic trait. One reason per
/// reference, so the argument-coercion filter can discharge the same reason
/// when it leaves one candidate.
fn rust_unnamed_trait_items_reason(
    hierarchy: &HierarchyOperationArena,
    reference: SemanticId,
) -> SemanticId {
    service_reason(
        hierarchy,
        b"rust-unnamed-trait-items",
        &[reference.as_bytes().as_slice()],
    )
}

/// Whether a call path's type segment names its type directly, so the
/// arguments it writes are that type's own, in its order: the segment's
/// reference binds exactly the one declaration its identity slot holds. A
/// segment that names an alias (`type Swap<X, Y> = Pair<Y, X>`) binds the
/// alias while its identity is the aliased type, and its arguments are the
/// alias's, which need not line up with the type's. Until the segment's
/// projection, answer and state are evaluated, the answer is no.
fn type_segment_names_its_type(
    segment: SemanticId,
    projections: &HashMap<SemanticId, LoweredBindingProjection>,
    answers: &AnswerMap,
    previous_states: &StateMap,
) -> bool {
    let Some(projection) = projections.get(&segment) else {
        return false;
    };
    let Some(&[declaration]) = answers
        .get(&projection.reference())
        .map(|answer| answer.targets())
    else {
        return false;
    };
    previous_states.get(&segment).is_some_and(|state| {
        !state.possible_values().is_empty()
            && state
                .possible_values()
                .iter()
                .all(|value| value.ty().identity() == declaration)
    })
}

/// Why a member lookup through a trait bound that found nothing proves no
/// absence. One reason per reference, so the forward answer and the reverse
/// candidate it keeps name the same reason.
fn open_bound_member_surface_reason(
    hierarchy: &HierarchyOperationArena,
    reference: SemanticId,
) -> ResolutionIncompleteReason {
    ResolutionIncompleteReason::UnsupportedSemantic(service_reason(
        hierarchy,
        b"open-bound-member-surface",
        &[reference.as_bytes().as_slice()],
    ))
}

/// Whether a Rust argument of exact type `argument` provably cannot bind a
/// parameter of exact type `parameter` under Rust's coercions.
///
/// Only intrinsic types are compared: primitives, and slices and arrays of a
/// primitive. They implement no `Deref`, and the only unsizing among them is
/// from an array to a slice. A nominal type may implement `Deref` to anything,
/// and a generic or `impl Trait` value's frontier names its bound, not its
/// type, so either one proves nothing. `kind_of` names an identity's
/// intrinsic kind, `None` for any other identity.
///
/// The type model keeps one reference and pointer count per type, and
/// projects `Box`, `Rc` and `Arc` to their payload at the same depth. So a
/// by-value slice parameter may be a `Box<[T]>` that an array argument
/// unsizes into, and a chain that mixes raw pointers or `Option` layers with
/// references does not say where each layer sits, so it proves nothing.
fn rust_argument_cannot_coerce(
    argument: ResolutionTypeRef,
    parameter: ResolutionTypeRef,
    kind_of: impl Fn(SemanticId) -> Option<IntrinsicTypeKind>,
) -> bool {
    if argument == parameter {
        return false;
    }
    let concrete = |kind: Option<IntrinsicTypeKind>| {
        matches!(
            kind,
            Some(
                IntrinsicTypeKind::Primitive | IntrinsicTypeKind::Slice | IntrinsicTypeKind::Array
            )
        )
    };
    let argument_kind = kind_of(argument.identity());
    let parameter_kind = kind_of(parameter.identity());
    if !concrete(argument_kind) || !concrete(parameter_kind) {
        return false;
    }
    let unsizes = |from: Option<IntrinsicTypeKind>, to: Option<IntrinsicTypeKind>| {
        // An array unsizes to a slice. Two array identities can also spell
        // one length differently (`4` and `4usize`), so neither proves a
        // mismatch against the other.
        from == Some(IntrinsicTypeKind::Array)
            && matches!(
                to,
                Some(IntrinsicTypeKind::Slice | IntrinsicTypeKind::Array)
            )
    };
    // A call argument gets no auto-ref, and no coercion removes every layer
    // from a reference, pointer or `Option`.
    if (argument.indirection() == 0) != (parameter.indirection() == 0) {
        return true;
    }
    if argument.indirection() == 0 {
        return !unsizes(argument_kind, parameter_kind);
    }
    let pure_references = argument.indirection() == argument.reference_indirection()
        && parameter.indirection() == parameter.reference_indirection();
    if !pure_references {
        return false;
    }
    // Deref coercion removes reference layers and never adds one.
    if argument.indirection() < parameter.indirection() {
        return true;
    }
    argument.identity() != parameter.identity() && !unsizes(argument_kind, parameter_kind)
}

fn exact_singleton_runtime_type(state: &TypedFrontierState) -> Option<ResolutionTypeRef> {
    if state.completion() != &ResolutionCompletion::Complete {
        return None;
    }
    match state.possible_values() {
        [ResolutionSlotValue::Runtime { ty, .. }] => Some(*ty),
        _ => None,
    }
}

#[derive(Debug, Clone, Copy)]
struct TransferEdge {
    source: SemanticId,
    target: SemanticId,
    indirection_delta: i64,
}

trait TransferCycleInput {
    fn transfer_edge(&self) -> TransferEdge;
}

impl TransferCycleInput for TransferEdge {
    fn transfer_edge(&self) -> TransferEdge {
        *self
    }
}

#[cfg(test)]
impl TransferCycleInput for Rc<SelectedTypedRow<LoweredTypeTransfer>> {
    fn transfer_edge(&self) -> TransferEdge {
        TransferEdge {
            source: self.row().source_slot(),
            target: self.row().rule().target_slot(),
            indirection_delta: self.row().rule().indirection_delta(),
        }
    }
}

#[cfg(test)]
impl TransferCycleInput for SelectedTypedRow<LoweredTypeTransfer> {
    fn transfer_edge(&self) -> TransferEdge {
        TransferEdge {
            source: self.row().source_slot(),
            target: self.row().rule().target_slot(),
            indirection_delta: self.row().rule().indirection_delta(),
        }
    }
}

#[derive(Debug, Default)]
struct TransferCycleClassification {
    finite_slots: HashSet<SemanticId>,
    productive_slots: HashMap<SemanticId, SemanticId>,
    productive_edges: HashMap<(SemanticId, SemanticId), SemanticId>,
}

impl TransferCycleClassification {
    fn finite_slot(&self, slot: SemanticId) -> bool {
        self.finite_slots.contains(&slot)
    }

    fn productive_slot_reason(&self, slot: SemanticId) -> Option<SemanticId> {
        self.productive_slots.get(&slot).copied()
    }

    fn productive_edge_reason(&self, source: SemanticId, target: SemanticId) -> Option<SemanticId> {
        self.productive_edges.get(&(source, target)).copied()
    }
}

/// Classify one exhausted demand-local incoming-transfer closure.
///
/// A zero-delta SCC has a finite value/category domain and may reach its least
/// fixed point normally. Any SCC containing a nonzero indirection transform
/// can generate an unbounded sequence, even when the net delta around one
/// particular cycle is zero. Every internal edge of such an SCC is therefore
/// blocked and receives the same stable, component-local incomplete evidence.
/// The input rows are the selected source's sole transfer authority. Every
/// graph walk is iterative and every semantic row/node transition polls the
/// caller, so cancellation returns no usable partial classification.
fn classify_transfer_cycles<T: TransferCycleInput>(
    arena: &HierarchyOperationArena,
    transfers: &[T],
    cancelled: &mut dyn FnMut() -> bool,
) -> Option<TransferCycleClassification> {
    let mut edges = Vec::with_capacity(transfers.len());
    let mut nodes = BTreeSet::new();
    let mut forward: HashMap<SemanticId, Vec<SemanticId>> = HashMap::default();
    let mut reverse: HashMap<SemanticId, Vec<SemanticId>> = HashMap::default();
    for transfer in transfers {
        if cancelled() {
            return None;
        }
        let edge = transfer.transfer_edge();
        nodes.insert(edge.source);
        nodes.insert(edge.target);
        forward.entry(edge.source).or_default().push(edge.target);
        reverse.entry(edge.target).or_default().push(edge.source);
        edges.push(edge);
    }

    let mut visited = HashSet::default();
    let mut finish_order = Vec::with_capacity(nodes.len());
    for root in nodes.iter().copied() {
        if cancelled() {
            return None;
        }
        if visited.contains(&root) {
            continue;
        }
        let mut stack = vec![(root, false)];
        while let Some((node, exiting)) = stack.pop() {
            if cancelled() {
                return None;
            }
            if exiting {
                finish_order.push(node);
                continue;
            }
            if !visited.insert(node) {
                continue;
            }
            stack.push((node, true));
            if let Some(neighbors) = forward.get(&node) {
                for &neighbor in neighbors.iter().rev() {
                    if cancelled() {
                        return None;
                    }
                    stack.push((neighbor, false));
                }
            }
        }
    }

    let mut assigned = HashSet::default();
    let mut components = Vec::new();
    for root in finish_order.into_iter().rev() {
        if cancelled() {
            return None;
        }
        if !assigned.insert(root) {
            continue;
        }
        let mut component = BTreeSet::new();
        let mut stack = vec![root];
        while let Some(node) = stack.pop() {
            if cancelled() {
                return None;
            }
            component.insert(node);
            if let Some(neighbors) = reverse.get(&node) {
                for &neighbor in neighbors.iter().rev() {
                    if cancelled() {
                        return None;
                    }
                    if assigned.insert(neighbor) {
                        stack.push(neighbor);
                    }
                }
            }
        }
        let mut ordered_component = Vec::with_capacity(component.len());
        while let Some(slot) = component.pop_first() {
            if cancelled() {
                return None;
            }
            ordered_component.push(slot);
        }
        components.push(ordered_component);
    }

    let mut component_by_node = HashMap::default();
    for (component_id, component) in components.iter().enumerate() {
        for &slot in component {
            if cancelled() {
                return None;
            }
            assert!(
                component_by_node.insert(slot, component_id).is_none(),
                "one transfer slot belongs to one strongly connected component"
            );
        }
    }
    let mut cyclic = Vec::with_capacity(components.len());
    let mut productive = Vec::with_capacity(components.len());
    for component in &components {
        if cancelled() {
            return None;
        }
        cyclic.push(component.len() > 1);
        productive.push(false);
    }
    for edge in &edges {
        if cancelled() {
            return None;
        }
        let source_component = component_by_node[&edge.source];
        let target_component = component_by_node[&edge.target];
        if source_component != target_component {
            continue;
        }
        cyclic[source_component] |= edge.source == edge.target;
        productive[source_component] |= edge.indirection_delta != 0;
    }

    let mut classification = TransferCycleClassification::default();
    let mut productive_reasons = HashMap::default();
    for (component_id, component) in components.iter().enumerate() {
        if cancelled() {
            return None;
        }
        if !cyclic[component_id] {
            continue;
        }
        if productive[component_id] {
            let reason = productive_transfer_cycle_reason(arena, component, cancelled)?;
            assert!(
                productive_reasons.insert(component_id, reason).is_none(),
                "one productive component owns one stable reason"
            );
            for &slot in component {
                if cancelled() {
                    return None;
                }
                assert!(
                    classification
                        .productive_slots
                        .insert(slot, reason)
                        .is_none(),
                    "one slot belongs to one productive component"
                );
            }
        } else {
            for &slot in component {
                if cancelled() {
                    return None;
                }
                classification.finite_slots.insert(slot);
            }
        }
    }
    for edge in edges {
        if cancelled() {
            return None;
        }
        let component_id = component_by_node[&edge.source];
        if component_id == component_by_node[&edge.target]
            && let Some(&reason) = productive_reasons.get(&component_id)
        {
            classification
                .productive_edges
                .insert((edge.source, edge.target), reason);
        }
    }
    (!cancelled()).then_some(classification)
}

fn productive_transfer_cycle_reason(
    arena: &HierarchyOperationArena,
    component: &[SemanticId],
    cancelled: &mut dyn FnMut() -> bool,
) -> Option<SemanticId> {
    let mut hasher = CanonicalHasher::new(b"bifrost-resolution-productive-transfer-cycle:v1");
    for (index, slot) in component.iter().enumerate() {
        if cancelled() {
            return None;
        }
        hasher.field(&format!("slot-{index}"), &slot.as_bytes());
    }
    (!cancelled()).then(|| arena.operation_semantic(hasher.finish()))
}

#[allow(clippy::too_many_arguments)]
fn merge_state_values(
    states: &mut BTreeMap<SemanticId, TypedStateAccumulator>,
    slot: SemanticId,
    values: impl IntoIterator<Item = ResolutionSlotValue>,
    completion: &ResolutionCompletion,
    extra_reason: Option<ResolutionIncompleteReason>,
    cancellation: &CancellationToken,
    work: &mut usize,
    cancellation_observed: &mut bool,
    cancellation_reasons: &mut CancellationReasonCollection,
) -> bool {
    include_completion_reasons_with_poll(
        cancellation_reasons,
        completion,
        cancellation,
        work,
        cancellation_observed,
    );
    let state = states.entry(slot).or_default();
    if *cancellation_observed {
        return false;
    }
    if state
        .completion
        .include(completion, &mut || {
            let observed = poll_cancelled(cancellation, work);
            *cancellation_observed |= observed;
            observed
        })
        .is_none()
    {
        *cancellation_observed = true;
        return false;
    }
    if let Some(reason) = extra_reason {
        cancellation_reasons.include_reason_with_poll(
            reason,
            cancellation,
            work,
            cancellation_observed,
        );
        if *cancellation_observed {
            return false;
        }
        if state
            .completion
            .include_reason(reason, &mut || {
                let observed = poll_cancelled(cancellation, work);
                *cancellation_observed |= observed;
                observed
            })
            .is_none()
        {
            *cancellation_observed = true;
            return false;
        }
    }
    for value in values {
        *cancellation_observed |= poll_cancelled(cancellation, work);
        if *cancellation_observed {
            return false;
        }
        state.values.insert(value);
    }
    *cancellation_observed |= cancellation.is_cancelled();
    !*cancellation_observed
}

fn finish_state_accumulators(
    mut accumulators: BTreeMap<SemanticId, TypedStateAccumulator>,
    cancellation: &CancellationToken,
    work: &mut usize,
    cancellation_observed: &mut bool,
) -> Option<StateMap> {
    let mut states = HashMap::default();
    while let Some((slot, mut accumulator)) = accumulators.pop_first() {
        *cancellation_observed |= poll_cancelled(cancellation, work);
        if *cancellation_observed {
            return None;
        }
        let mut values = Vec::with_capacity(accumulator.values.len());
        while let Some(value) = accumulator.values.pop_first() {
            *cancellation_observed |= poll_cancelled(cancellation, work);
            if *cancellation_observed {
                return None;
            }
            values.push(value);
        }
        let completion = accumulator.completion.finish(&mut || {
            let observed = poll_cancelled(cancellation, work);
            *cancellation_observed |= observed;
            observed
        })?;
        let state = TypedFrontierState::from_canonical_parts(
            slot,
            values.into_boxed_slice(),
            completion,
            || {
                let observed = poll_cancelled(cancellation, work);
                *cancellation_observed |= observed;
                observed
            },
        )?;
        assert!(
            states.insert(slot, Arc::new(state)).is_none(),
            "one canonical typed state is published per slot"
        );
    }
    *cancellation_observed |= cancellation.is_cancelled();
    (!*cancellation_observed).then_some(states)
}

fn poll_cancelled(cancellation: &CancellationToken, work: &mut usize) -> bool {
    *work += 1;
    (*work).is_multiple_of(CANCELLATION_QUANTUM) && cancellation.is_cancelled()
}

fn copy_route_ids_with_poll(
    route_ids: &[usize],
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<Vec<usize>> {
    let mut copied = Vec::with_capacity(route_ids.len());
    for &route_id in route_ids {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        copied.push(route_id);
    }
    if cancellation.is_cancelled() {
        return None;
    }
    Some(copied)
}

fn answer_maps_equal_with_poll(
    left: &AnswerMap,
    right: &AnswerMap,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<bool> {
    if left.len() != right.len() {
        return Some(false);
    }
    for (semantic, left) in left {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        let Some(right) = right.get(semantic) else {
            return Some(false);
        };
        let equal =
            answers_equal_with_poll(left, right, &mut || poll_cancelled(cancellation, work))?;
        if !equal {
            return Some(false);
        }
    }
    Some(true)
}

fn state_maps_equal_with_poll(
    left: &StateMap,
    right: &StateMap,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<bool> {
    if left.len() != right.len() {
        return Some(false);
    }
    for (slot, left) in left {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        let Some(right) = right.get(slot) else {
            return Some(false);
        };
        let equal =
            states_equal_with_poll(left, right, &mut || poll_cancelled(cancellation, work))?;
        if !equal {
            return Some(false);
        }
    }
    Some(true)
}

#[cfg(test)]
fn snapshot(
    references: &HashSet<SemanticId>,
    slots: &HashSet<SemanticId>,
    answers: &AnswerMap,
    states: &StateMap,
) -> EvaluationSnapshot {
    let cancellation = CancellationToken::new();
    let mut work = 0;
    snapshot_with_poll(references, slots, answers, states, &cancellation, &mut work)
        .expect("an uncancelled snapshot is total")
}

fn snapshot_with_poll(
    references: &HashSet<SemanticId>,
    slots: &HashSet<SemanticId>,
    answers: &AnswerMap,
    states: &StateMap,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<EvaluationSnapshot> {
    if poll_cancelled(cancellation, work) {
        return None;
    }
    let references = ordered_semantics_with_poll(references, cancellation, work)?;
    let slots = ordered_semantics_with_poll(slots, cancellation, work)?;
    let answers = ordered_answers_with_poll(answers, cancellation, work)?;
    let states = ordered_states_with_poll(states, cancellation, work)?;
    if poll_cancelled(cancellation, work) {
        return None;
    }
    Some(EvaluationSnapshot {
        references,
        slots,
        answers,
        states,
    })
}

fn ordered_semantics_with_poll(
    semantics: &HashSet<SemanticId>,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<Box<[SemanticId]>> {
    let mut ordered = BTreeSet::new();
    for &semantic in semantics {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        assert!(ordered.insert(semantic));
    }
    let mut output = Vec::with_capacity(ordered.len());
    for semantic in ordered {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        output.push(semantic);
    }
    Some(output.into_boxed_slice())
}

fn ordered_answer_keys_with_poll(
    answers: &AnswerMap,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<BTreeSet<SemanticId>> {
    let mut keys = BTreeSet::new();
    for &semantic in answers.keys() {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        assert!(keys.insert(semantic));
    }
    Some(keys)
}

fn ordered_state_keys_with_poll(
    states: &StateMap,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<BTreeSet<SemanticId>> {
    let mut keys = BTreeSet::new();
    for &slot in states.keys() {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        assert!(keys.insert(slot));
    }
    Some(keys)
}

fn ordered_answers_with_poll(
    answers: &AnswerMap,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<Box<[(SemanticId, SharedAnswer)]>> {
    let keys = ordered_answer_keys_with_poll(answers, cancellation, work)?;
    let mut output = Vec::with_capacity(keys.len());
    for semantic in keys {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        output.push((semantic, Arc::clone(&answers[&semantic])));
    }
    Some(output.into_boxed_slice())
}

fn ordered_states_with_poll(
    states: &StateMap,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<Box<[(SemanticId, SharedState)]>> {
    let keys = ordered_state_keys_with_poll(states, cancellation, work)?;
    let mut output = Vec::with_capacity(keys.len());
    for slot in keys {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        output.push((slot, Arc::clone(&states[&slot])));
    }
    Some(output.into_boxed_slice())
}

fn clone_completion_with_poll(
    completion: &ResolutionCompletion,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<ResolutionCompletion> {
    if poll_cancelled(cancellation, work) {
        return None;
    }
    let completion = clone_resolution_completion_with_poll(completion, &mut || {
        poll_cancelled(cancellation, work)
    })?;
    if cancellation.is_cancelled() {
        None
    } else {
        Some(completion)
    }
}

fn clone_semantic_set_with_poll(
    semantics: &HashSet<SemanticId>,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<HashSet<SemanticId>> {
    let ordered = ordered_semantics_with_poll(semantics, cancellation, work)?;
    let mut cloned = HashSet::default();
    for semantic in ordered.iter().copied() {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        assert!(cloned.insert(semantic));
    }
    Some(cloned)
}

fn clone_completion_map_with_poll(
    completions: &HashMap<SemanticId, ResolutionCompletion>,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<HashMap<SemanticId, ResolutionCompletion>> {
    let mut keys = BTreeSet::new();
    for &semantic in completions.keys() {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        assert!(keys.insert(semantic));
    }
    let mut cloned = HashMap::default();
    for semantic in keys {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        assert!(
            cloned
                .insert(
                    semantic,
                    clone_completion_with_poll(&completions[&semantic], cancellation, work)?,
                )
                .is_none()
        );
    }
    Some(cloned)
}

fn clone_answer_map_with_poll(
    answers: &AnswerMap,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<AnswerMap> {
    let keys = ordered_answer_keys_with_poll(answers, cancellation, work)?;
    let mut cloned = HashMap::default();
    for semantic in keys {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        assert!(
            cloned
                .insert(semantic, Arc::clone(&answers[&semantic]),)
                .is_none()
        );
    }
    Some(cloned)
}

fn clone_state_map_with_poll(
    states: &StateMap,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> Option<StateMap> {
    let keys = ordered_state_keys_with_poll(states, cancellation, work)?;
    let mut cloned = HashMap::default();
    for slot in keys {
        if poll_cancelled(cancellation, work) {
            return None;
        }
        assert!(cloned.insert(slot, Arc::clone(&states[&slot]),).is_none());
    }
    Some(cloned)
}

fn snapshots_equal_with_poll(
    left: &EvaluationSnapshot,
    right: &EvaluationSnapshot,
    mut cancelled: impl FnMut() -> bool,
) -> Option<bool> {
    if cancelled() {
        return None;
    }
    if left.references.len() != right.references.len()
        || left.slots.len() != right.slots.len()
        || left.answers.len() != right.answers.len()
        || left.states.len() != right.states.len()
    {
        return Some(false);
    }
    for (left, right) in left.references.iter().zip(right.references.iter()) {
        if cancelled() {
            return None;
        }
        if left != right {
            return Some(false);
        }
    }
    for (left, right) in left.slots.iter().zip(right.slots.iter()) {
        if cancelled() {
            return None;
        }
        if left != right {
            return Some(false);
        }
    }
    for ((left_semantic, left_answer), (right_semantic, right_answer)) in
        left.answers.iter().zip(right.answers.iter())
    {
        if cancelled() {
            return None;
        }
        if left_semantic != right_semantic {
            return Some(false);
        }
        let equal = answers_equal_with_poll(left_answer, right_answer, &mut cancelled)?;
        if !equal {
            return Some(false);
        }
    }
    for ((left_slot, left_state), (right_slot, right_state)) in
        left.states.iter().zip(right.states.iter())
    {
        if cancelled() {
            return None;
        }
        if left_slot != right_slot {
            return Some(false);
        }
        let equal = states_equal_with_poll(left_state, right_state, &mut cancelled)?;
        if !equal {
            return Some(false);
        }
    }
    Some(true)
}

fn answers_equal_with_poll(
    left: &ResolutionAnswer,
    right: &ResolutionAnswer,
    cancelled: &mut impl FnMut() -> bool,
) -> Option<bool> {
    // Snapshots and checkpoints share their answers, so one answer is often
    // compared with itself; its value is then equal without a walk.
    if std::ptr::eq(left, right) {
        return Some(true);
    }
    if left.targets().len() != right.targets().len()
        || left.witnesses().len() != right.witnesses().len()
    {
        return Some(false);
    }
    for (left, right) in left.targets().iter().zip(right.targets().iter()) {
        if cancelled() {
            return None;
        }
        if left != right {
            return Some(false);
        }
    }
    for (left, right) in left.witnesses().iter().zip(right.witnesses().iter()) {
        if cancelled() {
            return None;
        }
        if left.reference() != right.reference()
            || left.target() != right.target()
            || left.steps().len() != right.steps().len()
        {
            return Some(false);
        }
        for (left, right) in left.steps().iter().zip(right.steps().iter()) {
            if cancelled() {
                return None;
            }
            if left != right {
                return Some(false);
            }
        }
        let equal = completions_equal_with_poll(left.completion(), right.completion(), cancelled)?;
        if !equal {
            return Some(false);
        }
    }
    if !left.lookup_decisions_equal_with_poll(right, cancelled)? {
        return Some(false);
    }
    completions_equal_with_poll(left.completion(), right.completion(), cancelled)
}

fn states_equal_with_poll(
    left: &TypedFrontierState,
    right: &TypedFrontierState,
    cancelled: &mut impl FnMut() -> bool,
) -> Option<bool> {
    // As for answers: a shared state compared with itself is equal.
    if std::ptr::eq(left, right) {
        return Some(true);
    }
    if left.slot() != right.slot() || left.possible_values().len() != right.possible_values().len()
    {
        return Some(false);
    }
    for (left, right) in left
        .possible_values()
        .iter()
        .zip(right.possible_values().iter())
    {
        if cancelled() {
            return None;
        }
        if left != right {
            return Some(false);
        }
    }
    completions_equal_with_poll(left.completion(), right.completion(), cancelled)
}

fn completions_equal_with_poll<P>(
    left: &ResolutionCompletion,
    right: &ResolutionCompletion,
    cancelled: &mut P,
) -> Option<bool>
where
    P: FnMut() -> bool + ?Sized,
{
    if cancelled() {
        return None;
    }
    match (left, right) {
        (ResolutionCompletion::Complete, ResolutionCompletion::Complete) => Some(true),
        (ResolutionCompletion::Incomplete(left), ResolutionCompletion::Incomplete(right)) => {
            left.equals_with_poll(right, cancelled)
        }
        _ => Some(false),
    }
}

fn answer_with_completion(
    answer: ResolutionAnswer,
    completion: ResolutionCompletion,
) -> ResolutionAnswer {
    ResolutionAnswer::new(
        answer.targets().to_vec(),
        answer.witnesses().to_vec(),
        completion,
    )
}

fn empty_reference_answer(completion: ResolutionCompletion) -> ReferenceSearchAnswer {
    ReferenceSearchAnswer::new(Vec::new(), Vec::new(), completion)
}

fn completion_without_unsupported_semantic(
    completion: &ResolutionCompletion,
    semantic: SemanticId,
) -> ResolutionCompletion {
    let ResolutionCompletion::Incomplete(reasons) = completion else {
        return ResolutionCompletion::Complete;
    };
    if reasons.is_shared() {
        return reasons
            .without_reasons([ResolutionIncompleteReason::UnsupportedSemantic(semantic)])
            .map_or(
                ResolutionCompletion::Complete,
                ResolutionCompletion::Incomplete,
            );
    }
    let retained = reasons
        .iter()
        .copied()
        .filter(|reason| *reason != ResolutionIncompleteReason::UnsupportedSemantic(semantic))
        .collect::<Vec<_>>();
    if retained.is_empty() {
        ResolutionCompletion::Complete
    } else {
        ResolutionCompletion::incomplete(retained)
    }
}

fn completion_without_bound_reference_reasons(
    completion: &ResolutionCompletion,
    owned: &BTreeSet<ResolutionIncompleteReason>,
    cancellation: &CancellationToken,
    work: &mut usize,
) -> ResolutionCompletion {
    if owned.is_empty() {
        return completion.clone();
    }
    let ResolutionCompletion::Incomplete(reasons) = completion else {
        return completion.clone();
    };
    match reasons.without_reasons_with_poll(owned.iter().copied(), &mut || {
        poll_cancelled(cancellation, work)
    }) {
        Some(retained) => retained.map_or(
            ResolutionCompletion::Complete,
            ResolutionCompletion::Incomplete,
        ),
        None => completion.combine(&ResolutionCompletion::incomplete([
            ResolutionIncompleteReason::Cancelled,
        ])),
    }
}

fn completion_without_unsupported_semantics_with_poll(
    completion: &ResolutionCompletion,
    semantics: &BTreeSet<SemanticId>,
    cancelled: &mut dyn FnMut() -> bool,
) -> Option<ResolutionCompletion> {
    if cancelled() {
        return None;
    }
    let ResolutionCompletion::Incomplete(reasons) = completion else {
        return Some(ResolutionCompletion::Complete);
    };
    if reasons.is_shared() {
        let retained = reasons.without_reasons_with_poll(
            semantics
                .iter()
                .copied()
                .map(ResolutionIncompleteReason::UnsupportedSemantic),
            cancelled,
        )?;
        if cancelled() {
            return None;
        }
        return Some(retained.map_or(
            ResolutionCompletion::Complete,
            ResolutionCompletion::Incomplete,
        ));
    }
    let mut retained = Vec::with_capacity(reasons.len());
    let mut removed = false;
    for &reason in reasons.iter() {
        if cancelled() {
            return None;
        }
        if let ResolutionIncompleteReason::UnsupportedSemantic(semantic) = reason
            && semantics.contains(&semantic)
        {
            removed = true;
        } else {
            retained.push(reason);
        }
    }
    if cancelled() {
        return None;
    }
    Some(if removed && retained.is_empty() {
        ResolutionCompletion::Complete
    } else {
        ResolutionCompletion::Incomplete(retained.into_boxed_slice().into())
    })
}

fn incomplete(reason: SemanticId) -> ResolutionCompletion {
    ResolutionCompletion::incomplete([ResolutionIncompleteReason::UnsupportedSemantic(reason)])
}

fn incomplete_cancelled() -> ResolutionCompletion {
    ResolutionCompletion::incomplete([ResolutionIncompleteReason::Cancelled])
}

fn service_reason(arena: &HierarchyOperationArena, kind: &[u8], fields: &[&[u8]]) -> SemanticId {
    let mut hasher = CanonicalHasher::new(b"bifrost-resolution-fact-service-reason:v1");
    hasher.field("kind", kind);
    for (index, field) in fields.iter().enumerate() {
        hasher.field(&format!("field-{index}"), field);
    }
    arena.operation_semantic(hasher.finish())
}

fn projection_natural_identity(row: &SelectedTypedRow<LoweredBindingProjection>) -> ProjectionKey {
    (
        row.fragment(),
        row.row().reference(),
        row.row().output_slot(),
        projection_kind_rank(row.row().kind()),
    )
}

const fn projection_kind_rank(kind: BindingProjectionKind) -> u8 {
    match kind {
        BindingProjectionKind::TargetTypeIdentity => 0,
        BindingProjectionKind::TargetDeclaredValueType => 1,
        BindingProjectionKind::TargetCallableResultType => 2,
        BindingProjectionKind::TargetConstructorOwnerType => 3,
        BindingProjectionKind::TargetTypeOrDeclaredValueType => 4,
        BindingProjectionKind::TargetMemberOwnerType => 5,
        BindingProjectionKind::TargetNominalTypeIdentity => 6,
    }
}

const fn declaration_type_role_rank(role: DeclarationTypeRole) -> u8 {
    match role {
        DeclarationTypeRole::Value => 0,
        DeclarationTypeRole::Parameter => 1,
        DeclarationTypeRole::Return => 2,
        DeclarationTypeRole::Identity => 3,
        DeclarationTypeRole::NominalIdentity => 4,
    }
}

const fn member_kind_rank(kind: ResolutionMemberKind) -> u8 {
    match kind {
        ResolutionMemberKind::NestedType => 0,
        ResolutionMemberKind::Method => 1,
        ResolutionMemberKind::Constructor => 2,
        ResolutionMemberKind::Field => 3,
        ResolutionMemberKind::AssociatedType => 4,
    }
}

const fn qualifier_compatibility_rank(compatibility: ResolutionMemberQualifierCompatibility) -> u8 {
    match compatibility {
        ResolutionMemberQualifierCompatibility::RuntimeOnly => 0,
        ResolutionMemberQualifierCompatibility::TypeOnly => 1,
        ResolutionMemberQualifierCompatibility::RuntimeOrType => 2,
    }
}

/// Whether a declaration's visibility carries the exact number of
/// unsupported-visibility gaps its lowering must publish. Public carries
/// none and every restricted level (Java's access levels, Rust's
/// crate/module and C#'s internal) carries one. Unknown carries one in most
/// languages but none for Java local and anonymous types, whose visibility
/// lexical scope already decides; the per-language rule is enforced when the
/// facts are lowered.
fn visibility_gap_count_matches(visibility: DeclaredVisibility, gaps: usize) -> bool {
    match visibility {
        DeclaredVisibility::Public => gaps == 0,
        DeclaredVisibility::Unknown => gaps <= 1,
        _ => gaps == 1,
    }
}

/// Whether a lookup through this declaration must apply contextual access:
/// every non-public declaration except an Unknown one without a visibility
/// gap, whose lexical scope already decided its visibility.
fn visibility_has_access_obligation(
    visibility: DeclaredVisibility,
    gaps: &[(ResolutionGapKind, SemanticId)],
) -> bool {
    match visibility {
        DeclaredVisibility::Public => false,
        DeclaredVisibility::Unknown => gaps
            .iter()
            .any(|gap| gap.0 == ResolutionGapKind::UnsupportedVisibility),
        _ => true,
    }
}

