    /// The Rust coercion facts the argument filter relies on, and the shapes
    /// it must never exclude: a nominal or generic identity and a chain that
    /// mixes pointer layers can each reach a parameter the model cannot see.
    #[test]
    fn rust_argument_coercion_excludes_only_impossible_intrinsic_bindings() {
        let f32 = SemanticId::local(0, 1);
        let f64 = SemanticId::local(0, 2);
        let slice = SemanticId::local(0, 3);
        let array = SemanticId::local(0, 4);
        let nominal = SemanticId::local(0, 5);
        let kind_of = |identity: SemanticId| match identity {
            identity if identity == f32 || identity == f64 => Some(IntrinsicTypeKind::Primitive),
            identity if identity == slice => Some(IntrinsicTypeKind::Slice),
            identity if identity == array => Some(IntrinsicTypeKind::Array),
            _ => None,
        };
        let ty = ResolutionTypeRef::new_with_reference_indirection;
        for (argument, parameter, cannot_coerce, why) in [
            (ty(f32, 0, 0), ty(f32, 0, 0), false, "identical types"),
            (
                ty(f32, 0, 0),
                ty(f64, 0, 0),
                true,
                "no implicit numeric conversion",
            ),
            (
                ty(f32, 0, 0),
                ty(f32, 1, 1),
                true,
                "no auto-ref at an argument",
            ),
            (
                ty(f32, 1, 1),
                ty(f32, 0, 0),
                true,
                "a reference never becomes a value",
            ),
            (
                ty(f32, 1, 1),
                ty(slice, 1, 1),
                true,
                "f32 neither derefs nor unsizes",
            ),
            (
                ty(array, 1, 1),
                ty(f32, 1, 1),
                true,
                "an array does not deref",
            ),
            (
                ty(array, 1, 1),
                ty(slice, 1, 1),
                false,
                "&[T; N] unsizes to &[T]",
            ),
            (
                ty(array, 0, 0),
                ty(slice, 0, 0),
                false,
                "Box<[T; N]> unsizes to Box<[T]>",
            ),
            (ty(array, 0, 0), ty(array, 0, 0), false, "identical arrays"),
            (ty(f32, 2, 2), ty(f32, 1, 1), false, "&&f32 derefs to &f32"),
            (
                ty(f32, 1, 1),
                ty(f32, 2, 2),
                true,
                "deref never adds a reference",
            ),
            (
                ty(f32, 2, 1),
                ty(f32, 1, 1),
                false,
                "a pointer layer's position is unknown",
            ),
            (
                ty(nominal, 1, 1),
                ty(slice, 1, 1),
                false,
                "a nominal type may deref",
            ),
            (
                ty(nominal, 0, 0),
                ty(f32, 1, 1),
                false,
                "a generic can be a reference",
            ),
            (
                ty(f32, 0, 0),
                ty(nominal, 0, 0),
                false,
                "a generic bound admits f32",
            ),
        ] {
            assert_eq!(
                rust_argument_cannot_coerce(argument, parameter, kind_of),
                cannot_coerce,
                "{why}: {argument:?} into {parameter:?}"
            );
        }
    }

    mod inherent_member_evaluation_tests {
        include!("inherent_member_evaluation_tests.rs");

        #[test]
        fn transferred_type_observations_bind_nominal_impls_and_preserve_abstract_frontiers() {
            let source = "pub struct Service; impl Service { fn new() -> Self { Service } } trait Abstract { fn new() -> Self; }";
            let fixture = parsed_rust_fixture(source, b"observed-type-identities");
            let service = definition_after(&fixture, "pub struct", "Service");
            let abstract_type = definition_after(&fixture, "trait", "Abstract");
            let observations = fixture
                .typed
                .frontiers()
                .iter()
                .filter_map(|frontier| {
                    frontier
                        .type_identity_reference()
                        .map(|(reference, _)| (reference, frontier.slot()))
                })
                .collect::<Vec<_>>();
            assert_eq!(observations.len(), 2);
            let mut nominal = Vec::new();
            let mut abstract_count = 0;
            for (reference, slot) in observations {
                let answer = fixture
                    .service
                    .resolve_reference(reference, &CancellationToken::new())
                    .unwrap();
                assert_eq!(answer.observed_type_identity(), Some(slot));
                assert!(
                    answer.projections().is_empty(),
                    "observation is not another producer"
                );
                assert!(!answer.binding().targets().contains(&abstract_type));
                if answer.binding().targets().is_empty() {
                    assert_ne!(answer.completion(), &ResolutionCompletion::Complete);
                    abstract_count += 1;
                } else {
                    assert_eq!(answer.binding().targets(), &[service]);
                    assert_eq!(answer.completion(), &ResolutionCompletion::Complete);
                    nominal.push(reference);
                }
            }
            assert_eq!(abstract_count, 1);
            assert_eq!(nominal.len(), 1);
            let reverse = fixture
                .service
                .references_to(service, &CancellationToken::new())
                .unwrap();
            assert!(reverse.references().contains(&nominal[0]), "{reverse:?}");
        }

        #[test]
        fn self_tuple_constructor_matches_explicit_type_and_reverse_lookup() {
            let source = "pub struct Record(pub u32); impl Record { fn new() -> Self { Self(1) } fn explicit() -> Self { Record(1) } }";
            let fixture = parsed_rust_fixture(source, b"self-tuple-constructor");
            let definition = definition_after(&fixture, "pub struct", "Record");
            let implicit = callable_reference_named_at(&fixture, "Self(1)", "Self");
            let explicit = callable_reference_named_at(&fixture, "Record(1)", "Record");
            let mut result_values = Vec::new();
            for reference in [implicit, explicit] {
                let answer = fixture
                    .service
                    .resolve_reference(reference, &CancellationToken::new())
                    .unwrap();
                assert_eq!(answer.binding().targets(), &[definition], "{answer:?}");
                assert_eq!(
                    answer.binding().completion(),
                    &ResolutionCompletion::Complete,
                    "{answer:?}"
                );
                let projection = answer
                    .projections()
                    .iter()
                    .find(|projection| {
                        projection.kind() == BindingProjectionKind::TargetCallableResultType
                    })
                    .unwrap();
                let result = answer
                    .projected_frontiers()
                    .iter()
                    .find(|frontier| frontier.slot() == projection.output_slot())
                    .unwrap();
                // Tuple-call result inference is already incomplete for the
                // explicit Record spelling. Self must preserve that honest
                // result uncertainty while resolving the same declaration.
                assert!(matches!(
                    result.completion(),
                    ResolutionCompletion::Incomplete(_)
                ));
                result_values.push(result.possible_values().to_vec());
                assert_experimental_call_matches_eager(&fixture.service, reference);
            }
            assert_eq!(result_values[0], result_values[1]);
            let reverse = fixture
                .service
                .references_to(definition, &CancellationToken::new())
                .unwrap();
            assert!(reverse.references().contains(&implicit), "{reverse:?}");
            assert!(reverse.references().contains(&explicit), "{reverse:?}");
            let cancelled = CancellationToken::new();
            cancelled.cancel();
            let answer = fixture
                .service
                .resolve_reference(implicit, &cancelled)
                .unwrap();
            assert!(
                answer
                    .completion()
                    .contains_reason(ResolutionIncompleteReason::Cancelled)
            );
        }

        #[test]
        fn experimental_rust_calls_preserve_argument_independent_and_deferred_member_semantics() {
            let source = "pub fn target(value: i32) {} pub mod nested { pub fn qualified() {} } pub struct Service; impl Service { pub fn run(&self) {} } pub fn caller(service: Service) { target(1); crate::nested::qualified(); service.run(); }";
            let fixture = parsed_rust_fixture(source, b"experimental-rust-call-frames");
            for (marker, name) in [
                ("target(1)", "target"),
                ("nested::qualified()", "qualified"),
                ("service.run()", "run"),
            ] {
                let reference = callable_reference_named_at(&fixture, marker, name);
                let obligation = fixture
                    .typed
                    .call_obligations()
                    .iter()
                    .find(|call| call.callee_reference() == reference)
                    .unwrap();
                assert!(
                    obligation
                        .eligible_rules()
                        .contains(&ResolutionEngineRuleKind::ArgumentIndependentBinding)
                );
                assert_experimental_call_matches_eager(&fixture.service, reference);
            }
        }
    }

