    fn install_cached_intrinsic_relation(
        operation: &mut FactResolutionOperation<'_>,
        request: SemanticId,
        rows: &[SelectedTypedRow<LoweredIntrinsicSeed>],
    ) {
        assert!(!rows.is_empty());
        let keys = rows
            .iter()
            .map(|row| (row.fragment(), row.row().frontier().slot()))
            .collect::<Vec<_>>();
        let cache = &mut operation.session.cache;
        for (key, row) in keys.iter().copied().zip(rows.iter()) {
            cache.intrinsic_rows.intern(key, row.clone());
        }
        let evidence = cache.intrinsics_by_type_identity.evidence.len();
        cache
            .intrinsics_by_type_identity
            .evidence
            .push(ResolutionCompletion::Complete);
        assert!(
            cache
                .intrinsics_by_type_identity
                .by_request
                .insert(
                    request,
                    CachedFactRelation {
                        row_keys: keys.clone(),
                        evidence,
                    },
                )
                .is_none()
        );
        for row in rows {
            let mut relations = vec![ObservedFactRelation::Primary(row.row().frontier().slot())];
            relations.extend(
                row.row()
                    .frontier()
                    .possible_values()
                    .iter()
                    .map(|value| ObservedFactRelation::Secondary(value.ty().identity())),
            );
            for relation in relations {
                cache
                    .intrinsic_rows
                    .observed_keys_by_relation
                    .entry(relation)
                    .or_default()
                    .extend(keys.iter().copied());
                cache.intrinsic_rows.exhausted_relations.insert(relation);
            }
        }
    }

    fn empty_selected_blueprint(cancellation: &CancellationToken) -> SelectedContextTestOracle {
        let SelectedResolutionContextValidationOutcome::Ready(context) =
            SelectedResolutionContextSet::new(
                crate::analyzer::resolution::SelectedContextIdentities::new(),
                Vec::<SelectedResolutionMountContext>::new(),
                0,
                &|_| Ok(None),
            )
            .expect("an empty selected context set is valid")
            .validate_exact_mounts(0, &|_| Ok(None), cancellation)
            .expect("an empty selected context validates")
        else {
            panic!("an uncancelled empty selected context must validate")
        };
        SelectedContextTestOracle::collect_context(
            context,
            crate::analyzer::resolution::test_shared_names(),
            cancellation,
        )
        .expect("an empty oracle context compiles")
    }

    #[test]
    fn bounded_forward_callback_shares_session_and_suppresses_terminal_values() {
        let fixture = java_fixture();
        let references = [fixture.references[&10], fixture.references[&11]];
        let cancellation = CancellationToken::new();
        let blueprint = empty_selected_blueprint(&cancellation);

        reset_selected_fact_operation_construction_count_for_test();
        let complete = blueprint
            .with_forward_operation(
                &fixture.service,
                &fixture.service,
                ReceiverAnalysisBudget::default(),
                &cancellation,
                |operation, session| {
                    let mut answers = Vec::with_capacity(references.len());
                    for reference in references {
                        assert!(session.scope_step());
                        answers.push(operation.resolve_reference(reference)?);
                    }
                    Ok(answers)
                },
            )
            .expect("the shared bounded forward operation is operational");
        let BoundedResolution::Complete { value, .. } = complete else {
            panic!("the default bounded forward operation must complete")
        };
        assert_eq!(value.len(), references.len());
        assert_eq!(
            selected_fact_operation_construction_count_for_test(),
            1,
            "the callback must reuse one fact operation and read session"
        );

        let cancellation = CancellationToken::new();
        let blueprint = empty_selected_blueprint(&cancellation);
        let exceeded = blueprint
            .with_forward_operation(
                &fixture.service,
                &fixture.service,
                ReceiverAnalysisBudget::tiny(),
                &cancellation,
                |operation, session| {
                    let mut answers = Vec::new();
                    if session.scope_step() {
                        answers.push(operation.resolve_reference(references[0])?);
                    }
                    Ok(answers)
                },
            )
            .expect("a bounded operation reports budget exhaustion as a value");
        assert!(matches!(exceeded, BoundedResolution::Exceeded { .. }));

        let cancellation = CancellationToken::new();
        let blueprint = empty_selected_blueprint(&cancellation);
        let cancelled = blueprint
            .with_forward_operation(
                &fixture.service,
                &fixture.service,
                ReceiverAnalysisBudget::default(),
                &cancellation,
                |operation, _session| {
                    let answer = operation.resolve_reference(references[0])?;
                    cancellation.cancel();
                    Ok(vec![answer])
                },
            )
            .expect("a cancelled callback remains operational");
        assert!(matches!(cancelled, BoundedResolution::Cancelled { .. }));
    }

