    fn install_preloaded_transfer(
        selection: &mut TypedSelection,
        fragment: BindingFragmentId,
        transfer: LoweredTypeTransfer,
    ) {
        let source = transfer.source_slot();
        let target = transfer.rule().target_slot();
        let semantic = transfer.rule().semantic();
        retain_source_row_fragment(&mut selection.source_row_fragments, semantic, fragment);
        selection
            .transfers_by_source
            .entry(source)
            .or_default()
            .push(transfer.clone());
        selection
            .transfers_by_target
            .entry(target)
            .or_default()
            .push(transfer);
        let owners = &selection.source_row_fragments;
        {
            let rows = selection.transfers_by_source.get_mut(&source).unwrap();
            rows.sort_by_key(|row| (owners[&row.rule().semantic()], row.rule().semantic()));
            rows.dedup();
        }
        {
            let rows = selection.transfers_by_target.get_mut(&target).unwrap();
            rows.sort_by_key(|row| (owners[&row.rule().semantic()], row.rule().semantic()));
            rows.dedup();
        }
    }

    fn replace_preloaded_transfer(
        selection: &mut TypedSelection,
        semantic: SemanticId,
        indirection_delta: i64,
        value_transform: TypeTransferValueTransform,
        completion: ResolutionCompletion,
    ) {
        let mut replaced = 0_usize;
        for transfers in selection
            .transfers_by_source
            .values_mut()
            .chain(selection.transfers_by_target.values_mut())
        {
            for transfer in transfers {
                if transfer.rule().semantic() != semantic {
                    continue;
                }
                *transfer = LoweredTypeTransfer::new(
                    transfer.source_slot(),
                    transfer.kind(),
                    TypeTransferRule::new(
                        semantic,
                        transfer.rule().target_slot(),
                        indirection_delta,
                        value_transform,
                        completion.clone(),
                    ),
                );
                replaced += 1;
            }
        }
        assert_eq!(
            replaced, 2,
            "one selected transfer appears once in each access direction"
        );
    }

