    fn selected_cycle_classification(
        selection: &TypedSelection,
        slots: &[SemanticId],
    ) -> TransferCycleClassification {
        let mut rows = Vec::new();
        for &target in slots {
            for transfer in selection
                .transfers_by_target
                .get(&target)
                .into_iter()
                .flatten()
            {
                rows.push(Rc::new(selection.selected_source_row(
                    transfer.rule().semantic(),
                    transfer.clone(),
                )));
            }
        }
        rows.sort_by_key(|row| row.target_access_order());
        classify_transfer_cycles(test_arena(), &rows, &mut || false)
            .expect("a live selected cycle classification completes")
    }

    fn collect_typed_read<T, F>(read: F) -> (Vec<T>, Vec<usize>, TypedFactReadOutcome)
    where
        T: Clone,
        F: FnOnce(&mut TypedFactPageVisitor<'_, T>) -> StoreResult<TypedFactReadOutcome>,
    {
        let mut rows = Vec::new();
        let mut page_sizes = Vec::new();
        let mut callback = |page: &[T]| {
            page_sizes.push(page.len());
            rows.extend_from_slice(page);
            Ok(true)
        };
        let mut visitor = TypedFactPageVisitor::new(&mut callback);
        let outcome = read(&mut visitor).expect("preloaded typed reads are infallible");
        (rows, page_sizes, outcome)
    }

    fn assert_exhausted_typed_rows<T, F>(expected: Vec<T>, read: F)
    where
        T: Clone + std::fmt::Debug + PartialEq,
        F: FnOnce(&mut TypedFactPageVisitor<'_, T>) -> StoreResult<TypedFactReadOutcome>,
    {
        let (actual, page_sizes, outcome) = collect_typed_read(read);
        assert_eq!(actual, expected);
        assert!(
            page_sizes
                .iter()
                .all(|&size| size <= MAX_TYPED_FACT_ROWS_PER_PAGE)
        );
        assert_eq!(outcome.terminal(), TypedFactReadTerminal::Exhausted);
        assert_eq!(outcome.evidence(), &ResolutionCompletion::Complete);
    }

    fn reversed_unique<T>(values: impl IntoIterator<Item = T>) -> Vec<T>
    where
        T: Ord,
    {
        values
            .into_iter()
            .collect::<BTreeSet<_>>()
            .into_iter()
            .rev()
            .collect()
    }

    #[test]
    fn qualified_route_dual_coordinates_share_one_preloaded_and_session_identity() {
        for namespace in [ResolutionNamespace::Callable, ResolutionNamespace::Value] {
            let mut facts = java_chain_facts();
            facts
                .identifiers
                .iter_mut()
                .find(|identifier| identifier.site == ResolutionSiteId::new(11))
                .expect("the fixture has a qualified callable projection")
                .namespace = namespace;
            if namespace == ResolutionNamespace::Value {
                facts
                    .callable_receiver_origins
                    .retain(|origin| origin.reference != ResolutionSiteId::new(11));
            }
            let fixture = java_fixture_from_facts(facts);
            let reference = fixture.references[&11];
            let route_id = fixture.service.typed.qualified_route_ids_by_reference[&reference][0];
            let base = fixture.service.typed.qualified_routes[route_id].row;
            let source_lookup = base.source_lookup();
            assert_eq!(base.namespace(), ResolutionNamespace::Callable);
            assert_eq!(
                base.lookup() == source_lookup,
                namespace == ResolutionNamespace::Callable
            );
            let selected = fixture.service.typed.selected_source_route(route_id);
            let cancellation = CancellationToken::new();
            let lookups = reversed_unique([base.lookup(), source_lookup]);
            let requests = lookups
                .iter()
                .map(|&lookup| QualifiedRouteSlotLookup::new(base.qualifier_slot(), lookup))
                .collect::<Vec<_>>();
            let (rows, _, outcome) = collect_typed_read(|visitor| {
                fixture
                    .service
                    .visit_qualified_route_pages_for_slot_lookups(
                        TypedFactRequest::new(&requests),
                        &cancellation,
                        visitor,
                    )
            });
            assert_eq!(rows, [selected], "namespace={namespace:?}");
            assert_eq!(outcome.terminal(), TypedFactReadTerminal::Exhausted);

            let mut session = preloaded_session(&fixture.service, &cancellation);
            let SessionFactRead::Exhausted {
                rows: source_rows, ..
            } = session
                .routes_for_slot_lookups(&[QualifiedRouteSlotLookup::new(
                    base.qualifier_slot(),
                    source_lookup,
                )])
                .expect("the source coordinate is an exact route relation")
            else {
                panic!("a live route read cannot cancel")
            };
            assert_eq!(source_rows.len(), 1);
            let SessionFactRead::Exhausted {
                rows: member_rows, ..
            } = session
                .routes_for_slot_lookups(&[QualifiedRouteSlotLookup::new(
                    base.qualifier_slot(),
                    base.lookup(),
                )])
                .expect("the member coordinate reuses the same immutable route")
            else {
                panic!("a live route read cannot cancel")
            };
            assert_eq!(member_rows, source_rows);
            let SessionFactRead::Exhausted { rows, .. } = session
                .routes_for_lookups(&lookups)
                .expect("the lookup union deduplicates the natural route identity")
            else {
                panic!("a live route read cannot cancel")
            };
            assert_eq!(rows.iter().filter(|row| **row == source_rows[0]).count(), 1);
            assert_eq!(*source_rows[0].get(&session), selected);
        }
    }

