    fn all_typed_source_facts() -> FileResolutionFacts {
        let mut facts = java_chain_facts();
        facts.supertypes.push(ResolutionSupertypeFact {
            subtype: ResolutionSiteId::new(0),
            supertype_reference: ResolutionSiteId::new(13),
            supertype_slot: ResolutionTypeSlotId::new(10),
            kind: ResolutionSupertypeKind::Superclass,
        });
        facts.gaps.extend([
            ResolutionGapFact {
                site: ResolutionSiteId::new(1),
                kind: ResolutionGapKind::ImplicitConstructor,
            },
            ResolutionGapFact {
                site: ResolutionSiteId::new(13),
                kind: ResolutionGapKind::UnsupportedHierarchyTraversal,
            },
        ]);
        facts
    }

    #[test]
    fn demand_scheduler_drives_nested_prefixes_once_and_rejects_cycles() {
        use super::{
            DemandAcyclicOutcome as Outcome, DemandAcyclicUnsupported as Unsupported,
            DemandRootDiscovery as RootDiscovery, DemandRootPlan as RootPlan,
            DemandRootProvider as RootProvider,
        };

        struct Provider {
            dependencies: HashMap<EndpointSignature, Vec<SemanticId>>,
            expected: HashMap<SemanticId, FactResolutionAnswer>,
            discovered: HashSet<EndpointSignature>,
            closed: HashSet<EndpointSignature>,
            supplied: Vec<SemanticId>,
            discovery_completion: ResolutionCompletion,
            fail_close: bool,
        }
        impl RootProvider for Provider {
            fn discover(&mut self, endpoint: &EndpointSignature) -> StoreResult<RootDiscovery> {
                assert!(self.discovered.insert(endpoint.clone()));
                Ok(RootDiscovery::Ready(RootPlan {
                    prefixes: self.dependencies.get(endpoint).cloned().unwrap_or_default(),
                    completion: self.discovery_completion.clone(),
                }))
            }

            fn close(
                &mut self,
                endpoint: &EndpointSignature,
                inputs: &[(SemanticId, &FactResolutionAnswer)],
            ) -> StoreResult<ResolutionCompletion> {
                if self.fail_close {
                    return Err(StoreError::new("injected root materialization failure"));
                }
                assert!(self.closed.insert(endpoint.clone()));
                for (root, answer) in inputs {
                    assert_eq!(*answer, &self.expected[root]);
                    self.supplied.push(*root);
                }
                Ok(ResolutionCompletion::Complete)
            }
        }
        let facts = single_unqualified_reverse_facts();
        let owners = [
            b"scheduler-a",
            b"scheduler-b",
            b"scheduler-c",
            b"scheduler-d",
        ]
        .map(BindingFragmentId::for_test);
        let lexical = owners.map(|owner| {
            crate::analyzer::resolution::lower_for_test(owner, Language::Java, &facts)
                .lexical()
                .clone()
        });
        let roots = lexical.each_ref().map(|fragment| {
            lowered_semantic_at(
                fragment,
                ResolutionSiteId::new(1),
                LoweredSemanticRole::Reference,
            )
        });
        let typed = owners.map(|owner| {
            crate::analyzer::resolution::lower_for_test(owner, Language::Java, &facts)
                .typed()
                .clone()
        });
        let service = PreloadedFactResolutionService::from_lowered_fragments(lexical, typed);
        let cancellation = CancellationToken::new();
        let endpoints = roots.map(|root| {
            let seed = service
                .source
                .reference_seed(ResolutionQuery::new(root), &cancellation)
                .unwrap()
                .unwrap();
            crate::analyzer::resolution::engine::identity_path(seed.node())
                .end()
                .clone()
        });
        let expected = roots
            .into_iter()
            .map(|root| {
                (
                    root,
                    service.resolve_reference(root, &cancellation).unwrap(),
                )
            })
            .collect::<HashMap<_, _>>();
        let mut provider = Provider {
            dependencies: HashMap::from_iter([
                (endpoints[0].clone(), vec![roots[1], roots[1]]),
                (endpoints[1].clone(), vec![roots[2]]),
            ]),
            expected,
            discovered: HashSet::default(),
            closed: HashSet::default(),
            supplied: Vec::new(),
            discovery_completion: ResolutionCompletion::Complete,
            fail_close: false,
        };
        let mut operation = FactResolutionOperation::new(&service.source, &service, &cancellation);
        let Outcome::Ready(answer) = operation
            .resolve_reference_acyclic_with_provider(roots[0], &mut provider)
            .unwrap()
        else {
            panic!("finite acyclic ordinary prefix tasks must finish");
        };
        assert_eq!(answer, provider.expected[&roots[0]]);
        assert_eq!(provider.supplied, vec![roots[2], roots[1]]);
        assert_eq!(provider.discovered, provider.closed);
        assert!(!provider.discovered.contains(&endpoints[3]));

        let run_bounded = |duplicate_count: usize, limit: usize| {
            let token = CancellationToken::new();
            let session = ResolutionSession::bounded(
                ReceiverAnalysisBudget {
                    max_scope_nodes: limit,
                    max_summary_expansions: usize::MAX,
                    ..ReceiverAnalysisBudget::default()
                },
                Some(&token),
            );
            let mut bounded_provider = Provider {
                dependencies: HashMap::from_iter([
                    (endpoints[0].clone(), vec![roots[1]; duplicate_count]),
                    (endpoints[1].clone(), vec![roots[2]]),
                ]),
                expected: provider.expected.clone(),
                discovered: HashSet::default(),
                closed: HashSet::default(),
                supplied: Vec::new(),
                discovery_completion: ResolutionCompletion::Complete,
                fail_close: false,
            };
            let mut operation =
                FactResolutionOperation::new_bounded_with_callable_static_import_boundaries(
                    &service.source,
                    &service,
                    &[],
                    session.cancellation().unwrap(),
                    &session,
                );
            let outcome = operation
                .resolve_reference_acyclic_with_provider(roots[0], &mut bounded_provider)
                .unwrap();
            let complete = match outcome {
                Outcome::Ready(answer) => {
                    assert_eq!(answer, provider.expected[&roots[0]]);
                    assert_eq!(bounded_provider.supplied, vec![roots[2], roots[1]]);
                    true
                }
                Outcome::Cancelled(completion) => {
                    assert!(completion.contains_reason(ResolutionIncompleteReason::Cancelled));
                    false
                }
                Outcome::Unsupported(_) => panic!("acyclic ordinary fixture is supported"),
                Outcome::Unavailable { .. } => {
                    panic!("the complete fake source has no pending discovery")
                }
            };
            assert!(!token.is_cancelled());
            (complete, session.finish(()).work().scope_nodes)
        };
        let (complete, small_work) = run_bounded(2, usize::MAX);
        assert!(complete);
        let (complete, large_work) = run_bounded(258, usize::MAX);
        assert!(complete);
        assert_eq!(
            large_work - small_work,
            256,
            "duplicate plan rows are charged before deduplication"
        );
        assert_eq!(run_bounded(258, large_work), (true, large_work));
        assert_eq!(run_bounded(258, large_work - 1), (false, large_work - 1));

        provider
            .dependencies
            .insert(endpoints[1].clone(), vec![roots[0]]);
        provider.discovered.clear();
        provider.closed.clear();
        provider.supplied.clear();
        let mut operation = FactResolutionOperation::new(&service.source, &service, &cancellation);
        let Outcome::Unsupported(Unsupported::CyclicPrefixDependency {
            pending_roots,
            pending_endpoints,
            completion,
        }) = operation
            .resolve_reference_acyclic_with_provider(roots[0], &mut provider)
            .unwrap()
        else {
            panic!("dynamic dependency cycle must publish no experimental answer");
        };
        assert_eq!(pending_roots, roots[..2]);
        assert_eq!(pending_endpoints, endpoints[..2]);
        assert!(provider.closed.is_empty());
        // The cycle is named for exactly the roots it left unanswered and for
        // nothing else, so a caller can publish honest per-site evidence.
        for &root in &roots[..2] {
            assert!(
                completion
                    .contains_reason(ResolutionIncompleteReason::CyclicPrefixDependency(root))
            );
        }
        assert!(
            !completion
                .contains_reason(ResolutionIncompleteReason::CyclicPrefixDependency(roots[2]))
        );

        // Returned cancellation evidence is authoritative even when the
        // caller token is still live. No dependent root or relation closes.
        provider.discovered.clear();
        let reason = ResolutionIncompleteReason::UnsupportedSemantic(SemanticId::for_test(
            b"scheduler-discovery-cancel-evidence",
        ));
        provider.discovery_completion =
            ResolutionCompletion::incomplete([reason, ResolutionIncompleteReason::Cancelled]);
        let mut operation = FactResolutionOperation::new(&service.source, &service, &cancellation);
        let Outcome::Cancelled(completion) = operation
            .resolve_reference_acyclic_with_provider(roots[0], &mut provider)
            .unwrap()
        else {
            panic!("returned cancellation cannot publish a task prefix");
        };
        assert!(completion.contains_reason(reason));
        assert!(completion.contains_reason(ResolutionIncompleteReason::Cancelled));
        assert!(!cancellation.is_cancelled());
        assert_eq!(provider.discovered.len(), 1);
        assert!(provider.closed.is_empty());

        provider.discovered.clear();
        provider.dependencies.clear();
        provider.discovery_completion = ResolutionCompletion::Complete;
        provider.fail_close = true;
        let mut operation = FactResolutionOperation::new(&service.source, &service, &cancellation);
        let result = operation.resolve_reference_acyclic_with_provider(roots[0], &mut provider);
        assert!(
            matches!(result, Err(error) if error.to_string().contains("injected root materialization failure"))
        );
        assert!(provider.closed.is_empty());
    }

    /// One scheduler per reference batch.
    ///
    /// The oracle for every answer is the independent eager evaluator, and the
    /// oracle for the shared-prefix claim is the seed seam: a prefix that two
    /// roots share is admitted, seeded and evaluated once for the batch, so the
    /// batch reads one scalar prefix seed where two separate schedulers read
    /// two.
    #[test]
    fn demand_scheduler_batch_admits_shared_prefixes_and_duplicate_roots_once() {
        use super::{
            DemandBatchOutcome as BatchOutcome, DemandRootDiscovery as RootDiscovery,
            DemandRootPlan as RootPlan, DemandRootProvider as RootProvider,
        };

        struct Provider {
            dependencies: HashMap<EndpointSignature, Vec<SemanticId>>,
            discovered: HashSet<EndpointSignature>,
            closed: HashSet<EndpointSignature>,
        }
        impl RootProvider for Provider {
            fn discover(&mut self, endpoint: &EndpointSignature) -> StoreResult<RootDiscovery> {
                assert!(self.discovered.insert(endpoint.clone()));
                Ok(RootDiscovery::Ready(RootPlan {
                    prefixes: self.dependencies.get(endpoint).cloned().unwrap_or_default(),
                    completion: ResolutionCompletion::Complete,
                }))
            }

            fn close(
                &mut self,
                endpoint: &EndpointSignature,
                _inputs: &[(SemanticId, &FactResolutionAnswer)],
            ) -> StoreResult<ResolutionCompletion> {
                assert!(self.closed.insert(endpoint.clone()));
                Ok(ResolutionCompletion::Complete)
            }
        }

        let facts = single_unqualified_reverse_facts();
        let owners = [b"batch-a", b"batch-b", b"batch-c", b"batch-d"]
            .map(|owner| BindingFragmentId::for_test(owner.as_slice()));
        let lexical = owners.map(|owner| {
            crate::analyzer::resolution::lower_for_test(owner, Language::Java, &facts)
                .lexical()
                .clone()
        });
        let roots = lexical.each_ref().map(|fragment| {
            lowered_semantic_at(
                fragment,
                ResolutionSiteId::new(1),
                LoweredSemanticRole::Reference,
            )
        });
        let typed = owners.map(|owner| {
            crate::analyzer::resolution::lower_for_test(owner, Language::Java, &facts)
                .typed()
                .clone()
        });
        let service = PreloadedFactResolutionService::from_lowered_fragments(lexical, typed);
        let cancellation = CancellationToken::new();
        let endpoints = roots.map(|root| {
            let seed = service
                .source
                .reference_seed(ResolutionQuery::new(root), &cancellation)
                .unwrap()
                .unwrap();
            crate::analyzer::resolution::engine::identity_path(seed.node())
                .end()
                .clone()
        });
        // Both roots of the batch below depend on the same prefix reference.
        let dependencies = HashMap::from_iter([
            (endpoints[0].clone(), vec![roots[2]]),
            (endpoints[1].clone(), vec![roots[2]]),
        ]);
        let expected = roots
            .into_iter()
            .map(|root| {
                (
                    root,
                    service.resolve_reference(root, &cancellation).unwrap(),
                )
            })
            .collect::<HashMap<_, _>>();
        let new_provider = || Provider {
            dependencies: dependencies.clone(),
            discovered: HashSet::default(),
            closed: HashSet::default(),
        };

        // One scheduler for the two roots: one batched seed read covering both
        // roots, and one scalar seed read for the single shared prefix task.
        let batched_source = ObservedBatchSource::new(&service.source);
        let mut provider = new_provider();
        let mut batch_metrics = ResolutionBatchMetrics::default();
        let mut operation = FactResolutionOperation::new(&batched_source, &service, &cancellation);
        let BatchOutcome::Ready(resolutions) = operation
            .resolve_reference_batch_acyclic_with_provider(
                &[roots[0], roots[1]],
                &mut provider,
                &mut batch_metrics,
            )
            .unwrap()
        else {
            panic!("a finite acyclic batch must finish");
        };
        assert_eq!(resolutions.len(), 2);
        assert_eq!(resolutions[0].answer, expected[&roots[0]]);
        assert_eq!(resolutions[1].answer, expected[&roots[1]]);
        assert_eq!(batched_source.reference_seed_batch_lookups.get(), 1);
        assert_eq!(*batched_source.reference_seed_batch_sizes.borrow(), vec![2]);
        assert_eq!(
            batched_source.reference_seed_lookups.get(),
            1,
            "the shared prefix task is admitted and seeded once for the batch"
        );
        assert_eq!(
            *batched_source.reference_seed_queries.borrow(),
            vec![roots[2]]
        );
        assert_eq!(provider.closed, provider.discovered);

        // The same two roots through the one-root route, for comparison: two
        // schedulers, two batched reads, and the shared prefix seeded twice.
        let scalar_source = ObservedBatchSource::new(&service.source);
        let mut root_metrics = Vec::new();
        for &root in &[roots[0], roots[1]] {
            let mut provider = new_provider();
            let mut metrics = ResolutionBatchMetrics::default();
            let mut operation =
                FactResolutionOperation::new(&scalar_source, &service, &cancellation);
            let BatchOutcome::Ready(resolutions) = operation
                .resolve_reference_batch_acyclic_with_provider(&[root], &mut provider, &mut metrics)
                .unwrap()
            else {
                panic!("a finite acyclic root must finish");
            };
            assert_eq!(resolutions[0].answer, expected[&root]);
            assert!(
                metrics.reference_seeds() > 0,
                "a one-root scheduler still charges its own prefix to the batch"
            );
            root_metrics.push(resolutions[0].metrics);
        }
        assert_eq!(scalar_source.reference_seed_batch_lookups.get(), 2);
        assert_eq!(
            *scalar_source.reference_seed_batch_sizes.borrow(),
            vec![1, 1]
        );
        assert_eq!(scalar_source.reference_seed_lookups.get(), 2);
        assert_eq!(
            *scalar_source.reference_seed_queries.borrow(),
            vec![roots[2], roots[2]],
            "separate schedulers re-seed the prefix they share"
        );

        // Attribution: each root's answer carries its own frames, and the
        // shared prefix's frames are the batch's. The prefix task resolved on
        // its own is the oracle for the batch total.
        for (position, metrics) in root_metrics.iter().enumerate() {
            assert_eq!(
                resolutions[position].metrics.reference_seeds(),
                metrics.reference_seeds(),
                "a root's metrics are its own frames in a batch and alone"
            );
        }
        let prefix_alone_source = ObservedBatchSource::new(&service.source);
        let mut prefix_provider = new_provider();
        let mut prefix_batch_metrics = ResolutionBatchMetrics::default();
        let mut operation =
            FactResolutionOperation::new(&prefix_alone_source, &service, &cancellation);
        let BatchOutcome::Ready(prefix_alone) = operation
            .resolve_reference_batch_acyclic_with_provider(
                &[roots[2]],
                &mut prefix_provider,
                &mut prefix_batch_metrics,
            )
            .unwrap()
        else {
            panic!("the prefix reference resolves on its own");
        };
        assert!(prefix_alone[0].metrics.reference_seeds() > 0);
        assert_eq!(
            batch_metrics.reference_seeds(),
            prefix_alone[0].metrics.reference_seeds(),
            "the shared prefix's frames are the batch's, not any root's"
        );

        // Two input positions naming one reference share one task, so the
        // duplicated batch does exactly the work the single root does and both
        // positions get that one task's answer.
        let run_duplicate = |positions: &[SemanticId]| {
            let source = ObservedBatchSource::new(&service.source);
            let mut provider = Provider {
                dependencies: HashMap::default(),
                discovered: HashSet::default(),
                closed: HashSet::default(),
            };
            let mut metrics = ResolutionBatchMetrics::default();
            let mut operation = FactResolutionOperation::new(&source, &service, &cancellation);
            let BatchOutcome::Ready(resolutions) = operation
                .resolve_reference_batch_acyclic_with_provider(
                    positions,
                    &mut provider,
                    &mut metrics,
                )
                .unwrap()
            else {
                panic!("a duplicated root must finish");
            };
            assert_eq!(
                metrics,
                ResolutionBatchMetrics::default(),
                "a batch with no shared prefix has no shared work"
            );
            (
                resolutions,
                provider.discovered,
                source.reference_seed_batch_lookups.get(),
                source.reference_seed_batch_sizes.borrow().clone(),
                source.reference_seed_lookups.get(),
            )
        };
        let single = run_duplicate(&[roots[3]]);
        let duplicated = run_duplicate(&[roots[3], roots[3]]);
        assert_eq!(single.0.len(), 1);
        assert_eq!(single.0[0].answer, expected[&roots[3]]);
        assert_eq!(duplicated.0.len(), 2);
        assert_eq!(duplicated.0[0].answer, single.0[0].answer);
        assert_eq!(duplicated.0[1].answer, single.0[0].answer);
        assert_eq!(duplicated.0[1].metrics, duplicated.0[0].metrics);
        assert_eq!(
            (duplicated.1, duplicated.2, duplicated.3, duplicated.4),
            (single.1, single.2, single.3, single.4),
            "a duplicate root is one query, one task and one set of reads"
        );
    }

    /// One answer with the numbers its operation minted for itself replaced.
    ///
    /// A qualified origin the operation minted is numbered in the order the
    /// operation met it, so when several origins prove one member reference,
    /// the number the witness names follows the read order: it moves with the
    /// scheduler's batch width, and it moves again when a second task takes a
    /// memoized answer instead of minting its own. The number drops with its
    /// operation and names nothing outside it, so a comparison of two runs
    /// replaces it and compares everything else exactly: every target,
    /// completion, projection and node step, and the position and outcome of
    /// the replaced step.
    fn operation_minted_invariant(answer: &FactResolutionAnswer) -> FactResolutionAnswer {
        let mut answer = answer.clone();
        let (targets, witnesses, completion) = answer.binding.clone().into_parts();
        let witnesses = witnesses
            .into_vec()
            .into_iter()
            .map(|witness| {
                let (reference, target, steps, completion) = witness.into_parts();
                let steps = steps
                    .into_vec()
                    .into_iter()
                    .map(|step| match step {
                        WitnessStep::Candidate { semantic, outcome }
                            if semantic.operation_local_number().is_some() =>
                        {
                            WitnessStep::Candidate {
                                semantic: SemanticId::operation_local(0),
                                outcome,
                            }
                        }
                        step => step,
                    })
                    .collect::<Vec<_>>();
                ResolutionWitness::new(reference, target, steps, completion)
            })
            .collect::<Vec<_>>();
        answer.binding = ResolutionAnswer::new(targets, witnesses, completion);
        answer
    }

    /// The operation's memo of demanded-reference answers.
    ///
    /// Two root tasks that demand the same reference evaluate it once. The
    /// oracle for the memoized answer is the same reference resolved with the
    /// memo unavailable, so a hit cannot quietly answer something else. The
    /// key is the reference and the selection, so a source that names a
    /// different scope misses, and a cancelled result is never published at
    /// all.
    #[test]
    fn demand_reference_memo_serves_a_second_task_and_only_its_own_selection() {
        use super::{
            DemandBatchOutcome as BatchOutcome, DemandRootDiscovery as RootDiscovery,
            DemandRootProvider as RootProvider,
        };

        struct Provider {
            cancel_after: Option<usize>,
            discoveries: usize,
        }
        impl RootProvider for Provider {
            fn discover(&mut self, _endpoint: &EndpointSignature) -> StoreResult<RootDiscovery> {
                self.discoveries += 1;
                if self
                    .cancel_after
                    .is_some_and(|limit| self.discoveries > limit)
                {
                    return Ok(RootDiscovery::Cancelled(ResolutionCompletion::incomplete(
                        [ResolutionIncompleteReason::Cancelled],
                    )));
                }
                Ok(RootDiscovery::AlreadyReady {
                    completion: ResolutionCompletion::Complete,
                })
            }

            fn close(
                &mut self,
                _endpoint: &EndpointSignature,
                _inputs: &[(SemanticId, &FactResolutionAnswer)],
            ) -> StoreResult<ResolutionCompletion> {
                panic!("an already-ready endpoint closes no selected relation");
            }
        }

        // Two callers of one helper: each root demands the helper's reference,
        // so the second root is what the memo has to serve.
        let source = "public class Fixture {\
            public static class A { public int x; }\
            public int first(A a) { return a.x; }\
            public int second(A a) { return a.x; }\
        }";
        let fixture = parsed_java_service_fixture(source, b"demand-reference-memo");
        let cancellation = CancellationToken::new();
        let references = {
            let mut references = Vec::new();
            fixture
                .service
                .source
                .visit_reference_seed_batches(
                    MAX_REFERENCE_SEEDS_PER_BATCH,
                    &cancellation,
                    &mut |batch| {
                        references.extend(batch.seeds().iter().map(ReferenceSeed::reference));
                        Ok(true)
                    },
                )
                .unwrap();
            references
        };
        assert!(
            references.len() > 4,
            "the fixture demands several references"
        );

        let resolve = |roots: &[SemanticId], authority: Option<SeedReadAuthority>| {
            let mut observed = ObservedBatchSource::new(&fixture.service.source);
            observed.selection_authority = authority;
            let mut provider = Provider {
                cancel_after: None,
                discoveries: 0,
            };
            let mut metrics = ResolutionBatchMetrics::default();
            let mut operation =
                FactResolutionOperation::new(&observed, &fixture.service, &cancellation);
            let BatchOutcome::Ready(resolutions) = operation
                .resolve_reference_batch_acyclic_with_provider(roots, &mut provider, &mut metrics)
                .unwrap()
            else {
                panic!("the complete fixture resolves every root");
            };
            let answers = resolutions
                .into_iter()
                .map(|resolution| resolution.answer)
                .collect::<Vec<_>>();
            let memo = operation
                .forward_candidate_artifacts
                .demanded_reference_entries();
            (
                answers,
                observed.demanded_reference_seed_queries().len(),
                observed.forward_match_calls.get(),
                memo,
            )
        };

        let normalize = |answers: &[FactResolutionAnswer]| {
            answers
                .iter()
                .map(operation_minted_invariant)
                .collect::<Vec<_>>()
        };

        // One root at a time, each in its own operation: nothing is shared, so
        // this is what every reference costs when it is evaluated from cold.
        let mut cold_answers = Vec::new();
        let mut cold_seed_reads = 0;
        let mut cold_match_reads = 0;
        for &root in &references {
            let (answers, seed_reads, match_reads, memo) = resolve(&[root], None);
            assert_eq!(memo, 0, "a source that names no selection memoizes nothing");
            cold_answers.extend(answers);
            cold_seed_reads += seed_reads;
            cold_match_reads += match_reads;
        }

        // The same roots in one operation that does name its selection: the
        // answers are the same and the repeated demanded references are read
        // once instead of once per task.
        let (shared_answers, shared_seed_reads, shared_match_reads, shared_memo) =
            resolve(&references, Some(PRELOADED_FIXTURE_AUTHORITY));
        assert_eq!(normalize(&shared_answers), normalize(&cold_answers));
        assert!(shared_memo > 0, "the shared run memoized something");
        assert!(
            shared_seed_reads < cold_seed_reads,
            "the memo removed demanded seed reads: {shared_seed_reads} against {cold_seed_reads}"
        );
        assert!(
            shared_match_reads < cold_match_reads,
            "the memo removed the candidate reads behind them: \
             {shared_match_reads} against {cold_match_reads}"
        );

        // The key carries the selection, so a source claiming a different
        // scope shares nothing with the run above even inside one process.
        let other_scope = SeedReadAuthority {
            scope: [0xa5; 32],
            ..PRELOADED_FIXTURE_AUTHORITY
        };
        let (other_answers, other_seed_reads, _, other_memo) =
            resolve(&references, Some(other_scope));
        assert_eq!(normalize(&other_answers), normalize(&cold_answers));
        assert_eq!(other_memo, shared_memo);
        assert_eq!(
            other_seed_reads, shared_seed_reads,
            "one operation's memo is keyed the same way whatever the scope is"
        );

        // A scheduler the provider stops publishes nothing to the memo: the
        // answers it would have published are the cancelled empty ones.
        let mut observed = ObservedBatchSource::new(&fixture.service.source);
        observed.selection_authority = Some(PRELOADED_FIXTURE_AUTHORITY);
        let mut provider = Provider {
            cancel_after: Some(0),
            discoveries: 0,
        };
        let mut metrics = ResolutionBatchMetrics::default();
        let mut operation =
            FactResolutionOperation::new(&observed, &fixture.service, &cancellation);
        let outcome = operation
            .resolve_reference_batch_acyclic_with_provider(&references, &mut provider, &mut metrics)
            .unwrap();
        assert!(
            matches!(outcome, BatchOutcome::Cancelled(completion)
                if completion.contains_reason(ResolutionIncompleteReason::Cancelled)),
            "a stopped discovery cancels the batch"
        );
        assert_eq!(
            operation
                .forward_candidate_artifacts
                .demanded_reference_entries(),
            0,
            "a cancelled run publishes no memo entry"
        );
        assert!(!cancellation.is_cancelled());
    }

    /// One scheduler round reads every frame's keys in one statement set.
    ///
    /// The frames of a round ask the same three keyed statements for their own
    /// one or two keys. A round reads the deduplicated union once and each
    /// frame takes its own keys from it, so the oracle for both halves is the
    /// same roots resolved one at a time, each in its own operation: the
    /// answers must be equal, and each root's own frame metrics, which are
    /// exactly the quantities the budget charges per frame, must be equal too.
    ///
    /// The source names no selection here, so the operation's demanded
    /// reference memo is off and the only difference between the two runs is
    /// how the reads were issued.
    #[test]
    fn a_merged_scheduler_round_reads_every_frames_keys_in_one_statement_set() {
        use super::{
            DemandBatchOutcome as BatchOutcome, DemandRootDiscovery as RootDiscovery,
            DemandRootProvider as RootProvider,
        };

        struct Provider;
        impl RootProvider for Provider {
            fn discover(&mut self, _endpoint: &EndpointSignature) -> StoreResult<RootDiscovery> {
                Ok(RootDiscovery::AlreadyReady {
                    completion: ResolutionCompletion::Complete,
                })
            }

            fn close(
                &mut self,
                _endpoint: &EndpointSignature,
                _inputs: &[(SemanticId, &FactResolutionAnswer)],
            ) -> StoreResult<ResolutionCompletion> {
                panic!("an already-ready endpoint closes no selected relation");
            }
        }

        let source = "public class Fixture {\
            public static class A { public int x; public int y; }\
            public int first(A a) { return a.x + a.y; }\
            public int second(A a) { return a.y + a.x; }\
            public int third(A a) { return a.x; }\
        }";
        let fixture = parsed_java_service_fixture(source, b"merged-scheduler-round");
        let cancellation = CancellationToken::new();
        let references = {
            let mut references = Vec::new();
            fixture
                .service
                .source
                .visit_reference_seed_batches(
                    MAX_REFERENCE_SEEDS_PER_BATCH,
                    &cancellation,
                    &mut |batch| {
                        references.extend(batch.seeds().iter().map(ReferenceSeed::reference));
                        Ok(true)
                    },
                )
                .unwrap();
            references
        };
        assert!(references.len() > 4, "the fixture demands several roots");

        struct Run {
            answers: Vec<FactResolutionAnswer>,
            metrics: Vec<ResolutionBatchMetrics>,
            match_calls: usize,
            widest_match_request: usize,
            classification_calls: usize,
            widest_classification_request: usize,
            hydration_calls: usize,
            widest_hydration_request: usize,
        }
        let run = |roots: &[SemanticId]| {
            let mut observed = ObservedBatchSource::new(&fixture.service.source);
            observed.selection_authority = None;
            let mut metrics = ResolutionBatchMetrics::default();
            let mut operation =
                FactResolutionOperation::new(&observed, &fixture.service, &cancellation);
            let BatchOutcome::Ready(resolutions) = operation
                .resolve_reference_batch_acyclic_with_provider(roots, &mut Provider, &mut metrics)
                .unwrap()
            else {
                panic!("the complete fixture resolves every root");
            };
            fn widest<T>(requests: &[Vec<T>]) -> usize {
                requests.iter().map(Vec::len).max().unwrap_or(0)
            }
            Run {
                match_calls: observed.forward_match_calls.get(),
                widest_match_request: widest(&observed.forward_match_requests.borrow()),
                classification_calls: observed.endpoint_classification_calls.get(),
                widest_classification_request: widest(
                    &observed.endpoint_classification_requests.borrow(),
                ),
                hydration_calls: observed.path_hydration_calls.get(),
                widest_hydration_request: widest(&observed.path_hydration_requests.borrow()),
                metrics: resolutions
                    .iter()
                    .map(|resolution| resolution.metrics)
                    .collect(),
                answers: resolutions
                    .into_iter()
                    .map(|resolution| resolution.answer)
                    .collect(),
            }
        };
        let normalize = |answers: &[FactResolutionAnswer]| {
            answers
                .iter()
                .map(operation_minted_invariant)
                .collect::<Vec<_>>()
        };

        let alone = references
            .iter()
            .map(|&root| run(&[root]))
            .collect::<Vec<_>>();
        let merged = run(&references);

        assert_eq!(
            normalize(&merged.answers),
            normalize(
                &alone
                    .iter()
                    .map(|run| run.answers[0].clone())
                    .collect::<Vec<_>>()
            ),
            "a merged round hands every frame exactly its own rows"
        );
        for (position, run) in alone.iter().enumerate() {
            assert_eq!(
                merged.metrics[position], run.metrics[0],
                "a root's own frames, and so its own budget charges, are the same merged or not"
            );
        }

        let alone_match_calls = alone.iter().map(|run| run.match_calls).sum::<usize>();
        let alone_classification_calls = alone
            .iter()
            .map(|run| run.classification_calls)
            .sum::<usize>();
        let alone_hydration_calls = alone.iter().map(|run| run.hydration_calls).sum::<usize>();
        let alone_widest_match = alone
            .iter()
            .map(|run| run.widest_match_request)
            .max()
            .unwrap_or(0);
        let alone_widest_classification = alone
            .iter()
            .map(|run| run.widest_classification_request)
            .max()
            .unwrap_or(0);
        let alone_widest_hydration = alone
            .iter()
            .map(|run| run.widest_hydration_request)
            .max()
            .unwrap_or(0);
        assert!(
            merged.widest_match_request > alone_widest_match
                && merged.widest_classification_request > alone_widest_classification
                && merged.widest_hydration_request > alone_widest_hydration,
            "a merged round asks each statement for more than one frame's keys: \
             candidate {} against {}, classification {} against {}, \
             hydration {} against {}",
            merged.widest_match_request,
            alone_widest_match,
            merged.widest_classification_request,
            alone_widest_classification,
            merged.widest_hydration_request,
            alone_widest_hydration
        );
        assert!(
            merged.match_calls < alone_match_calls
                && merged.classification_calls < alone_classification_calls
                && merged.hydration_calls < alone_hydration_calls,
            "a merged round issues fewer statements: candidate {} against {}, \
             classification {} against {}, hydration {} against {}",
            merged.match_calls,
            alone_match_calls,
            merged.classification_calls,
            alone_classification_calls,
            merged.hydration_calls,
            alone_hydration_calls
        );
    }

    /// A frame whose endpoints are not closed is left out of the merged read.
    ///
    /// Readiness stays per frame: the round collects the keys of the frames
    /// that are ready for them and polls the rest unchanged, so a gated
    /// endpoint cannot reach the source before its relation closes. The gated
    /// root is re-queued and still answers exactly what it answers alone.
    #[test]
    fn a_merged_round_leaves_out_the_frame_whose_endpoints_are_not_closed() {
        use super::{
            DemandBatchOutcome as BatchOutcome, DemandRootDiscovery as RootDiscovery,
            DemandRootPlan as RootPlan, DemandRootProvider as RootProvider,
        };

        struct Provider<'a, 'b> {
            observed: &'b ObservedBatchSource<'a>,
            gated: EndpointSignature,
            prefix: SemanticId,
            closed: HashSet<EndpointSignature>,
        }
        impl RootProvider for Provider<'_, '_> {
            fn discover(&mut self, endpoint: &EndpointSignature) -> StoreResult<RootDiscovery> {
                Ok(RootDiscovery::Ready(RootPlan {
                    prefixes: if *endpoint == self.gated {
                        vec![self.prefix]
                    } else {
                        Vec::new()
                    },
                    completion: ResolutionCompletion::Complete,
                }))
            }

            fn close(
                &mut self,
                endpoint: &EndpointSignature,
                _inputs: &[(SemanticId, &FactResolutionAnswer)],
            ) -> StoreResult<ResolutionCompletion> {
                if *endpoint == self.gated {
                    assert!(
                        !self
                            .observed
                            .forward_match_requests
                            .borrow()
                            .iter()
                            .any(|requests| requests.contains(&self.gated)),
                        "no read carries a gated endpoint before its relation closes"
                    );
                }
                assert!(self.closed.insert(endpoint.clone()));
                Ok(ResolutionCompletion::Complete)
            }
        }

        let facts = single_unqualified_reverse_facts();
        let owners = [b"gated-a", b"gated-b", b"gated-c", b"gated-d"]
            .map(|owner| BindingFragmentId::for_test(owner.as_slice()));
        let lexical = owners.map(|owner| {
            crate::analyzer::resolution::lower_for_test(owner, Language::Java, &facts)
                .lexical()
                .clone()
        });
        let roots = lexical.each_ref().map(|fragment| {
            lowered_semantic_at(
                fragment,
                ResolutionSiteId::new(1),
                LoweredSemanticRole::Reference,
            )
        });
        let typed = owners.map(|owner| {
            crate::analyzer::resolution::lower_for_test(owner, Language::Java, &facts)
                .typed()
                .clone()
        });
        let service = PreloadedFactResolutionService::from_lowered_fragments(lexical, typed);
        let cancellation = CancellationToken::new();
        let endpoints = roots.map(|root| {
            let seed = service
                .source
                .reference_seed(ResolutionQuery::new(root), &cancellation)
                .unwrap()
                .unwrap();
            crate::analyzer::resolution::engine::identity_path(seed.node())
                .end()
                .clone()
        });

        let expected = service.resolve_reference(roots[0], &cancellation).unwrap();
        let observed = ObservedBatchSource::new(&service.source);
        let mut provider = Provider {
            observed: &observed,
            gated: endpoints[0].clone(),
            prefix: roots[3],
            closed: HashSet::default(),
        };
        let mut metrics = ResolutionBatchMetrics::default();
        let mut operation = FactResolutionOperation::new(&observed, &service, &cancellation);
        let BatchOutcome::Ready(resolutions) = operation
            .resolve_reference_batch_acyclic_with_provider(
                &[roots[0], roots[1], roots[2]],
                &mut provider,
                &mut metrics,
            )
            .unwrap()
        else {
            panic!("a finite acyclic batch must finish");
        };
        assert!(provider.closed.contains(&endpoints[0]), "the gate closed");
        assert_eq!(
            resolutions[0].answer, expected,
            "the re-queued root answers what it answers alone"
        );
    }

    /// A cancelled merged read publishes nothing and loses no evidence.
    ///
    /// The round's read is not any frame's answer: when it observes
    /// cancellation it publishes no artifact, so every participating frame
    /// reads and retains its own evidence exactly as it does unmerged, and no
    /// frame's answer is built from another frame's partial read.
    #[test]
    fn a_cancelled_merged_round_read_publishes_no_artifact() {
        use super::{
            DemandBatchOutcome as BatchOutcome, DemandRootDiscovery as RootDiscovery,
            DemandRootProvider as RootProvider,
        };

        struct Provider;
        impl RootProvider for Provider {
            fn discover(&mut self, _endpoint: &EndpointSignature) -> StoreResult<RootDiscovery> {
                Ok(RootDiscovery::AlreadyReady {
                    completion: ResolutionCompletion::Complete,
                })
            }

            fn close(
                &mut self,
                _endpoint: &EndpointSignature,
                _inputs: &[(SemanticId, &FactResolutionAnswer)],
            ) -> StoreResult<ResolutionCompletion> {
                panic!("an already-ready endpoint closes no selected relation");
            }
        }

        let source = "public class Fixture {\
            public static class A { public int x; public int y; }\
            public int first(A a) { return a.x + a.y; }\
            public int second(A a) { return a.y + a.x; }\
        }";
        let fixture = parsed_java_service_fixture(source, b"cancelled-merged-round");
        let cancellation = CancellationToken::new();
        let references = {
            let mut references = Vec::new();
            fixture
                .service
                .source
                .visit_reference_seed_batches(
                    MAX_REFERENCE_SEEDS_PER_BATCH,
                    &cancellation,
                    &mut |batch| {
                        references.extend(batch.seeds().iter().map(ReferenceSeed::reference));
                        Ok(true)
                    },
                )
                .unwrap();
            references
        };
        let reason = references[0];
        let observed = ObservedBatchSource::cancelling_after_incomplete_forward_match(
            &fixture.service.source,
            reason,
        );
        let mut metrics = ResolutionBatchMetrics::default();
        let mut operation =
            FactResolutionOperation::new(&observed, &fixture.service, &cancellation);
        let outcome = operation
            .resolve_reference_batch_acyclic_with_provider(&references, &mut Provider, &mut metrics)
            .unwrap();
        let BatchOutcome::Cancelled(completion) = outcome else {
            panic!("a source that cancels its first candidate read cancels the batch");
        };
        assert!(
            completion.contains_reason(ResolutionIncompleteReason::Cancelled),
            "the cancelled batch carries the stop"
        );
        assert!(
            completion.contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(reason)),
            "the evidence the cancelled read returned is retained: {completion:?}"
        );
        let (endpoint_matches, hydrated_paths, _) =
            operation.forward_candidate_artifacts.artifact_counts();
        assert_eq!(
            (endpoint_matches, hydrated_paths),
            (0, 0),
            "a cancelled read publishes no candidate or hydration artifact"
        );
        assert!(cancellation.is_cancelled());
    }

    /// Two tasks that want one demanded reference at the same time evaluate it
    /// once.
    ///
    /// The operation's memo answers a second task only once the first has
    /// finished the reference, so tasks that reach it together both miss. The
    /// scheduler now makes the second wait for the first, and the oracle for
    /// what it then gets is the same roots resolved one at a time. With the
    /// memo off the waiter still wakes and evaluates the reference itself,
    /// which is what every task did before the wait existed.
    #[test]
    fn demand_reference_memo_makes_the_second_task_wait_for_the_first_to_finish() {
        use super::{
            DemandBatchOutcome as BatchOutcome, DemandRootDiscovery as RootDiscovery,
            DemandRootProvider as RootProvider,
        };

        struct Provider;
        impl RootProvider for Provider {
            fn discover(&mut self, _endpoint: &EndpointSignature) -> StoreResult<RootDiscovery> {
                Ok(RootDiscovery::AlreadyReady {
                    completion: ResolutionCompletion::Complete,
                })
            }

            fn close(
                &mut self,
                _endpoint: &EndpointSignature,
                _inputs: &[(SemanticId, &FactResolutionAnswer)],
            ) -> StoreResult<ResolutionCompletion> {
                panic!("an already-ready endpoint closes no selected relation");
            }
        }

        let source = "public class Fixture {\
            public static class A { public int x; }\
            public int first(A a) { return a.x; }\
            public int second(A a) { return a.x; }\
            public int third(A a) { return a.x; }\
        }";
        let fixture = parsed_java_service_fixture(source, b"demanded-reference-wait");
        let cancellation = CancellationToken::new();
        let references = {
            let mut references = Vec::new();
            fixture
                .service
                .source
                .visit_reference_seed_batches(
                    MAX_REFERENCE_SEEDS_PER_BATCH,
                    &cancellation,
                    &mut |batch| {
                        references.extend(batch.seeds().iter().map(ReferenceSeed::reference));
                        Ok(true)
                    },
                )
                .unwrap();
            references
        };
        assert!(references.len() > 4, "the fixture demands several roots");

        let resolve = |roots: &[SemanticId], authority: Option<SeedReadAuthority>| {
            let mut observed = ObservedBatchSource::new(&fixture.service.source);
            observed.selection_authority = authority;
            let mut metrics = ResolutionBatchMetrics::default();
            let mut operation =
                FactResolutionOperation::new(&observed, &fixture.service, &cancellation);
            let BatchOutcome::Ready(resolutions) = operation
                .resolve_reference_batch_acyclic_with_provider(roots, &mut Provider, &mut metrics)
                .unwrap()
            else {
                panic!("the complete fixture resolves every root");
            };
            (
                resolutions
                    .into_iter()
                    .map(|resolution| resolution.answer)
                    .collect::<Vec<_>>(),
                observed.demanded_reference_seed_queries(),
            )
        };
        let normalize = |answers: &[FactResolutionAnswer]| {
            answers
                .iter()
                .map(operation_minted_invariant)
                .collect::<Vec<_>>()
        };

        let cold = references
            .iter()
            .map(|&root| resolve(&[root], None).0.remove(0))
            .collect::<Vec<_>>();

        let (shared_answers, shared_queries) =
            resolve(&references, Some(PRELOADED_FIXTURE_AUTHORITY));
        assert_eq!(normalize(&shared_answers), normalize(&cold));
        let mut distinct = shared_queries.clone();
        distinct.sort_unstable();
        distinct.dedup();
        assert_eq!(
            distinct.len(),
            shared_queries.len(),
            "a demanded reference is seeded once for the operation: {shared_queries:?}"
        );

        // With the memo off nothing the first task finishes can serve the
        // second, so every waiter wakes and evaluates the reference itself.
        let (unmemoized_answers, unmemoized_queries) = resolve(&references, None);
        assert_eq!(normalize(&unmemoized_answers), normalize(&cold));
        assert!(
            unmemoized_queries.len() > shared_queries.len(),
            "a woken waiter proceeds as a miss: {unmemoized_queries:?} against {shared_queries:?}"
        );
    }

    /// A round whose typed closure demands several lexical references reads
    /// their seeds in one plural statement and evaluates them in one forward
    /// frame, and answers exactly what the eager evaluator answers, which
    /// takes the same references one at a time. The shared frame is charged
    /// one summary step per worklist round, not one per reference in it, so
    /// such a root costs fewer summary steps than the eager evaluation and
    /// every other root costs the same. The shared run then puts
    /// every reference in one scheduler, where one task's frame claims several
    /// references that other tasks are also about to demand: the answers stay
    /// the cold ones, and no demanded reference is read twice.
    #[test]
    fn a_rounds_lexical_demands_share_one_seed_read_and_one_frame() {
        use super::{
            DemandBatchOutcome as BatchOutcome, DemandRootDiscovery as RootDiscovery,
            DemandRootProvider as RootProvider,
        };

        struct Provider;
        impl RootProvider for Provider {
            fn discover(&mut self, _endpoint: &EndpointSignature) -> StoreResult<RootDiscovery> {
                Ok(RootDiscovery::AlreadyReady {
                    completion: ResolutionCompletion::Complete,
                })
            }

            fn close(
                &mut self,
                _endpoint: &EndpointSignature,
                _inputs: &[(SemanticId, &FactResolutionAnswer)],
            ) -> StoreResult<ResolutionCompletion> {
                panic!("an already-ready endpoint closes no selected relation");
            }
        }

        // Overload applicability types both arguments of the call, so the
        // call's first round demands `left` and `right` together, and the
        // next one the parameter types behind them.
        let source = "public class Fixture {\
            public static int pick(int x, String y) { return x; }\
            public static int pick(String x, int y) { return y; }\
            public int read(int left, String right) { return pick(left, right); }\
        }";
        let fixture = parsed_java_service_fixture(source, b"demanded-lexical-batch");
        let cancellation = CancellationToken::new();
        let mut references = Vec::new();
        fixture
            .service
            .source
            .visit_reference_seed_batches(
                MAX_REFERENCE_SEEDS_PER_BATCH,
                &cancellation,
                &mut |batch| {
                    references.extend(batch.seeds().iter().map(ReferenceSeed::reference));
                    Ok(true)
                },
            )
            .unwrap();

        let resolve = |roots: &[SemanticId], authority: Option<SeedReadAuthority>| {
            let mut observed = ObservedBatchSource::new(&fixture.service.source);
            observed.selection_authority = authority;
            let mut metrics = ResolutionBatchMetrics::default();
            let budget = ResolutionSession::bounded(
                ReceiverAnalysisBudget {
                    max_scope_nodes: usize::MAX,
                    max_summary_expansions: usize::MAX,
                    ..ReceiverAnalysisBudget::default()
                },
                Some(&cancellation),
            );
            let mut operation =
                FactResolutionOperation::new_bounded_with_callable_static_import_boundaries(
                    &observed,
                    &fixture.service,
                    &[],
                    &cancellation,
                    &budget,
                );
            let BatchOutcome::Ready(resolutions) = operation
                .resolve_reference_batch_acyclic_with_provider(roots, &mut Provider, &mut metrics)
                .unwrap()
            else {
                panic!("the complete fixture resolves every root");
            };
            let widths = observed
                .reference_seed_batch_sizes
                .borrow()
                .iter()
                .skip(1)
                .copied()
                .collect::<Vec<_>>();
            assert_eq!(
                observed.reference_seed_lookups.get(),
                0,
                "demanded references are read in plural"
            );
            (
                resolutions
                    .into_iter()
                    .map(|resolution| operation_minted_invariant(&resolution.answer))
                    .collect::<Vec<_>>(),
                widths,
                observed.demanded_reference_seed_queries(),
                budget.finish(()).work().summary_expansions,
            )
        };

        let mut widest = 0;
        let mut cold = Vec::new();
        for &root in &references {
            let (mut answers, widths, _, steps) = resolve(&[root], None);
            let eager_budget = ResolutionSession::bounded(
                ReceiverAnalysisBudget {
                    max_scope_nodes: usize::MAX,
                    max_summary_expansions: usize::MAX,
                    ..ReceiverAnalysisBudget::default()
                },
                Some(&cancellation),
            );
            let mut session = FactReadSession::from_split_sources_bounded(
                &fixture.service.source,
                &fixture.service,
                &[],
                &cancellation,
                &eager_budget,
            );
            let mut hierarchy = HierarchyOperationArena::default();
            let mut artifacts = ForwardCandidateArtifactCache::default();
            let eager = FactEvaluation::new_with_forward_artifacts(
                &mut session,
                &mut hierarchy,
                &mut artifacts,
                root,
            )
            .run()
            .unwrap();
            assert_eq!(answers[0], operation_minted_invariant(&eager), "{root:?}");
            // The eager evaluation opens one frame per demanded reference and
            // charges each its own summary step per worklist round. A shared
            // round is one expansion and is charged once, so a root whose
            // round batched several references costs fewer steps, and every
            // other root costs the same.
            let eager_steps = eager_budget.finish(()).work().summary_expansions;
            if widths.iter().any(|&width| width > 1) {
                assert!(
                    steps < eager_steps,
                    "{root:?}: widths {widths:?}, steps {steps}, eager {eager_steps}"
                );
            } else {
                assert_eq!(steps, eager_steps, "{root:?}: widths {widths:?}");
            }
            widest = widest.max(widths.iter().copied().max().unwrap_or(0));
            cold.push(answers.remove(0));
        }
        assert!(
            widest > 1,
            "some round reads several demanded references in one statement"
        );

        let (shared, _, queries, _) = resolve(&references, Some(PRELOADED_FIXTURE_AUTHORITY));
        assert_eq!(shared, cold);
        let mut distinct = queries.clone();
        distinct.sort_unstable();
        distinct.dedup();
        assert_eq!(
            distinct.len(),
            queries.len(),
            "a demanded reference is seeded once for the operation: {queries:?}"
        );
    }

    /// A round that demands no new slot reuses the slot structure the
    /// previous round read (`SlotPrep`). The oracle is the same evaluation
    /// with the reuse forced off: every root's answer, completion and
    /// projected frontiers are the same, over fixtures whose roots take
    /// several rounds (overloaded calls, generic results, member chains).
    #[test]
    fn reused_slot_structure_gives_the_from_scratch_answers() {
        let sources = [
            "public class Fixture {\
                public static int pick(int x, String y) { return x; }\
                public static int pick(String x, int y) { return y; }\
                public int read(int left, String right) { return pick(left, right); }\
            }",
            "class Box<T> { T value; T get() { return value; } }\
             class Item { int size() { return 1; } }\
             class Use { int run(Box<Item> box) { return box.get().size(); } }",
            "class A { B next() { return null; } }\
             class B { C next() { return null; } }\
             class C { int done() { return 0; } }\
             class Walk { int go(A a) { return a.next().next().done(); } }",
        ];
        for (index, source) in sources.iter().enumerate() {
            let fixture =
                parsed_java_service_fixture(source, format!("slot-prep-oracle-{index}").as_bytes());
            let cancellation = CancellationToken::new();
            let mut references = Vec::new();
            fixture
                .service
                .source
                .visit_reference_seed_batches(
                    MAX_REFERENCE_SEEDS_PER_BATCH,
                    &cancellation,
                    &mut |batch| {
                        references.extend(batch.seeds().iter().map(ReferenceSeed::reference));
                        Ok(true)
                    },
                )
                .unwrap();
            assert!(!references.is_empty(), "fixture {index} has references");
            let resolve = |off: bool| {
                SLOT_PREP_OFF_FOR_TEST.with(|flag| flag.set(off));
                let answers = references
                    .iter()
                    .map(|&reference| {
                        let mut operation = FactResolutionOperation::new(
                            &fixture.service.source,
                            &fixture.service,
                            &cancellation,
                        );
                        operation_minted_invariant(&operation.resolve_reference(reference).unwrap())
                    })
                    .collect::<Vec<_>>();
                SLOT_PREP_OFF_FOR_TEST.with(|flag| flag.set(false));
                answers
            };
            SLOT_PREP_REUSES.with(|reuses| reuses.set(0));
            let reused = resolve(false);
            assert!(
                SLOT_PREP_REUSES.with(std::cell::Cell::get) > 0,
                "fixture {index} reuses a slot structure"
            );
            assert_eq!(reused, resolve(true), "fixture {index}");
        }
    }

    #[test]
    fn qualified_supertype_eager_and_demand_preserve_the_same_field_owner() {
        struct Provider;
        impl DemandRootProvider for Provider {
            fn discover(
                &mut self,
                _endpoint: &EndpointSignature,
            ) -> StoreResult<DemandRootDiscovery> {
                Ok(DemandRootDiscovery::AlreadyReady {
                    completion: ResolutionCompletion::Complete,
                })
            }
            fn close(
                &mut self,
                _endpoint: &EndpointSignature,
                _inputs: &[(SemanticId, &FactResolutionAnswer)],
            ) -> StoreResult<ResolutionCompletion> {
                unreachable!("fixture source is already assembled")
            }
        }
        let source = "public class Fixture { public static class Outer { public static class Base { public int x; } } public static class Box extends Outer.Base {} public static class Use { public int f(Box probe) { return probe.x; } } }";
        let fixture = parsed_java_service_fixture(source, b"qualified-supertype-eager-demand");
        let reference = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Reference,
        )[0];
        let target = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let cancellation = CancellationToken::new();
        let mut eager =
            FactResolutionOperation::new(&fixture.service.source, &fixture.service, &cancellation);
        let eager = eager.resolve_reference(reference).unwrap();
        assert_eq!(eager.binding().targets(), &[target]);
        let mut demanded =
            FactResolutionOperation::new(&fixture.service.source, &fixture.service, &cancellation);
        let FactDemandResolution::Ready(demanded) = demanded
            .resolve_reference_by_demand(reference, &mut Provider)
            .unwrap()
        else {
            panic!("uncancelled assembled source must answer the field lookup");
        };
        assert_eq!(demanded.binding().targets(), &[target]);
        assert_eq!(
            operation_minted_invariant(&eager),
            operation_minted_invariant(&demanded)
        );
    }

    #[test]
    fn java_unqualified_inherited_type_eager_and_demand_agree() {
        use super::super::fact_source::{
            JavaInheritanceDeclaration, JavaInheritanceDeclarationKind,
        };
        struct Provider;
        impl DemandRootProvider for Provider {
            fn discover(
                &mut self,
                _endpoint: &EndpointSignature,
            ) -> StoreResult<DemandRootDiscovery> {
                Ok(DemandRootDiscovery::AlreadyReady {
                    completion: ResolutionCompletion::Complete,
                })
            }
            fn close(
                &mut self,
                _endpoint: &EndpointSignature,
                _inputs: &[(SemanticId, &FactResolutionAnswer)],
            ) -> StoreResult<ResolutionCompletion> {
                unreachable!("fixture source is already assembled")
            }
        }
        let source = "class Fixture { static class Base { static class Target {} } static class Box extends Base { Target field; } }";
        let mut fixture = parsed_java_service_fixture(source, b"java-inherited-type-parity");
        assert!(!fixture.lexical.hierarchy_terminals().is_empty());
        for &(reason, terminal) in fixture.lexical.hierarchy_terminals() {
            assert!(fixture.lexical.paths().iter().any(|(_, path)| {
                path.end().node() == terminal
                    && path
                        .completion()
                        .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(reason))
            }));
        }
        // Authored class declarations provide independent fixture metadata.
        // Do not infer class/interface kind from generic lowered type rows.
        for name in ["Fixture", "Base", "Target", "Box"] {
            let definitions = lowered_semantics_named(
                &fixture.facts,
                &fixture.lexical,
                name,
                ResolutionIdentifierRole::Declaration,
            );
            assert_eq!(definitions.len(), 1);
            let definition = definitions[0];
            fixture.service.java_inheritance_metadata.insert(
                definition,
                JavaInheritanceDeclaration {
                    definition,
                    package: Some(String::new()),
                    kind: JavaInheritanceDeclarationKind::Type {
                        is_interface: false,
                    },
                },
            );
        }
        let reference = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "Target",
            ResolutionIdentifierRole::Reference,
        )[0];
        let target = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "Target",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let cancellation = CancellationToken::new();
        let mut eager =
            FactResolutionOperation::new(&fixture.service.source, &fixture.service, &cancellation);
        let eager = eager.resolve_reference(reference).unwrap();
        assert_eq!(eager.binding().targets(), &[target], "{eager:?}");
        let raw = BatchResolutionEngine::new(&fixture.service.source)
            .resolve_reference(ResolutionQuery::new(reference), &cancellation)
            .unwrap();
        assert!(
            raw.targets().is_empty(),
            "fixture requires hierarchy replay"
        );
        let mut injected_session = preloaded_session(&fixture.service, &cancellation);
        let mut injected_hierarchy = HierarchyOperationArena::default();
        let metadata = fixture
            .service
            .source
            .reference_seed(ResolutionQuery::new(reference), &cancellation)
            .unwrap()
            .unwrap()
            .site_metadata();
        let injected = FactEvaluation::from_lexical_answer_with_site_metadata(
            &mut injected_session,
            &mut injected_hierarchy,
            reference,
            raw,
            metadata,
        )
        .run()
        .unwrap();
        assert_eq!(injected.binding().targets(), &[target], "{injected:?}");
        assert_eq!(
            operation_minted_invariant(&eager),
            operation_minted_invariant(&injected)
        );
        let mut demanded =
            FactResolutionOperation::new(&fixture.service.source, &fixture.service, &cancellation);
        let FactDemandResolution::Ready(demanded) = demanded
            .resolve_reference_by_demand(reference, &mut Provider)
            .unwrap()
        else {
            panic!("assembled inherited lookup must settle");
        };
        assert_eq!(demanded.binding().targets(), &[target], "{demanded:?}");
        assert_eq!(
            operation_minted_invariant(&eager),
            operation_minted_invariant(&demanded)
        );
    }

    #[test]
    fn java_unqualified_type_retires_the_implicit_object_frontier() {
        use super::super::fact_source::{
            JavaInheritanceDeclaration, JavaInheritanceDeclarationKind,
        };
        let source = "class Fixture { static class Target {} static class Base {} static class Box extends Base { Target field; } }";
        let mut fixture = parsed_java_service_fixture(source, b"java-inherited-type-frontier");
        let mut definitions = HashMap::default();
        for name in ["Fixture", "Base", "Target", "Box"] {
            let found = lowered_semantics_named(
                &fixture.facts,
                &fixture.lexical,
                name,
                ResolutionIdentifierRole::Declaration,
            );
            assert_eq!(found.len(), 1);
            let definition = found[0];
            definitions.insert(name, definition);
            fixture.service.java_inheritance_metadata.insert(
                definition,
                JavaInheritanceDeclaration {
                    definition,
                    package: Some(String::new()),
                    kind: JavaInheritanceDeclarationKind::Type {
                        is_interface: false,
                    },
                },
            );
        }
        let reason_for = |definition| {
            let reasons = fixture
                .typed
                .property_gaps()
                .iter()
                .filter(|gap| {
                    gap.definition() == definition
                        && gap.kind() == ResolutionGapKind::UnsupportedHierarchyTraversal
                })
                .map(|gap| ResolutionIncompleteReason::UnsupportedSemantic(gap.reason_semantic()))
                .collect::<Vec<_>>();
            assert_eq!(reasons.len(), 1);
            reasons[0]
        };
        let base_reason = reason_for(definitions["Base"]);
        let box_reason = reason_for(definitions["Box"]);
        let reference = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "Target",
            ResolutionIdentifierRole::Reference,
        )[0];
        let cancellation = CancellationToken::new();
        let mut operation =
            FactResolutionOperation::new(&fixture.service.source, &fixture.service, &cancellation);
        let answer = operation.resolve_reference(reference).unwrap();
        assert_eq!(
            answer.binding().targets(),
            &[definitions["Target"]],
            "{answer:?}"
        );
        // Box -> Base -> implicit java.lang.Object is sealed for member types:
        // Object declares methods only (JLS 4.3.2), so the inherited walk is an
        // exhaustive negative. This fixture installs no access policy, so the
        // enclosing Fixture.Target binds with exactly its own visibility gap.
        let target_visibility = fixture
            .typed
            .property_gaps()
            .iter()
            .filter(|gap| {
                gap.definition() == definitions["Target"]
                    && gap.kind() == ResolutionGapKind::UnsupportedVisibility
            })
            .map(|gap| ResolutionIncompleteReason::UnsupportedSemantic(gap.reason_semantic()))
            .collect::<Vec<_>>();
        assert_eq!(target_visibility.len(), 1);
        assert_eq!(
            answer.binding().completion(),
            &ResolutionCompletion::incomplete(target_visibility),
            "{answer:?}"
        );
        let ResolutionIncompleteReason::UnsupportedSemantic(base_gap) = base_reason else {
            unreachable!();
        };
        let ResolutionIncompleteReason::UnsupportedSemantic(box_gap) = box_reason else {
            unreachable!();
        };
        let base_terminal = fixture.service.typed.hierarchy_terminals[&base_gap];
        let box_terminal = fixture.service.typed.hierarchy_terminals[&box_gap];
        assert_ne!(base_terminal, box_terminal);
        let original = closed_endpoint(box_terminal, [reference]);
        let mut session = preloaded_session(&fixture.service, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut evaluation = FactEvaluation::new(&mut session, &mut hierarchy, reference);
        // This fixture deliberately has no selected access policy. Its final
        // answer keeps visibility uncertainty, so it is not a lookup certificate.
        // An unchanged hierarchy refinement must still preserve the whole value.
        let original_answer = Arc::new(answer.binding().clone());
        let mut answers = HashMap::default();
        answers.insert(reference, Arc::clone(&original_answer));
        assert!(
            evaluation
                .refine_type_reference_hierarchy_gaps(&mut answers)
                .unwrap()
        );
        assert!(Arc::ptr_eq(&answers[&reference], &original_answer));
        let reached = evaluation
            .java_inherited_frontier_endpoint(
                &original,
                &ResolutionCompletion::incomplete([base_reason]),
            )
            .unwrap()
            .unwrap();
        assert_eq!(reached.node(), base_terminal);
        assert_eq!(reached.symbols(), original.symbols());
        assert_eq!(reached.scopes(), original.scopes());
        // Two independent gaps do not describe one canonical pending request.
        assert_eq!(
            evaluation
                .java_inherited_frontier_endpoint(
                    &original,
                    &ResolutionCompletion::incomplete([base_reason, box_reason]),
                )
                .unwrap(),
            Some(original)
        );
    }

    #[test]
    fn qualified_supertype_eager_cycle_retains_incomplete_dependency_evidence() {
        let source = "class A extends Outer.B {} class Outer extends A {} class Use { int f(A probe) { return probe.Missing; } }";
        let fixture = parsed_java_service_fixture(source, b"qualified-supertype-eager-cycle");
        let reference = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "Missing",
            ResolutionIdentifierRole::Reference,
        )[0];
        let cancellation = CancellationToken::new();
        let mut operation =
            FactResolutionOperation::new(&fixture.service.source, &fixture.service, &cancellation);
        let answer = operation.resolve_reference(reference).unwrap();
        assert!(answer.binding().targets().is_empty());
        let ResolutionCompletion::Incomplete(reasons) = answer.completion() else {
            panic!("a cyclic superclass dependency cannot prove absence");
        };
        assert!(
            reasons.iter().any(|reason| matches!(
                reason,
                ResolutionIncompleteReason::CyclicPrefixDependency(_)
            )),
            "{answer:?}"
        );
        assert!(
            !answer
                .completion()
                .contains_reason(ResolutionIncompleteReason::Cancelled)
        );
        assert!(!cancellation.is_cancelled());
    }

