    #[test]
    fn plural_forward_scope_budget_has_atomic_lookahead_and_exact_boundary() {
        let fixture = parsed_java_service_fixture(
            "class Fixture { int value; int first() { return value; } int second() { return value; } }",
            b"plural-forward-budget",
        );
        let references = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "value",
            ResolutionIdentifierRole::Reference,
        );
        assert_eq!(references.len(), 2);
        let gap = SemanticId::for_test(b"plural-forward-budget-later-gap");
        let run = |limit| {
            let source = ObservedBatchSource::with_reference_seed_gap(
                &fixture.service.source,
                references[1],
                gap,
            );
            let cancellation = CancellationToken::new();
            let session = ResolutionSession::bounded(
                ReceiverAnalysisBudget {
                    max_scope_nodes: limit,
                    ..ReceiverAnalysisBudget::default()
                },
                Some(&cancellation),
            );
            let mut operation =
                FactResolutionOperation::new_bounded_with_callable_static_import_boundaries(
                    &source,
                    &fixture.service,
                    &[],
                    session.cancellation().unwrap(),
                    &session,
                );
            let batch = operation
                .resolve_references_with_metrics(
                    &references,
                    &mut ResolutionBatchMetrics::default(),
                )
                .unwrap();
            let outcome = session.finish(());
            (batch, outcome, source.reference_seed_batch_lookups.get())
        };
        let (complete, outcome, reads) = run(usize::MAX);
        assert_eq!(complete.answers().len(), references.len());
        assert_eq!(reads, 1);
        let exact = outcome.work().scope_nodes;
        assert!(exact > references.len());
        let cancellation = CancellationToken::new();
        let scalar_session = ResolutionSession::bounded(
            ReceiverAnalysisBudget {
                max_scope_nodes: usize::MAX,
                ..ReceiverAnalysisBudget::default()
            },
            Some(&cancellation),
        );
        let scalar_source = ObservedBatchSource::with_reference_seed_gap(
            &fixture.service.source,
            references[1],
            gap,
        );
        let mut scalar =
            FactResolutionOperation::new_bounded_with_callable_static_import_boundaries(
                &scalar_source,
                &fixture.service,
                &[],
                scalar_session.cancellation().unwrap(),
                &scalar_session,
            );
        for (item, &reference) in complete.answers().iter().zip(&references) {
            assert_eq!(item.answer(), &scalar.resolve_reference(reference).unwrap());
        }
        assert_eq!(
            exact,
            scalar_session.finish(()).work().scope_nodes + references.len(),
            "plural seed admission adds one scope step per root; evaluation charges remain unchanged"
        );
        let (boundary, outcome, _) = run(exact);
        assert_eq!(boundary.answers(), complete.answers());
        assert!(matches!(outcome, BoundedResolution::Complete { .. }));
        let (short, outcome, _) = run(exact - 1);
        assert!(!matches!(outcome, BoundedResolution::Complete { .. }));
        assert!(
            short.answers().is_empty(),
            "no completed root prefix may escape the batch"
        );
        assert!(
            short
                .completion()
                .contains_reason(ResolutionIncompleteReason::Cancelled)
        );
        assert_incomplete_with_reason(short.completion(), gap);
        let (unadmitted, _, reads) = run(references.len() - 1);
        assert!(unadmitted.answers().is_empty());
        assert_eq!(
            reads, 0,
            "the whole bounded seed batch must be admitted before I/O"
        );
    }

    #[test]
    fn forward_operation_shares_suffix_artifacts_without_sharing_root_answers() {
        let fixture = parsed_java_service_fixture(
            "class Fixture { int value; int first() { return value; } int second() { return value; } int third() { return value; } }",
            b"forward-operation-artifacts",
        );
        let references = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "value",
            ResolutionIdentifierRole::Reference,
        );
        assert_eq!(references.len(), 3);
        let gap = SemanticId::for_test(b"forward-operation-last-root-gap");
        let cached_source = ObservedBatchSource::with_reference_seed_gap(
            &fixture.service.source,
            references[2],
            gap,
        );
        let uncached_source = ObservedBatchSource::with_reference_seed_gap(
            &fixture.service.source,
            references[2],
            gap,
        );
        let cancellation = CancellationToken::new();
        let mut operation =
            FactResolutionOperation::new(&cached_source, &fixture.service, &cancellation);
        let mut uncached = FactReadSession::for_preloaded_service(
            &fixture.service,
            &uncached_source,
            &cancellation,
        );
        let mut hierarchy = HierarchyOperationArena::default();
        for &reference in &references {
            let mut oracle = FactEvaluation::new(&mut uncached, &mut hierarchy, reference);
            let expected = oracle.run().unwrap();
            let mut metrics = ResolutionBatchMetrics::default();
            let actual = operation
                .resolve_reference_with_metrics(reference, &mut metrics)
                .unwrap();
            assert_eq!(actual, expected);
            assert_eq!(metrics, oracle.binding_metrics);
            assert!(!actual.binding().targets().is_empty());
        }
        let physical_hydrations = |source: &ObservedBatchSource<'_>| {
            source
                .path_hydration_requests
                .borrow()
                .iter()
                .map(Vec::len)
                .sum::<usize>()
        };
        assert!(physical_hydrations(&cached_source) < physical_hydrations(&uncached_source));
        let before = (
            cached_source.forward_match_calls.get(),
            cached_source.path_hydration_calls.get(),
            cached_source.endpoint_classification_calls.get(),
        );
        let repeated = operation.resolve_reference(references[2]).unwrap();
        assert!(
            repeated
                .completion()
                .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(gap))
        );
        assert_eq!(
            before,
            (
                cached_source.forward_match_calls.get(),
                cached_source.path_hydration_calls.get(),
                cached_source.endpoint_classification_calls.get(),
            )
        );
        let artifacts = operation.forward_candidate_artifacts.artifact_counts();
        cancellation.cancel();
        let cancelled = operation.resolve_reference(references[2]).unwrap();
        assert!(
            cancelled
                .completion()
                .contains_reason(ResolutionIncompleteReason::Cancelled)
        );
        assert_eq!(
            operation.forward_candidate_artifacts.artifact_counts(),
            artifacts
        );
        assert_eq!(
            before,
            (
                cached_source.forward_match_calls.get(),
                cached_source.path_hydration_calls.get(),
                cached_source.endpoint_classification_calls.get(),
            )
        );
    }

    #[test]
    fn forward_operation_artifact_reuse_preserves_exact_bounded_work() {
        let fixture = parsed_java_service_fixture(
            "class Fixture { int value; int first() { return value; } int second() { return value; } }",
            b"bounded-forward-operation-artifacts",
        );
        let references = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "value",
            ResolutionIdentifierRole::Reference,
        );
        assert_eq!(references.len(), 2);
        let run = |cached_limit, oracle_limit| {
            let cancellation = CancellationToken::new();
            let budget = ReceiverAnalysisBudget {
                max_scope_nodes: cached_limit,
                ..ReceiverAnalysisBudget::default()
            };
            let cached_budget = ResolutionSession::bounded(budget, Some(&cancellation));
            let oracle_budget = ResolutionSession::bounded(
                ReceiverAnalysisBudget {
                    max_scope_nodes: oracle_limit,
                    ..budget
                },
                Some(&cancellation),
            );
            let mut operation =
                FactResolutionOperation::new_bounded_with_callable_static_import_boundaries(
                    &fixture.service.source,
                    &fixture.service,
                    &[],
                    cached_budget.cancellation().unwrap(),
                    &cached_budget,
                );
            let mut oracle = FactReadSession::from_split_sources_bounded(
                &fixture.service.source,
                &fixture.service,
                &[],
                oracle_budget.cancellation().unwrap(),
                &oracle_budget,
            );
            let mut hierarchy = HierarchyOperationArena::default();
            for &reference in &references {
                let expected = FactEvaluation::new(&mut oracle, &mut hierarchy, reference)
                    .run()
                    .unwrap();
                let actual = operation.resolve_reference(reference).unwrap();
                if matches!(cached_budget.finish(()), BoundedResolution::Complete { .. })
                    && matches!(oracle_budget.finish(()), BoundedResolution::Complete { .. })
                {
                    assert_eq!(actual, expected);
                } else {
                    assert!(
                        actual
                            .completion()
                            .contains_reason(ResolutionIncompleteReason::Cancelled)
                    );
                    assert!(
                        expected
                            .completion()
                            .contains_reason(ResolutionIncompleteReason::Cancelled)
                    );
                }
            }
            let outcome = cached_budget.finish(());
            let oracle_outcome = oracle_budget.finish(());
            let complete = matches!(outcome, BoundedResolution::Complete { .. });
            assert_eq!(
                complete,
                matches!(oracle_outcome, BoundedResolution::Complete { .. })
            );
            assert_eq!(
                outcome.work().summary_expansions,
                oracle_outcome.work().summary_expansions
            );
            (
                complete,
                outcome.work().scope_nodes,
                oracle_outcome.work().scope_nodes,
            )
        };
        let (complete, cached_exact, oracle_exact) = run(usize::MAX, usize::MAX);
        assert!(complete);
        assert!(cached_exact > 1);

        // Record each execution's actual provider requests independently of
        // the artifact cache. Then replay only those source calls, with an
        // always-live visitor that performs no engine work. The measured
        // delta is source-owned index inspection and branch-coverage work,
        // not lost logical matches, compositions, or typed evaluation.
        let cancellation = CancellationToken::new();
        let cached_source = ObservedBatchSource::new(&fixture.service.source);
        let oracle_source = ObservedBatchSource::new(&fixture.service.source);
        let mut operation =
            FactResolutionOperation::new(&cached_source, &fixture.service, &cancellation);
        let mut oracle =
            FactReadSession::for_preloaded_service(&fixture.service, &oracle_source, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        for &reference in &references {
            let mut evaluation = FactEvaluation::new(&mut oracle, &mut hierarchy, reference);
            let expected = evaluation.run().unwrap();
            let mut metrics = ResolutionBatchMetrics::default();
            assert_eq!(
                operation
                    .resolve_reference_with_metrics(reference, &mut metrics)
                    .unwrap(),
                expected
            );
            assert_eq!(metrics, evaluation.binding_metrics);
        }
        let provider_work = |source: &ObservedBatchSource<'_>| {
            let session = ResolutionSession::bounded(
                ReceiverAnalysisBudget {
                    max_scope_nodes: usize::MAX,
                    ..ReceiverAnalysisBudget::default()
                },
                Some(&cancellation),
            );
            for endpoints in source.forward_match_requests.borrow().iter() {
                let requests = endpoints
                    .iter()
                    .enumerate()
                    .map(|(ordinal, endpoint)| {
                        BatchCandidateRequest::new(ordinal, endpoint.clone())
                    })
                    .collect::<Vec<_>>();
                fixture
                    .service
                    .source
                    .visit_forward_candidate_match_pages_limited(
                        &requests,
                        MAX_SOURCE_ROWS_PER_BATCH,
                        Some(&session),
                        &cancellation,
                        &mut |_| Ok(true),
                    )
                    .unwrap();
            }
            assert!(matches!(
                session.finish(()),
                BoundedResolution::Complete { .. }
            ));
            session.finish(()).work().scope_nodes
        };
        let saved_provider_work = provider_work(&oracle_source) - provider_work(&cached_source);
        assert!(saved_provider_work > 0);
        assert_eq!(oracle_exact - cached_exact, saved_provider_work);
        assert_eq!(
            run(cached_exact, oracle_exact),
            (true, cached_exact, oracle_exact)
        );
        assert_eq!(
            run(cached_exact - 1, oracle_exact - 1),
            (false, cached_exact - 1, oracle_exact - 1)
        );
    }

