    #[test]
    fn fact_resolution_operation_reads_and_reuses_exact_intrinsic_descriptors() {
        let mut facts = java_chain_facts();
        facts.names[6] = name(6, "ExactAlpha");
        facts.names.push(name(7, "ExactBeta"));
        facts.intrinsic_type_seeds[1].name = ResolutionNameId::new(7);
        facts.intrinsic_type_seeds[1].kind = IntrinsicTypeKind::LanguageBuiltin;
        let fixture = java_fixture_from_facts(facts);
        let expected = fixture
            .typed
            .intrinsic_seeds()
            .iter()
            .map(|seed| {
                (
                    seed.frontier().possible_values()[0].ty().identity(),
                    seed.kind(),
                    seed.spelling(),
                )
            })
            .collect::<Vec<_>>();
        assert_eq!(expected.len(), 2);
        assert_ne!(expected[0].0, expected[1].0);
        let cancellation = CancellationToken::new();
        let mut operation =
            FactResolutionOperation::new(&fixture.service, &fixture.service, &cancellation);

        let first = operation
            .read_intrinsic_type_descriptors(&[expected[1].0, expected[0].0, expected[1].0])
            .expect("the selected intrinsic read succeeds")
            .expect("the live descriptor read is published");
        assert_eq!(first.len(), 2);
        assert!(first.iter().any(|descriptor| {
            descriptor.identity() == expected[0].0
                && descriptor.kind() == expected[0].1
                && descriptor.spelling() == expected[0].2
        }));
        assert!(first.iter().any(|descriptor| {
            descriptor.identity() == expected[1].0
                && descriptor.kind() == expected[1].1
                && descriptor.spelling() == expected[1].2
        }));

        let second = operation
            .read_intrinsic_type_descriptors(&[expected[0].0, expected[1].0])
            .expect("the cached selected intrinsic read succeeds")
            .expect("the cached descriptor read is published");
        assert_eq!(second, first);
    }

    #[test]
    fn fact_resolution_operation_does_not_publish_cancelled_intrinsic_descriptors() {
        let fixture = java_fixture();
        let identity = fixture.int_type;
        let cancellation = CancellationToken::new();
        cancellation.cancel();
        let mut operation =
            FactResolutionOperation::new(&fixture.service, &fixture.service, &cancellation);
        assert!(
            operation
                .read_intrinsic_type_descriptors(&[identity])
                .expect("cancellation is semantic control flow")
                .is_none(),
            "cancellation before a descriptor read must not look like an empty complete result"
        );

        let mut observed_during_read = false;
        for checks in 1..=128 {
            let cancellation = CancellationToken::cancel_after_checks_for_test(checks);
            let mut operation =
                FactResolutionOperation::new(&fixture.service, &fixture.service, &cancellation);
            let descriptors = operation
                .read_intrinsic_type_descriptors(&[identity])
                .expect("cancellation is semantic control flow");
            if descriptors.is_none() {
                observed_during_read = true;
                break;
            }
        }
        assert!(
            observed_during_read,
            "a cancellation edge during descriptor work must suppress the whole result"
        );
    }

    #[test]
    fn fact_read_session_preserves_distinct_projection_kinds_for_one_reference() {
        let fixture = java_fixture();
        let reference = SemanticId::for_test(b"same-reference-projection-kinds");
        let type_output = SemanticId::for_test(b"same-reference-type-output");
        let value_output = SemanticId::for_test(b"same-reference-value-output");
        let projections = [
            SelectedTypedRow::new(
                fragment(),
                LoweredBindingProjection::new(
                    reference,
                    type_output,
                    BindingProjectionKind::TargetTypeIdentity,
                ),
            ),
            SelectedTypedRow::new(
                fragment(),
                LoweredBindingProjection::new(
                    reference,
                    value_output,
                    BindingProjectionKind::TargetDeclaredValueType,
                ),
            ),
        ];
        let cancellation = CancellationToken::new();
        let mut session = preloaded_session(&fixture.service, &cancellation);
        let source_calls = Cell::new(0_usize);
        let first =
            read_session_projections_with(&mut session, &[reference], |request, visitor| {
                source_calls.set(source_calls.get() + 1);
                assert_eq!(request.as_slice(), &[reference]);
                assert!(visitor.visit_page(&projections)?);
                Ok(TypedFactReadOutcome::exhausted(
                    ResolutionCompletion::Complete,
                ))
            })
            .expect("the injected projection read is infallible");
        let SessionFactRead::Exhausted { rows, .. } = first else {
            panic!("a live projection read cannot cancel")
        };
        assert_eq!(rows.len(), 2);
        let metadata = rows
            .iter()
            .map(|row| {
                let projection = row.get(&session).row();
                (projection.output_slot(), projection.kind())
            })
            .collect::<Vec<_>>();
        assert!(metadata.contains(&(type_output, BindingProjectionKind::TargetTypeIdentity,)));
        assert!(
            metadata.contains(&(value_output, BindingProjectionKind::TargetDeclaredValueType,))
        );

        let cached = read_session_projections_with(&mut session, &[reference], |_, _| {
            panic!("distinct projections sharing a reference must reuse both cached rows")
        })
        .expect("the projection cache hit is infallible");
        let SessionFactRead::Exhausted { rows, .. } = cached else {
            panic!("a live projection cache hit cannot cancel")
        };
        assert_eq!(rows.len(), 2);
        assert_eq!(source_calls.get(), 1);
    }

