    #[test]
    fn fact_resolution_operation_does_not_publish_descriptor_prefix_after_mid_read_cancel() {
        let fixture = java_fixture();
        let mut identities = (0_u64..(CANCELLATION_QUANTUM as u64 + 7))
            .map(|ordinal| SemanticId::for_test(ordinal.to_le_bytes()))
            .collect::<Vec<_>>();
        identities.sort_unstable();
        identities.dedup();
        assert!(identities.len() > CANCELLATION_QUANTUM);
        let row = SelectedTypedRow::new(
            fragment(),
            LoweredIntrinsicSeed::new(
                IntrinsicTypeKind::Primitive,
                "MidReadPrimitive",
                TypedFrontierState::new(
                    SemanticId::for_test(b"mid-read-intrinsic-slot"),
                    identities
                        .iter()
                        .copied()
                        .map(|identity| {
                            ResolutionSlotValue::type_object(ResolutionTypeRef::new(identity, 0))
                        })
                        .collect::<Vec<_>>(),
                    ResolutionCompletion::Complete,
                ),
            ),
        );
        let requested = identities[0];
        let mut observed_threshold = None;
        for checks in 8..=256 {
            let cancellation = CancellationToken::cancel_after_checks_for_test(checks);
            let bounded =
                ResolutionSession::bounded(ReceiverAnalysisBudget::default(), Some(&cancellation));
            let mut operation =
                FactResolutionOperation::new_bounded_with_callable_static_import_boundaries(
                    &fixture.service,
                    &fixture.service,
                    &[],
                    &cancellation,
                    &bounded,
                );
            install_cached_intrinsic_relation(
                &mut operation,
                requested,
                std::slice::from_ref(&row),
            );
            let descriptors = operation
                .read_intrinsic_type_descriptors(&[requested])
                .expect("cancellation is semantic control flow");
            if descriptors.is_none() {
                observed_threshold = Some(checks);
                break;
            }
        }
        let Some(checks) = observed_threshold else {
            panic!("one threshold must cancel after descriptor work begins")
        };
        assert!(
            checks > 1,
            "the cancellation edge must occur after the operation has begun reading descriptors"
        );
    }

    fn contextual_java_fixture() -> JavaFixture {
        let mut facts = java_chain_facts();
        let placement_gap_site = ResolutionSiteId::new(20);
        facts.sites.push(site(
            placement_gap_site.get(),
            0,
            ResolutionSiteKind::UnsupportedRoute,
            999,
        ));
        facts.packages.push(ResolutionPackageFact {
            root_scope: ResolutionScopeId::new(0),
            declaration: None,
            placement_gap_site,
        });
        facts.gaps.push(ResolutionGapFact {
            site: placement_gap_site,
            kind: ResolutionGapKind::UnsupportedPlacementBoundary,
        });
        java_fixture_from_facts(facts)
    }

    fn java_fixture_from_facts(facts: FileResolutionFacts) -> JavaFixture {
        let lexical =
            crate::analyzer::resolution::lower_for_test(fragment(), Language::Java, &facts)
                .lexical()
                .clone();
        let references = lexical
            .semantics()
            .iter()
            .filter(|semantic| semantic.role() == LoweredSemanticRole::Reference)
            .map(|semantic| (semantic.site().get(), semantic.semantic()))
            .collect::<HashMap<_, _>>();
        let definitions = lexical
            .semantics()
            .iter()
            .filter(|semantic| semantic.role() == LoweredSemanticRole::Definition)
            .map(|semantic| (semantic.site().get(), semantic.semantic()))
            .collect::<HashMap<_, _>>();
        let typed = crate::analyzer::resolution::lower_for_test(fragment(), Language::Java, &facts)
            .typed()
            .clone();
        let int_type = typed.intrinsic_seeds()[0].frontier().possible_values()[0]
            .ty()
            .identity();
        JavaFixture {
            service: PreloadedFactResolutionService::from_lowered_fragments(
                [lexical.clone()],
                [typed.clone()],
            ),
            lexical,
            typed,
            references,
            definitions,
            int_type,
        }
    }

    #[test]
    fn point_and_broad_fact_answers_preserve_reference_site_metadata() {
        let fixture = java_fixture();
        let explicit_call = fixture.references[&11];
        let ordinary_reference = fixture.references[&10];
        let expected = fixture
            .lexical
            .semantics()
            .iter()
            .filter(|semantic| semantic.role() == LoweredSemanticRole::Reference)
            .map(|semantic| (semantic.semantic(), semantic.site_metadata()))
            .collect::<HashMap<_, _>>();
        let point = fixture
            .service
            .resolve_reference(explicit_call, &CancellationToken::new())
            .expect("preloaded point fact resolution succeeds");
        assert_eq!(point.site_metadata(), expected[&explicit_call]);
        assert_eq!(
            point.callable_receiver_origin(),
            point
                .site_metadata()
                .and_then(FactReferenceSiteMetadata::callable_receiver_origin)
        );
        let mut metadata = HashMap::default();
        let mut origins = HashMap::default();
        let mut dispositions = HashMap::default();
        fixture
            .service
            .stage_all_reference_batches(2, &CancellationToken::new(), &mut |batch| {
                for answer in batch.answers() {
                    assert!(
                        metadata
                            .insert(answer.reference(), answer.site_metadata())
                            .is_none(),
                        "broad fact staging must publish each reference once"
                    );
                    assert!(
                        origins
                            .insert(answer.reference(), answer.callable_receiver_origin())
                            .is_none(),
                        "broad fact staging must publish each reference once"
                    );
                    assert!(
                        dispositions
                            .insert(
                                answer.reference(),
                                answer.callable_receiver_dispositions().to_vec(),
                            )
                            .is_none(),
                        "broad fact staging must publish one disposition inventory per reference"
                    );
                }
                Ok(())
            })
            .expect("preloaded broad fact staging succeeds");
        assert_eq!(metadata, expected);
        assert_eq!(
            origins[&explicit_call],
            Some(ResolutionCallableReceiverOrigin::ExplicitExpression)
        );
        assert_eq!(
            origins[&ordinary_reference], None,
            "receiver origin remains optional for non-callable and partial producers"
        );
        assert!(
            dispositions[&ordinary_reference].is_empty(),
            "a non-callable target answer must not manufacture MissingOrigin receiver gaps"
        );
    }

