    #[test]
    fn broad_fact_shared_root_batch_has_no_seed_lookups_and_matches_point_answers() {
        let owner = BindingFragmentId::for_test(b"broad-shared-root-fragment");
        let facts = FileResolutionFacts {
            names: vec![name(0, "x"), name(1, "y")],
            scopes: vec![scope(
                0,
                None,
                None,
                ResolutionScopeKind::CompilationUnit,
                0,
                100,
            )],
            sites: vec![
                site(0, 0, ResolutionSiteKind::ValueDeclaration, 10),
                site(1, 0, ResolutionSiteKind::ValueReference, 20),
                site(2, 0, ResolutionSiteKind::ValueDeclaration, 30),
                site(3, 0, ResolutionSiteKind::ValueReference, 40),
            ],
            identifiers: vec![
                identifier(
                    0,
                    0,
                    ResolutionIdentifierRole::Declaration,
                    ResolutionNamespace::Value,
                    None,
                ),
                identifier(
                    1,
                    0,
                    ResolutionIdentifierRole::Reference,
                    ResolutionNamespace::Value,
                    None,
                ),
                identifier(
                    2,
                    1,
                    ResolutionIdentifierRole::Declaration,
                    ResolutionNamespace::Value,
                    None,
                ),
                identifier(
                    3,
                    1,
                    ResolutionIdentifierRole::Reference,
                    ResolutionNamespace::Value,
                    None,
                ),
            ],
            binders: vec![
                binder(
                    0,
                    0,
                    ResolutionBinderKind::Local,
                    HoistingClass::SourceOrder,
                    10,
                    100,
                ),
                binder(
                    2,
                    0,
                    ResolutionBinderKind::Local,
                    HoistingClass::SourceOrder,
                    30,
                    100,
                ),
            ],
            ..FileResolutionFacts::default()
        };
        let lexical = crate::analyzer::resolution::lower_for_test(owner, Language::Java, &facts)
            .lexical()
            .clone();
        let mut expected_edges = vec![
            (
                lowered_semantic_at(
                    &lexical,
                    ResolutionSiteId::new(1),
                    LoweredSemanticRole::Reference,
                ),
                lowered_semantic_at(
                    &lexical,
                    ResolutionSiteId::new(0),
                    LoweredSemanticRole::Definition,
                ),
            ),
            (
                lowered_semantic_at(
                    &lexical,
                    ResolutionSiteId::new(3),
                    LoweredSemanticRole::Reference,
                ),
                lowered_semantic_at(
                    &lexical,
                    ResolutionSiteId::new(2),
                    LoweredSemanticRole::Definition,
                ),
            ),
        ];
        expected_edges.sort_unstable();
        let mut expected_references = expected_edges
            .iter()
            .map(|(reference, _)| *reference)
            .collect::<Vec<_>>();
        expected_references.sort_unstable();
        let typed = crate::analyzer::resolution::lower_for_test(owner, Language::Java, &facts)
            .typed()
            .clone();
        let service = PreloadedFactResolutionService::from_lowered_fragments([lexical], [typed]);
        let observed = ObservedBatchSource::new(&service.source);
        let mut references = Vec::new();
        let mut edges = Vec::new();
        let mut broad_answers = Vec::new();
        let mut staged_completion = ResolutionCompletion::Complete;
        let summary = service
            .stage_all_reference_batches_from(
                &observed,
                MAX_REFERENCE_SEEDS_PER_BATCH,
                &CancellationToken::new(),
                &mut |batch| {
                    assert_eq!(batch.fragment(), owner);
                    assert!(
                        batch
                            .answers()
                            .windows(2)
                            .all(|pair| pair[0].reference() < pair[1].reference())
                    );
                    let exact_batch_completion = batch
                        .answers()
                        .iter()
                        .fold(ResolutionCompletion::Complete, |completion, item| {
                            completion.combine(item.answer().completion())
                        });
                    assert_eq!(batch.completion(), &exact_batch_completion);
                    staged_completion = staged_completion.combine(batch.completion());
                    for item in batch.answers() {
                        references.push(item.reference());
                        broad_answers.push((item.reference(), item.answer().clone()));
                        edges.extend(
                            item.answer()
                                .binding()
                                .targets()
                                .iter()
                                .copied()
                                .map(|target| (item.reference(), target)),
                        );
                    }
                    Ok(())
                },
            )
            .expect("preload broad reads are infallible");

        references.sort_unstable();
        assert_eq!(references, expected_references);
        assert!(
            references.windows(2).all(|pair| pair[0] != pair[1]),
            "every selected lexical reference is evaluated exactly once"
        );
        assert_eq!(summary.reference_count(), references.len());
        assert_eq!(summary.batch_count(), 1);
        assert_eq!(summary.completion(), &staged_completion);
        assert_eq!(summary.root_binding_metrics().batches(), 1);
        assert_eq!(
            summary.root_binding_metrics().reference_seeds(),
            expected_references.len()
        );
        assert_eq!(observed.reference_seed_lookups.get(), 0);
        broad_answers.sort_unstable_by_key(|(reference, _)| *reference);
        for (reference, broad) in broad_answers {
            let point = service
                .resolve_reference(reference, &CancellationToken::new())
                .expect("preload point reads are infallible");
            assert_eq!(broad, point, "broad/point mismatch for {reference}");
        }
        edges.sort_unstable();
        assert_eq!(edges, expected_edges);
    }

    #[test]
    fn broad_qualified_root_never_consumes_the_coarse_identity_gap() {
        let fixture = java_fixture();
        let lexical = crate::analyzer::resolution::lower_lexical_for_test(
            fragment(),
            Language::Java,
            &java_chain_facts(),
        )
        .0;
        let reference = fixture.references[&9];
        let coarse_reason = lexical
            .gaps()
            .iter()
            .find(|gap| {
                gap.site() == ResolutionSiteId::new(9)
                    && gap.origin() == LoweringGapOrigin::QualifiedReference
            })
            .expect("qualified field has a coarse lexical gap")
            .reason_semantic();
        let mut broad = None;
        let summary = fixture
            .service
            .stage_all_reference_batches(
                MAX_REFERENCE_SEEDS_PER_BATCH,
                &CancellationToken::new(),
                &mut |batch| {
                    if let Some(item) = batch
                        .answers()
                        .iter()
                        .find(|item| item.reference() == reference)
                    {
                        broad = Some(item.answer().clone());
                    }
                    Ok(())
                },
            )
            .expect("preload broad reads are infallible");
        let broad = broad.expect("qualified field was broadly evaluated");
        let point = fixture
            .service
            .resolve_reference(reference, &CancellationToken::new())
            .expect("preload point reads are infallible");

        assert_eq!(broad, point);
        assert_eq!(broad.completion(), &ResolutionCompletion::Complete);
        for completion in std::iter::once(broad.binding().completion())
            .chain(
                broad
                    .projected_frontiers()
                    .iter()
                    .map(|state| state.completion()),
            )
            .chain(std::iter::once(broad.completion()))
        {
            assert!(
                !completion.contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(
                    coarse_reason
                )),
                "qualified typed routing must not consume an identity-path gap"
            );
        }
        assert!(summary.root_binding_metrics().reference_seeds() < summary.reference_count());
    }

    #[test]
    fn broad_cancellation_after_root_batch_retains_seed_and_root_completion() {
        let source = "abstract class C extends Unindexed { abstract void f(); void g() { f(); } }";
        let fixture = parsed_java_service_fixture(source, b"broad-root-batch-cancellation");
        let hierarchy_reason = fixture
            .lexical
            .gaps()
            .iter()
            .find(|gap| {
                gap.origin()
                    == LoweringGapOrigin::Extracted(
                        ResolutionGapKind::UnsupportedHierarchyTraversal,
                    )
            })
            .expect("callable root batch has hierarchy terminal evidence")
            .reason_semantic();
        let applicability_reason = fixture
            .lexical
            .gaps()
            .iter()
            .find(|gap| {
                gap.origin()
                    == LoweringGapOrigin::Extracted(ResolutionGapKind::UnsupportedCallApplicability)
            })
            .expect("callee seed has applicability evidence")
            .reason_semantic();

        let mut observed = None;
        for checks in 1..=256 {
            let cancellation = CancellationToken::cancel_after_checks_for_test(checks);
            let mut staged = 0;
            let summary = fixture
                .service
                .stage_all_reference_batches(
                    MAX_REFERENCE_SEEDS_PER_BATCH,
                    &cancellation,
                    &mut |_| {
                        staged += 1;
                        Ok(())
                    },
                )
                .expect("preload broad reads are infallible");
            if staged == 0
                && summary.root_binding_metrics().batches() == 1
                && summary
                    .completion()
                    .contains_reason(ResolutionIncompleteReason::Cancelled)
                && matches!(
                    summary.completion(),
                    ResolutionCompletion::Incomplete(reasons)
                        if reasons.contains(&ResolutionIncompleteReason::UnsupportedSemantic(
                            hierarchy_reason
                        ))
                            && reasons.contains(
                                &ResolutionIncompleteReason::UnsupportedSemantic(
                                    applicability_reason
                                )
                            )
                )
            {
                observed = Some(summary);
                break;
            }
        }

        let summary = observed.expect(
            "deterministic cancellation after the shared root batch preserves all evidence",
        );
        assert_eq!(summary.reference_count(), 0);
        assert_eq!(summary.batch_count(), 0);
        assert!(summary.root_binding_metrics().reference_seeds() > 0);
    }

    #[test]
    fn broad_fact_summary_combines_cross_file_and_enumeration_coverage() {
        let declaration_fragment = BindingFragmentId::for_test(b"broad-declaration-fragment");
        let reference_fragment = BindingFragmentId::for_test(b"broad-reference-fragment");
        let declaration_facts = FileResolutionFacts {
            names: vec![name(0, "A")],
            scopes: vec![scope(
                0,
                None,
                None,
                ResolutionScopeKind::CompilationUnit,
                0,
                100,
            )],
            sites: vec![
                site(0, 0, ResolutionSiteKind::TypeDeclaration, 1),
                site(1, 0, ResolutionSiteKind::UnsupportedRoute, 0),
            ],
            identifiers: vec![identifier(
                0,
                0,
                ResolutionIdentifierRole::Declaration,
                ResolutionNamespace::Type,
                None,
            )],
            binders: vec![binder(
                0,
                0,
                ResolutionBinderKind::Type,
                HoistingClass::ScopeWide,
                0,
                100,
            )],
            gaps: vec![ResolutionGapFact {
                site: ResolutionSiteId::new(1),
                kind: ResolutionGapKind::UnsupportedPlacementBoundary,
            }],
            ..FileResolutionFacts::default()
        };
        let reference_facts = FileResolutionFacts {
            names: vec![name(0, "A")],
            scopes: vec![scope(
                0,
                None,
                None,
                ResolutionScopeKind::CompilationUnit,
                0,
                100,
            )],
            sites: vec![
                site(0, 0, ResolutionSiteKind::TypeReference, 20),
                site(1, 0, ResolutionSiteKind::UnsupportedRoute, 0),
                site(2, 0, ResolutionSiteKind::UnsupportedExpression, 30),
            ],
            identifiers: vec![identifier(
                0,
                0,
                ResolutionIdentifierRole::Reference,
                ResolutionNamespace::Type,
                None,
            )],
            gaps: vec![
                ResolutionGapFact {
                    site: ResolutionSiteId::new(1),
                    kind: ResolutionGapKind::UnsupportedPlacementBoundary,
                },
                ResolutionGapFact {
                    site: ResolutionSiteId::new(2),
                    kind: ResolutionGapKind::UnsupportedExpression,
                },
            ],
            reference_enumeration_gaps: vec![ResolutionReferenceEnumerationGapFact {
                site: ResolutionSiteId::new(2),
                kind: ResolutionGapKind::UnsupportedExpression,
            }],
            ..FileResolutionFacts::default()
        };

        let declaration_lexical = crate::analyzer::resolution::lower_for_test(
            declaration_fragment,
            Language::Java,
            &declaration_facts,
        )
        .lexical()
        .clone();
        let definition = declaration_lexical
            .semantics()
            .iter()
            .find(|semantic| semantic.role() == LoweredSemanticRole::Definition)
            .expect("cross-file definition semantic")
            .semantic();
        let declaration_placement_reason = declaration_lexical
            .gaps()
            .iter()
            .find(|gap| {
                gap.origin()
                    == LoweringGapOrigin::Extracted(ResolutionGapKind::UnsupportedPlacementBoundary)
            })
            .expect("definition fragment has placement evidence")
            .reason_semantic();
        let reference_lexical = crate::analyzer::resolution::lower_for_test(
            reference_fragment,
            Language::Java,
            &reference_facts,
        )
        .lexical()
        .clone();
        let reference = reference_lexical
            .semantics()
            .iter()
            .find(|semantic| semantic.role() == LoweredSemanticRole::Reference)
            .expect("cross-file reference semantic")
            .semantic();
        let placement_reason = reference_lexical
            .gaps()
            .iter()
            .find(|gap| {
                gap.origin()
                    == LoweringGapOrigin::Extracted(ResolutionGapKind::UnsupportedPlacementBoundary)
            })
            .expect("cross-file placement evidence")
            .reason_semantic();
        let enumeration_reason = reference_lexical
            .gaps()
            .iter()
            .find(|gap| {
                gap.origin()
                    == LoweringGapOrigin::Extracted(ResolutionGapKind::UnsupportedExpression)
                    && gap.frontier() == LoweringCoverageFrontier::Enumeration
            })
            .expect("omitted-reference enumeration evidence")
            .reason_semantic();
        let declaration_typed = crate::analyzer::resolution::lower_for_test(
            declaration_fragment,
            Language::Java,
            &declaration_facts,
        )
        .typed()
        .clone();
        let reference_typed = crate::analyzer::resolution::lower_for_test(
            reference_fragment,
            Language::Java,
            &reference_facts,
        )
        .typed()
        .clone();
        let service = PreloadedFactResolutionService::from_lowered_fragments(
            [declaration_lexical, reference_lexical],
            [declaration_typed, reference_typed],
        );

        let mut answer_completion = None;
        let summary = service
            .stage_all_reference_batches(8, &CancellationToken::new(), &mut |batch| {
                assert_eq!(batch.answers().len(), 1);
                let item = &batch.answers()[0];
                assert_eq!(item.reference(), reference);
                assert!(item.answer().binding().targets().is_empty());
                answer_completion = Some(item.answer().completion().clone());
                Ok(())
            })
            .expect("preload broad reads are infallible");
        assert_eq!(summary.reference_count(), 1);
        assert_eq!(summary.batch_count(), 1);
        assert_incomplete_with_reason(
            answer_completion
                .as_ref()
                .expect("the selected reference was staged"),
            placement_reason,
        );
        assert_incomplete_with_reason(summary.completion(), placement_reason);
        assert_incomplete_with_reason(summary.completion(), enumeration_reason);

        let reverse = service
            .references_to(definition, &CancellationToken::new())
            .expect("plain lowered reverse reads are infallible");
        assert_incomplete_with_reason(reverse.completion(), declaration_placement_reason);
    }

    #[test]
    fn broad_fact_cancellation_requires_rollback_of_every_staged_batch() {
        let fixture = java_fixture();
        let cancellation = CancellationToken::new();
        let mut staged = Vec::new();
        let summary = fixture
            .service
            .stage_all_reference_batches(1, &cancellation, &mut |batch| {
                staged.extend(batch.answers().iter().map(|item| item.reference()));
                cancellation.cancel();
                Ok(())
            })
            .expect("preload broad reads are infallible");

        assert_eq!(summary.reference_count(), 1);
        assert_eq!(summary.batch_count(), 1);
        assert_eq!(staged.len(), 1, "one whole batch reached the staging sink");
        assert!(
            summary
                .completion()
                .contains_reason(ResolutionIncompleteReason::Cancelled)
        );
        let durable = if summary.completion() == &ResolutionCompletion::Complete {
            staged
        } else {
            Vec::new()
        };
        assert!(
            durable.is_empty(),
            "a cancelled broad operation cannot publish a staged prefix"
        );
    }

