    #[test]
    fn generic_selected_reverse_transfers_exact_seed_gap_to_typed_route_ownership() {
        let fixture = java_fixture();
        let reference = fixture.references[&9];
        let field = fixture.definitions[&4];
        let route_id = fixture.service.typed.qualified_route_ids_by_reference[&reference][0];
        let coarse_reason = fixture.service.typed.qualified_routes[route_id]
            .row
            .coarse_gap_reason();
        let expected = fixture
            .service
            .references_to(field, &CancellationToken::new())
            .expect("preload reverse reads are infallible");
        assert_eq!(expected.references(), &[reference]);
        assert_eq!(expected.completion(), &ResolutionCompletion::Complete);

        let generic = ObservedBatchSource::with_reverse_seed_completion(
            &fixture.service.source,
            incomplete(coarse_reason),
        );
        let actual = fixture
            .service
            .references_to_from(
                &generic,
                MAX_REFERENCE_SEEDS_PER_BATCH,
                field,
                &CancellationToken::new(),
            )
            .expect("generic selected reverse reads are infallible");

        assert_eq!(actual, expected);
        assert_eq!(generic.reverse_seed_issues.get(), 1);
        assert_eq!(
            generic.issued_reverse_references.borrow().as_slice(),
            &[reference]
        );

        let independent_reason =
            SemanticId::for_test(b"generic-selected-reverse-independent-seed-completion");
        let generic = ObservedBatchSource::with_reverse_seed_completion(
            &fixture.service.source,
            ResolutionCompletion::incomplete([
                ResolutionIncompleteReason::UnsupportedSemantic(coarse_reason),
                ResolutionIncompleteReason::UnsupportedSemantic(independent_reason),
            ]),
        );
        let actual = fixture
            .service
            .references_to_from(
                &generic,
                MAX_REFERENCE_SEEDS_PER_BATCH,
                field,
                &CancellationToken::new(),
            )
            .expect("generic selected reverse reads are infallible");

        assert_eq!(actual.references(), expected.references());
        assert_eq!(actual.witnesses().len(), expected.witnesses().len());
        for (actual, expected) in actual.witnesses().iter().zip(expected.witnesses()) {
            assert_eq!(actual.reference(), expected.reference());
            assert_eq!(actual.target(), expected.target());
            assert_eq!(actual.steps(), expected.steps());
            assert_incomplete_with_reason(actual.completion(), independent_reason);
            assert!(!actual.completion().contains_reason(
                ResolutionIncompleteReason::UnsupportedSemantic(coarse_reason)
            ));
        }
        assert_eq!(
            actual.completion(),
            &ResolutionCompletion::incomplete([ResolutionIncompleteReason::UnsupportedSemantic(
                independent_reason
            ),])
        );
    }

