    fn reverse_with_inventory_operands(
        operation: &mut FactResolutionOperation<'_>,
        target: SemanticId,
        raw: &ResolutionCompletion,
        contextual: &ResolutionCompletion,
    ) -> ReferenceSearchAnswer {
        let mut returned_evidence = CancellationEvidenceLedger::default();
        let mut work = 0;
        returned_evidence.include(raw, operation.session.cancellation, &mut work);
        returned_evidence.include(contextual, operation.session.cancellation, &mut work);
        operation
            .references_to_with_selected_inventory(
                2,
                target,
                TypedFactReadTerminal::Exhausted,
                raw,
                contextual,
                &mut returned_evidence,
                &mut FactReverseResolutionMetrics::default(),
                &mut |_| Ok(()),
            )
            .expect("selected reverse inventory operands are source-readable")
    }

