    #[test]
    fn typed_reverse_prunes_same_name_routes_before_seed_issuance() {
        let fixture = parsed_java_service_fixture(
            "class A { int changed; }\n\
             class B { int changed; }\n\
             class Use { void f(A a, B b) { int x = a.changed; int y = b.changed; } }",
            b"typed-reverse-same-name-owner-pruning",
        );
        let definitions = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "changed",
            ResolutionIdentifierRole::Declaration,
        );
        let references = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "changed",
            ResolutionIdentifierRole::Reference,
        );
        assert_eq!(definitions.len(), 2);
        assert_eq!(references.len(), 2);
        let narrowing_observed = ObservedBatchSource::new(&fixture.service.source);
        let narrowing_cancellation = CancellationToken::new();
        let mut narrowing_session = FactReadSession::for_preloaded_service(
            &fixture.service,
            &narrowing_observed,
            &narrowing_cancellation,
        );
        let mut narrowing_hierarchy = HierarchyOperationArena::default();
        let narrowed = TypedReverseNarrowing::new(&mut narrowing_session, &mut narrowing_hierarchy)
            .run(definitions[0], &ResolutionCompletion::Complete)
            .expect("preload narrowing reads are infallible");
        assert_eq!(
            narrowed
                .references
                .iter()
                .map(|(reference, _)| *reference)
                .collect::<Vec<_>>(),
            [references[0]]
        );
        let expected_scalar_queries = ["A", "B", "a", "b"]
            .into_iter()
            .map(|name| {
                let matches = lowered_semantics_named(
                    &fixture.facts,
                    &fixture.lexical,
                    name,
                    ResolutionIdentifierRole::Reference,
                );
                assert_eq!(matches.len(), 1);
                matches[0]
            })
            .collect::<BTreeSet<_>>();
        let scalar_queries = narrowing_observed.reference_seed_queries.borrow();
        assert_eq!(
            narrowing_observed.reference_seed_lookups.get(),
            expected_scalar_queries.len(),
            "typed route narrowing reads each structured unqualified predecessor once"
        );
        assert_eq!(scalar_queries.len(), expected_scalar_queries.len());
        assert_eq!(
            scalar_queries.iter().copied().collect::<BTreeSet<_>>(),
            expected_scalar_queries
        );
        assert!(expected_scalar_queries.iter().all(|query| {
            scalar_queries
                .iter()
                .filter(|&&actual| actual == *query)
                .count()
                == 1
        }));
        assert!(
            references
                .iter()
                .all(|reference| !scalar_queries.contains(reference))
        );
        assert_eq!(narrowing_observed.reference_seed_batch_lookups.get(), 0);
        assert_eq!(
            narrowing_observed.definition_node_lookups.get(),
            0,
            "typed reverse narrowing must not issue one point read per demanded definition"
        );
        assert!(narrowing_observed.definition_node_batches.get() > 0);
        assert!(
            narrowing_observed
                .definition_node_batch_sizes
                .borrow()
                .iter()
                .all(|&size| size <= MAX_REVERSE_TARGETS_PER_BATCH)
        );
        let observed = ObservedBatchSource::new(&fixture.service.source);

        let answer = fixture
            .service
            .references_to_from(
                &observed,
                MAX_REFERENCE_SEEDS_PER_BATCH,
                definitions[0],
                &CancellationToken::new(),
            )
            .expect("preload reverse reads are infallible");

        assert_eq!(answer.references(), &[references[0]]);
        assert_eq!(observed.reverse_seed_issues.get(), 1);
        assert_eq!(
            observed.issued_reverse_references.borrow().as_slice(),
            &[references[0]],
            "the same lookup under an unrelated owner must never reach candidate issuance"
        );
    }

    #[test]
    fn typed_reverse_definition_node_batch_is_order_independent_and_exact() {
        let fixture = java_fixture();
        let definition = fixture.definitions[&4];
        let expected_cancellation = CancellationToken::new();
        let mut expected_session = FactReadSession::for_preloaded_service(
            &fixture.service,
            &fixture.service.source,
            &expected_cancellation,
        );
        let mut expected_hierarchy = HierarchyOperationArena::default();
        let expected = TypedReverseNarrowing::new(&mut expected_session, &mut expected_hierarchy)
            .run(definition, &ResolutionCompletion::Complete)
            .expect("preload narrowing reads are infallible");
        let reversed = ObservedBatchSource::with_definition_node_fault(
            &fixture.service.source,
            DefinitionNodeBatchFault::Reverse,
        );
        let actual_cancellation = CancellationToken::new();
        let mut actual_session = FactReadSession::for_preloaded_service(
            &fixture.service,
            &reversed,
            &actual_cancellation,
        );
        let mut actual_hierarchy = HierarchyOperationArena::default();
        let actual = TypedReverseNarrowing::new(&mut actual_session, &mut actual_hierarchy)
            .run(definition, &ResolutionCompletion::Complete)
            .expect("permuted definition-node rows remain a valid bijection");

        assert_eq!(actual.references, expected.references);
        assert_eq!(
            actual.pending_qualified_reasons,
            expected.pending_qualified_reasons
        );
        assert_eq!(actual.completion, expected.completion);
        assert_eq!(reversed.definition_node_lookups.get(), 0);
        assert!(reversed.definition_node_batches.get() > 0);
        assert!(
            reversed
                .definition_node_batch_sizes
                .borrow()
                .iter()
                .all(|&size| size <= MAX_REVERSE_TARGETS_PER_BATCH)
        );

        for fault in [
            DefinitionNodeBatchFault::OmitLast,
            DefinitionNodeBatchFault::DuplicateFirst,
        ] {
            let malformed =
                ObservedBatchSource::with_definition_node_fault(&fixture.service.source, fault);
            let malformed_cancellation = CancellationToken::new();
            let mut malformed_session = FactReadSession::for_preloaded_service(
                &fixture.service,
                &malformed,
                &malformed_cancellation,
            );
            let mut malformed_hierarchy = HierarchyOperationArena::default();
            let panic = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                TypedReverseNarrowing::new(&mut malformed_session, &mut malformed_hierarchy)
                    .run(definition, &ResolutionCompletion::Complete)
            }));
            assert!(
                panic.is_err(),
                "a live malformed definition-node response must fail at its construction boundary"
            );
        }
    }

    #[test]
    fn typed_reverse_definition_node_cancellation_retains_returned_absence() {
        let fixture = java_fixture();
        let definition = fixture.definitions[&4];
        let source = ObservedBatchSource::with_definition_node_fault(
            &fixture.service.source,
            DefinitionNodeBatchFault::AbsentFirstAndCancel,
        );
        let cancellation = CancellationToken::new();
        let mut session =
            FactReadSession::for_preloaded_service(&fixture.service, &source, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();

        let answer = TypedReverseNarrowing::new(&mut session, &mut hierarchy)
            .run(definition, &ResolutionCompletion::Complete)
            .expect("definition-node cancellation is semantic incompleteness");

        assert!(answer.references.is_empty());
        assert!(answer.pending_qualified_reasons.is_empty());
        assert!(
            answer
                .completion
                .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(definition))
        );
        assert!(
            answer
                .completion
                .contains_reason(ResolutionIncompleteReason::Cancelled)
        );
    }

    #[test]
    fn incompatible_qualified_evaluated_miss_replaces_coarse_gap_with_forward_evidence() {
        let mut fixture = parsed_java_service_fixture(
            "class A { int x; } class Use extends Unindexed { int f() { return A.x; } }",
            b"typed-reverse-complete-qualified-miss",
        );
        let definition = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let reference = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Reference,
        )[0];
        let point = fixture
            .service
            .resolve_reference(reference, &CancellationToken::new())
            .expect("preload point reads are infallible");
        assert!(point.binding().targets().is_empty());
        assert_ne!(point.completion(), &ResolutionCompletion::Complete);
        let coarse_reasons = fixture.service.typed.qualified_route_ids_by_reference[&reference]
            .iter()
            .map(|&route_id| {
                fixture.service.typed.qualified_routes[route_id]
                    .row
                    .coarse_gap_reason()
            })
            .collect::<BTreeSet<_>>();
        assert!(!coarse_reasons.is_empty());
        assert!(coarse_reasons.iter().all(|&reason| {
            !point
                .completion()
                .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(reason))
        }));
        let a_definition = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "A",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let use_definition = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "Use",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let hierarchy_reasons_by_owner = fixture
            .typed
            .property_gaps()
            .iter()
            .filter(|gap| gap.kind() == ResolutionGapKind::UnsupportedHierarchyTraversal)
            .map(|gap| (gap.definition(), gap.reason_semantic()))
            .collect::<HashMap<_, _>>();
        let superclass_site = |definition| {
            let edge = fixture
                .typed
                .supertypes()
                .iter()
                .find(|edge| edge.definition() == definition)
                .expect("class has an implicit superclass edge");
            fixture
                .lexical
                .semantics()
                .iter()
                .find(|semantic| {
                    semantic.semantic() == edge.reference()
                        && semantic.role() == LoweredSemanticRole::Reference
                })
                .expect("superclass reference has a source site")
                .site()
        };
        let hierarchy_reason_at = |definition, source_site| {
            fixture
                .typed
                .property_gaps()
                .iter()
                .find(|gap| {
                    gap.definition() == definition
                        && gap.source_site() == source_site
                        && gap.kind() == ResolutionGapKind::UnsupportedHierarchyTraversal
                })
                .expect("the exact superclass reference owns one hierarchy gap")
                .reason_semantic()
        };
        let a_hierarchy_reason = hierarchy_reason_at(a_definition, superclass_site(a_definition));
        let use_hierarchy_reason =
            hierarchy_reason_at(use_definition, superclass_site(use_definition));
        assert_eq!(
            hierarchy_reasons_by_owner[&a_definition],
            a_hierarchy_reason
        );
        assert_eq!(
            hierarchy_reasons_by_owner[&use_definition],
            use_hierarchy_reason
        );
        let reason_multiplicity = |completion: &ResolutionCompletion, semantic| match completion {
            ResolutionCompletion::Complete => 0,
            ResolutionCompletion::Incomplete(reasons) => reasons
                .iter()
                .filter(|&&reason| {
                    reason == ResolutionIncompleteReason::UnsupportedSemantic(semantic)
                })
                .count(),
        };
        // The default aggregate legitimately omits these declaration-site
        // rows. Inject both into the selected raw reverse inventory so this
        // law challenges exact per-origin ownership instead of relying on an
        // incidental source-wide aggregate shape.
        fixture.service.reverse_inventory_completion = fixture
            .service
            .reverse_inventory_completion
            .combine(&ResolutionCompletion::incomplete([
                ResolutionIncompleteReason::UnsupportedSemantic(a_hierarchy_reason),
                ResolutionIncompleteReason::UnsupportedSemantic(use_hierarchy_reason),
            ]));
        for reason in [a_hierarchy_reason, use_hierarchy_reason] {
            assert_eq!(
                reason_multiplicity(&fixture.service.reverse_inventory_completion, reason),
                1,
                "the selected raw inventory carries each exact declaration-site operand once"
            );
        }
        assert!(
            !point
                .completion()
                .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(
                    a_hierarchy_reason
                )),
            "the structurally attempted A-owned branch consumes A's exact hierarchy inventory operand even when compatibility rejects publication"
        );
        assert!(
            point
                .completion()
                .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(
                    use_hierarchy_reason
                )),
            "the unrelated Use hierarchy operand remains semantic"
        );
        assert_eq!(
            reason_multiplicity(point.completion(), a_hierarchy_reason),
            0
        );
        assert_eq!(
            reason_multiplicity(point.completion(), use_hierarchy_reason),
            1
        );
        let observed = ObservedBatchSource::new(&fixture.service.source);
        let reverse_cancellation = CancellationToken::new();
        let mut operation =
            FactResolutionOperation::new(&observed, &fixture.service, &reverse_cancellation);
        let mut metrics = FactReverseResolutionMetrics::default();
        let answer = operation
            .references_to_with_metrics(
                MAX_REFERENCE_SEEDS_PER_BATCH,
                definition,
                &ResolutionCompletion::Complete,
                &mut metrics,
            )
            .expect("preload reverse reads are infallible");

        assert!(answer.references().is_empty());
        assert!(answer.witnesses().is_empty());
        assert_eq!(
            answer.completion(),
            &point.completion().combine(&incomplete(a_hierarchy_reason)),
            "the evaluated miss replaces the route-owned coarse gap but retains A's untraversed outgoing hierarchy operand"
        );
        assert!(coarse_reasons.iter().all(|&reason| {
            !answer
                .completion()
                .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(reason))
        }));
        assert!(answer.completion().contains_reason(
            ResolutionIncompleteReason::UnsupportedSemantic(a_hierarchy_reason)
        ));
        assert!(answer.completion().contains_reason(
            ResolutionIncompleteReason::UnsupportedSemantic(use_hierarchy_reason)
        ));
        assert_eq!(
            reason_multiplicity(answer.completion(), a_hierarchy_reason),
            1
        );
        assert_eq!(
            reason_multiplicity(answer.completion(), use_hierarchy_reason),
            1
        );
        assert_eq!(metrics.issued_reference_seed_count(), 1);
        assert_eq!(metrics.full_fact_evaluation_count(), 1);
        assert_eq!(metrics.published_reference_count(), 0);
        assert_eq!(
            observed.issued_reverse_references.borrow().as_slice(),
            &[reference],
            "an exact slot/owner join must receive one full evaluation before an exact miss"
        );
    }

    #[test]
    fn typed_reverse_handles_constructor_owner_and_type_object_routes() {
        let fixture = parsed_java_service_fixture(
            "class A { int x; static int s; A() {} }\n\
             class Use { int first = new A().x; int second = A.s; }",
            b"typed-reverse-constructor-and-type-object",
        );
        let x_definition = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let x_reference = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Reference,
        )[0];
        let s_definition = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "s",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let s_reference = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "s",
            ResolutionIdentifierRole::Reference,
        )[0];

        let x_point = fixture
            .service
            .resolve_reference(x_reference, &CancellationToken::new())
            .expect("preload point reads are infallible");
        let s_point = fixture
            .service
            .resolve_reference(s_reference, &CancellationToken::new())
            .expect("preload point reads are infallible");
        assert_eq!(x_point.binding().targets(), &[x_definition]);
        assert_eq!(s_point.binding().targets(), &[s_definition]);

        let constructor_owner = fixture
            .service
            .references_to(x_definition, &CancellationToken::new())
            .expect("preload reverse reads are infallible");
        let type_object = fixture
            .service
            .references_to(s_definition, &CancellationToken::new())
            .expect("preload reverse reads are infallible");

        assert_eq!(constructor_owner.references(), &[x_reference]);
        assert_eq!(type_object.references(), &[s_reference]);
        let a_definition = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "A",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let use_definition = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "Use",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let hierarchy_reasons_by_owner = fixture
            .typed
            .property_gaps()
            .iter()
            .filter(|gap| gap.kind() == ResolutionGapKind::UnsupportedHierarchyTraversal)
            .map(|gap| (gap.definition(), gap.reason_semantic()))
            .collect::<HashMap<_, _>>();
        let a_hierarchy_reason = hierarchy_reasons_by_owner[&a_definition];
        let use_hierarchy_reason = hierarchy_reasons_by_owner[&use_definition];
        let reverse_only_hierarchy_reasons = fixture
            .lexical
            .gaps()
            .iter()
            .filter(|gap| {
                gap.origin()
                    == LoweringGapOrigin::Extracted(
                        ResolutionGapKind::UnsupportedHierarchyTraversal,
                    )
                    && gap.frontier()
                        == (LoweringCoverageFrontier::CandidateInventory {
                            direction: LoweredCandidateDirection::Reverse,
                        })
            })
            .map(|gap| gap.reason_semantic())
            .collect::<BTreeSet<_>>();
        assert_eq!(
            reverse_only_hierarchy_reasons.len(),
            2,
            "both top-level class boundaries remain exact source-wide reverse inventory operands"
        );
        assert_eq!(
            reverse_only_hierarchy_reasons,
            BTreeSet::from([a_hierarchy_reason, use_hierarchy_reason]),
            "the reverse inventory hierarchy operands are owned by A and unrelated Use"
        );
        let reason_multiplicity = |completion: &ResolutionCompletion, semantic| match completion {
            ResolutionCompletion::Complete => 0,
            ResolutionCompletion::Incomplete(reasons) => reasons
                .iter()
                .filter(|&&reason| {
                    reason == ResolutionIncompleteReason::UnsupportedSemantic(semantic)
                })
                .count(),
        };
        for (answer, point) in [(&constructor_owner, &x_point), (&type_object, &s_point)] {
            assert_eq!(
                reason_multiplicity(answer.completion(), a_hierarchy_reason),
                1
            );
            assert_eq!(
                reason_multiplicity(answer.completion(), use_hierarchy_reason),
                1
            );
            assert_eq!(
                reason_multiplicity(point.completion(), a_hierarchy_reason),
                0
            );
            assert_eq!(
                answer.completion(),
                &point
                    .completion()
                    .combine(&reverse_inventory_boundary_completion(&fixture)),
                "reverse retains the inventory boundaries, including the direct owner's untraversed outgoing hierarchy operand, while point evaluation keeps its inclusive local cutoff"
            );
        }
    }

    #[test]
    fn typed_reverse_retains_qualified_gap_when_owner_production_is_incomplete() {
        let owner = fragment();
        let mut facts = java_chain_facts();
        facts
            .declaration_type_slots
            .retain(|property| property.declaration != ResolutionSiteId::new(2));
        let lexical = crate::analyzer::resolution::lower_for_test(owner, Language::Java, &facts)
            .lexical()
            .clone();
        let field = lowered_semantic_at(
            &lexical,
            ResolutionSiteId::new(4),
            LoweredSemanticRole::Definition,
        );
        let qualified_reason = lexical
            .gaps()
            .iter()
            .find(|gap| {
                gap.site() == ResolutionSiteId::new(9)
                    && gap.origin() == LoweringGapOrigin::QualifiedReference
                    && gap.frontier()
                        == (LoweringCoverageFrontier::CandidateInventory {
                            direction: LoweredCandidateDirection::Reverse,
                        })
            })
            .expect("qualified reference has a reverse inventory reason")
            .reason_semantic();
        let typed = crate::analyzer::resolution::lower_for_test(owner, Language::Java, &facts)
            .typed()
            .clone();
        let service = PreloadedFactResolutionService::from_lowered_fragments([lexical], [typed]);
        let raw = BatchResolutionEngine::new(&service.source)
            .references_to(field, &CancellationToken::new())
            .expect("raw preload reverse reads are infallible");
        assert_eq!(
            raw.completion(),
            &ResolutionCompletion::Complete,
            "the typed-owned coarse gap must not remain global"
        );

        let answer = service
            .references_to(field, &CancellationToken::new())
            .expect("preload reverse reads are infallible");

        assert!(answer.references().is_empty());
        assert_incomplete_with_reason(answer.completion(), qualified_reason);
    }

    #[test]
    fn typed_reverse_retains_route_gap_when_qualifier_slot_is_never_reached() {
        let mut fixture = java_fixture();
        let reference = fixture.references[&9];
        let route_id = fixture.service.typed.qualified_route_ids_by_reference[&reference][0];
        let route = fixture.service.typed.qualified_routes[route_id];
        let qualifier_slot = route.row.qualifier_slot();
        assert!(
            !fixture
                .service
                .typed
                .projection_by_output
                .contains_key(&qualifier_slot),
            "the Java receiver slot is reached through a transfer, not a direct projection"
        );
        assert!(
            !fixture
                .service
                .typed
                .intrinsic_seed_by_slot
                .contains_key(&qualifier_slot),
            "the Java receiver slot has no intrinsic producer"
        );
        let removed_target_rows = fixture
            .service
            .typed
            .transfers_by_target
            .remove(&qualifier_slot)
            .expect("the selected target relation has one transfer producer");
        let producer_sources = removed_target_rows
            .iter()
            .map(LoweredTypeTransfer::source_slot)
            .collect::<Vec<_>>();
        assert_eq!(producer_sources.len(), 1);
        for source_slot in producer_sources {
            let transfers = fixture
                .service
                .typed
                .transfers_by_source
                .get_mut(&source_slot)
                .expect("the transfer source has a rule index");
            let prior_transfer_count = transfers.len();
            transfers.retain(|transfer| transfer.rule().target_slot() != qualifier_slot);
            assert_eq!(transfers.len() + 1, prior_transfer_count);
        }
        assert!(
            !fixture
                .service
                .typed
                .transfers_by_target
                .contains_key(&qualifier_slot),
            "the adversarial route slot must never enter reached-slot closure"
        );

        let answer = fixture
            .service
            .references_to(fixture.definitions[&4], &CancellationToken::new())
            .expect("preload reverse reads are infallible");

        assert!(answer.references().is_empty());
        assert!(answer.witnesses().is_empty());
        assert_incomplete_with_reason(answer.completion(), route.row.coarse_gap_reason());
    }

