    #[test]
    fn fact_reverse_metrics_retain_partial_source_work_on_store_error() {
        let fixture = java_fixture();
        let source = ObservedBatchSource::failing_forward_match_after_reverse_seed_issue(
            &fixture.service.source,
        );
        let mut metrics = FactReverseResolutionMetrics::default();

        let error = fixture
            .service
            .references_to_from_with_metrics(
                &source,
                MAX_REFERENCE_SEEDS_PER_BATCH,
                fixture.definitions[&4],
                &CancellationToken::new(),
                &mut metrics,
            )
            .expect_err("the scripted forward-match read must fail");

        assert_eq!(
            error.to_string(),
            "scripted fact reverse forward-match failure"
        );
        assert!(metrics.demanded_definition_count() > 0);
        assert!(metrics.raw_reverse_batch_count() > 0);
        assert!(source.forward_match_calls.get() > 1);
        assert_eq!(
            source.forward_match_requests.borrow().len(),
            source.forward_match_calls.get()
        );
        assert!(
            source
                .forward_match_requests
                .borrow()
                .iter()
                .all(|requests| !requests.is_empty()),
            "producer narrowing performs real artifact reads before full validation reaches the scripted failure"
        );
        assert_eq!(metrics.narrowed_distinct_candidate_count(), 1);
        assert_eq!(metrics.issued_reference_seed_count(), 1);
        assert_eq!(metrics.full_fact_evaluation_count(), 1);
        assert_eq!(metrics.published_reference_count(), 0);
    }

