    #[test]
    fn typed_narrowing_uses_exact_two_sided_completion_algebra() {
        let owner = BindingFragmentId::for_test(b"typed-narrowing-two-sided-completion");
        let (service, _) = single_unqualified_reverse_service(owner);
        let cancellation = CancellationToken::new();
        let empty = ResolutionCompletion::Incomplete(Vec::new().into_boxed_slice().into());
        let reason = ResolutionIncompleteReason::UnsupportedSemantic(SemanticId::for_test(
            b"typed-narrowing-two-sided-reason",
        ));
        let nonempty = ResolutionCompletion::Incomplete(vec![reason].into_boxed_slice().into());

        assert!(
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let mut session = FactReadSession::for_preloaded_service(
                    &service,
                    &service.source,
                    &cancellation,
                );
                let mut hierarchy = HierarchyOperationArena::default();
                let mut narrowing = TypedReverseNarrowing::new(&mut session, &mut hierarchy);
                narrowing.include_completion(&empty);
                narrowing.include_completion(&empty);
            }))
            .is_err(),
            "two empty semantic operands must preserve combine's panic"
        );

        for (left, right) in [
            (empty.clone(), nonempty.clone()),
            (nonempty.clone(), empty.clone()),
        ] {
            let mut session =
                FactReadSession::for_preloaded_service(&service, &service.source, &cancellation);
            let mut hierarchy = HierarchyOperationArena::default();
            let mut narrowing = TypedReverseNarrowing::new(&mut session, &mut hierarchy);
            narrowing.include_completion(&left);
            narrowing.include_completion(&right);
            assert_eq!(narrowing.finish_completion(), left.combine(&right));
        }
    }

