    #[test]
    fn typed_narrowing_folds_transfer_completion_once_per_reached_source_slot() {
        let fixture = java_fixture();
        let (&source_slot, _transfers) = fixture
            .service
            .typed
            .transfers_by_source
            .iter()
            .find(|(_, transfers)| {
                !transfers.is_empty()
                    && transfers.iter().all(|transfer| {
                        transfer.rule().completion() == &ResolutionCompletion::Complete
                    })
            })
            .expect("the Java fixture has a completely covered transfer source");
        let first = ResolutionIncompleteReason::UnsupportedSemantic(SemanticId::for_test(
            b"typed-narrowing-transfer-first",
        ));
        let second = ResolutionIncompleteReason::UnsupportedSemantic(SemanticId::for_test(
            b"typed-narrowing-transfer-second",
        ));
        for completion in [
            ResolutionCompletion::Incomplete(Vec::new().into_boxed_slice().into()),
            ResolutionCompletion::Incomplete(vec![second, first, second].into_boxed_slice().into()),
        ] {
            for identities in [
                vec![fixture.definitions[&0]],
                vec![fixture.definitions[&0], fixture.definitions[&1]],
            ] {
                let cancellation = CancellationToken::new();
                let mut session = FactReadSession::for_preloaded_service(
                    &fixture.service,
                    &fixture.service.source,
                    &cancellation,
                );
                let mut hierarchy = HierarchyOperationArena::default();
                let mut narrowing = TypedReverseNarrowing::new(&mut session, &mut hierarchy);
                // This is the insertion-once producer observation performed
                // by `process_reached_slot`; value propagation must never
                // refold it.
                narrowing.include_completion(&completion);
                narrowing
                    .process_reached_slot(source_slot)
                    .expect("preload transfer read is infallible");
                for identity in identities {
                    narrowing
                        .process_slot_value(ReverseSlotValue {
                            slot: source_slot,
                            value: ResolutionSlotValue::runtime(
                                ResolutionTypeRef::new(identity, 0),
                                false,
                            ),
                        })
                        .expect("preload typed row reads are infallible");
                }

                assert_eq!(narrowing.finish_completion(), completion);
            }
        }
    }

    #[test]
    fn typed_narrowing_folds_multi_identity_intrinsic_completion_once() {
        let first = ResolutionIncompleteReason::UnsupportedSemantic(SemanticId::for_test(
            b"typed-narrowing-intrinsic-first",
        ));
        let second = ResolutionIncompleteReason::UnsupportedSemantic(SemanticId::for_test(
            b"typed-narrowing-intrinsic-second",
        ));
        for completion in [
            ResolutionCompletion::Incomplete(Vec::new().into_boxed_slice().into()),
            ResolutionCompletion::Incomplete(vec![second, first, second].into_boxed_slice().into()),
        ] {
            let mut fixture = java_fixture();
            let first_owner = fixture.definitions[&0];
            let second_owner = fixture.definitions[&1];
            let slot = SemanticId::for_test(b"typed-narrowing-multi-identity-intrinsic-slot");
            let owner_fragment = *fixture
                .service
                .typed
                .fragments
                .iter()
                .next()
                .expect("the Java fixture selects one typed fragment");
            let frontier = TypedFrontierState::new(
                slot,
                [
                    ResolutionSlotValue::type_object(ResolutionTypeRef::new(first_owner, 0)),
                    ResolutionSlotValue::type_object(ResolutionTypeRef::new(second_owner, 0)),
                ],
                completion.clone(),
            );
            fixture.service.typed.intrinsic_seed_by_slot.insert(
                slot,
                LoweredIntrinsicSeed::new(IntrinsicTypeKind::Primitive, "test_intrinsic", frontier),
            );
            fixture
                .service
                .typed
                .source_row_fragments
                .insert(slot, owner_fragment);
            for owner in [first_owner, second_owner] {
                fixture
                    .service
                    .typed
                    .intrinsic_slots_by_identity
                    .insert(owner, vec![slot]);
            }
            let cancellation = CancellationToken::new();
            let mut session = FactReadSession::for_preloaded_service(
                &fixture.service,
                &fixture.service.source,
                &cancellation,
            );
            let mut hierarchy = HierarchyOperationArena::default();
            let mut narrowing = TypedReverseNarrowing::new(&mut session, &mut hierarchy);

            narrowing.activate_owner(first_owner);
            narrowing.activate_owner(second_owner);
            narrowing
                .process_owner_batch()
                .expect("preload intrinsic reads are infallible");

            assert_eq!(
                narrowing.typed_semantic_completions,
                vec![completion.clone()],
                "one multi-identity intrinsic stages its exact completion operand once"
            );
            let staged = narrowing
                .typed_semantic_completions
                .pop()
                .expect("one staged intrinsic completion was just asserted");
            narrowing.include_completion(&staged);
            assert_eq!(narrowing.finish_completion(), completion);
            assert_eq!(narrowing.observed_intrinsic_completion_slots.len(), 1);
        }
    }

