    #[test]
    fn typed_reverse_open_route_fanout_polls_within_one_quantum() {
        let mut fixture = java_fixture();
        let reference = fixture.references[&9];
        let route_id = fixture.service.typed.qualified_route_ids_by_reference[&reference][0];
        let route = fixture.service.typed.qualified_routes[route_id];
        let owner = fixture.definitions[&0];
        let scope_head = fixture.service.typed.member_scope_by_definition[&owner];
        let target = fixture.definitions[&4];
        for offset in 1..=CANCELLATION_QUANTUM + 1 {
            let ordinal = route
                .row
                .precedence_ordinal()
                .checked_add(u32::try_from(offset).expect("test route fanout fits u32"))
                .expect("test route ordinal must fit u32");
            let route_id = fixture.service.typed.qualified_routes.len();
            fixture
                .service
                .typed
                .qualified_routes
                .push(SelectedQualifiedRoute {
                    fragment: route.fragment,
                    reference_node: route.reference_node,
                    row: LoweredQualifiedSeededRoute::new(
                        route.row.reference(),
                        route.row.qualifier_slot(),
                        route.row.lookup(),
                        route.row.namespace(),
                        ordinal,
                        route.row.projection_output_slot(),
                        route.row.projection_kind(),
                        SemanticId::for_test(ordinal.to_le_bytes()),
                    ),
                });
            fixture
                .service
                .typed
                .qualified_route_ids_by_qualifier_slot
                .get_mut(&route.row.qualifier_slot())
                .expect("qualified route has a slot index")
                .push(route_id);
        }
        let qualified_routes = &fixture.service.typed.qualified_routes;
        fixture
            .service
            .typed
            .qualified_route_ids_by_qualifier_slot
            .get_mut(&route.row.qualifier_slot())
            .expect("qualified route has a slot index")
            .sort_unstable_by_key(|&route_id| {
                let route = qualified_routes[route_id];
                (
                    route.fragment,
                    route.row.reference(),
                    route.row.precedence_ordinal(),
                )
            });
        let frontier = EndpointSignature::new(
            scope_head,
            StackPattern::open(
                Vec::new(),
                StackVariableId::for_test("typed-reverse-open-fanout"),
            ),
            StackPattern::closed(Vec::new()),
        );
        let cancellation = CancellationToken::cancel_after_checks_for_test(CANCELLATION_QUANTUM);
        let mut session = FactReadSession::for_preloaded_service(
            &fixture.service,
            &fixture.service.source,
            &cancellation,
        );
        let mut hierarchy = HierarchyOperationArena::default();
        let mut narrowing = TypedReverseNarrowing::new(&mut session, &mut hierarchy);
        narrowing.root_definition = Some(target);
        narrowing.member_frontiers_by_owner.insert(
            owner,
            vec![ObservedMemberFrontier {
                id: 0,
                definition: target,
                member_kind: Some(ResolutionMemberKind::Field),
                deferred: None,
                start: frontier,
            }],
        );

        narrowing
            .join_qualified_routes(
                ReverseSlotValue {
                    slot: route.row.qualifier_slot(),
                    value: ResolutionSlotValue::runtime(ResolutionTypeRef::new(owner, 0), false),
                },
                owner,
            )
            .expect("preload route read is infallible");

        assert!(narrowing.cancellation_observed);
        assert!(narrowing.candidate_references.is_empty());
        assert!(narrowing.pending_route_branches.is_empty());
        assert!(
            narrowing
                .finish_completion()
                .contains_reason(ResolutionIncompleteReason::Cancelled)
        );
    }

    #[test]
    fn typed_reverse_large_route_composition_cancels_without_a_candidate_prefix() {
        let fixture = java_fixture();
        let reference = fixture.references[&9];
        let route_id = fixture.service.typed.qualified_route_ids_by_reference[&reference][0];
        let route = fixture.service.typed.qualified_routes[route_id];
        let owner = fixture.definitions[&0];
        let scope_head = fixture.service.typed.member_scope_by_definition[&owner];
        let target = fixture.definitions[&4];
        let frontier = EndpointSignature::new(
            scope_head,
            StackPattern::open(
                std::iter::repeat_n(route.row.lookup(), CANCELLATION_QUANTUM + 1)
                    .collect::<Vec<_>>(),
                StackVariableId::for_test("typed-reverse-large-composition"),
            ),
            StackPattern::closed(Vec::new()),
        );
        // Let the selected-row read exhaust, then cancel from the structural
        // poll inside the one >quantum endpoint composition.
        let cancellation = CancellationToken::cancel_after_checks_for_test(22);
        let mut session = FactReadSession::for_preloaded_service(
            &fixture.service,
            &fixture.service.source,
            &cancellation,
        );
        let mut hierarchy = HierarchyOperationArena::default();
        let mut narrowing = TypedReverseNarrowing::new(&mut session, &mut hierarchy);
        narrowing.root_definition = Some(target);
        narrowing.member_frontiers_by_owner.insert(
            owner,
            vec![ObservedMemberFrontier {
                id: 0,
                definition: target,
                member_kind: Some(ResolutionMemberKind::Field),
                deferred: None,
                start: frontier,
            }],
        );

        narrowing
            .join_qualified_routes(
                ReverseSlotValue {
                    slot: route.row.qualifier_slot(),
                    value: ResolutionSlotValue::runtime(ResolutionTypeRef::new(owner, 0), false),
                },
                owner,
            )
            .expect("preload route read is infallible");

        assert!(narrowing.cancellation_observed);
        assert!(
            narrowing.work >= CANCELLATION_QUANTUM,
            "the token must reach the >quantum structural join, not cancel in source setup: work={}",
            narrowing.work,
        );
        assert!(narrowing.candidate_references.is_empty());
        assert!(
            narrowing
                .route_reason_obligations
                .contains(&(route.row.reference(), route.row.coarse_gap_reason()))
        );
        let completion = narrowing.finish_completion();
        assert!(
            completion.contains_reason(ResolutionIncompleteReason::Cancelled),
            "cancellation inside one exact stack join must not become a complete route mismatch"
        );
    }

