    #[test]
    fn java_implicit_constructor_projects_nominal_runtime_value_through_chained_call() {
        let source = "public class Product { public int changed() { return 1; } } \
                      class Use { int run() { return new Product().changed(); } }";
        let fixture = parsed_java_service_fixture(source, b"java-implicit-constructor-result");
        let product_site = positioned_site_at(
            &fixture.facts,
            source.find("Product").expect("Product declaration"),
            ResolutionIdentifierRole::Declaration,
            ResolutionNamespace::Type,
        );
        let product = lowered_semantic_at(
            &fixture.lexical,
            product_site,
            LoweredSemanticRole::Definition,
        );
        let constructor_position = source
            .rfind("new Product")
            .expect("implicit constructor call")
            + "new ".len();
        let constructor_site = positioned_site_at(
            &fixture.facts,
            constructor_position,
            ResolutionIdentifierRole::Reference,
            ResolutionNamespace::Constructor,
        );
        let constructor_reference = lowered_semantic_at(
            &fixture.lexical,
            constructor_site,
            LoweredSemanticRole::Reference,
        );
        let qualifier_site = positioned_site_at(
            &fixture.facts,
            constructor_position,
            ResolutionIdentifierRole::Reference,
            ResolutionNamespace::Type,
        );
        let qualifier_reference = lowered_semantic_at(
            &fixture.lexical,
            qualifier_site,
            LoweredSemanticRole::Reference,
        );
        let qualifier = fixture
            .service
            .resolve_reference(qualifier_reference, &CancellationToken::new())
            .expect("the constructed type qualifier is source-readable");
        assert_eq!(qualifier.binding().targets(), &[product]);
        assert_eq!(
            only_projected_value(&qualifier),
            ResolutionSlotValue::type_object(ResolutionTypeRef::new(product, 0))
        );
        let implicit_constructor_reason = fixture
            .typed
            .property_gaps()
            .iter()
            .find(|gap| {
                gap.definition() == product && gap.kind() == ResolutionGapKind::ImplicitConstructor
            })
            .expect("Product has one implicit-constructor property gap")
            .reason_semantic();
        let hierarchy_reason = fixture
            .typed
            .property_gaps()
            .iter()
            .find(|gap| {
                gap.definition() == product
                    && gap.kind() == ResolutionGapKind::UnsupportedHierarchyTraversal
            })
            .expect("Product has one implicit-hierarchy property gap")
            .reason_semantic();
        let applicability_reason = fixture
            .typed
            .call_obligations()
            .iter()
            .find(|obligation| obligation.callee_reference() == constructor_reference)
            .expect("the implicit constructor call has one applicability obligation")
            .applicability_reason();
        // Constructors are not inherited (JLS 8.8) and java.lang.Object
        // declares methods only (JLS 4.3.2), so Product's implicit superclass
        // edge does not answer this constructor lookup. The lookup finds no
        // declared constructor, so its member scope's outward continuation
        // reaches the compilation unit's placement boundary, which stays
        // conservatively open beside the implicit-constructor gap.
        let placement_reason = fixture
            .lexical
            .gaps()
            .iter()
            .find(|gap| {
                gap.origin()
                    == LoweringGapOrigin::Extracted(ResolutionGapKind::UnsupportedPlacementBoundary)
            })
            .expect("the compilation unit has placement evidence")
            .reason_semantic();
        let expected_completion =
            qualifier
                .completion()
                .combine(&ResolutionCompletion::incomplete([
                    ResolutionIncompleteReason::UnsupportedSemantic(placement_reason),
                    ResolutionIncompleteReason::UnsupportedSemantic(implicit_constructor_reason),
                    ResolutionIncompleteReason::UnsupportedSemantic(applicability_reason),
                ]));
        assert!(!expected_completion.contains_reason(
            ResolutionIncompleteReason::UnsupportedSemantic(hierarchy_reason)
        ));
        let result_slot = fixture
            .typed
            .projections()
            .iter()
            .find(|projection| {
                projection.reference() == constructor_reference
                    && projection.kind() == BindingProjectionKind::TargetConstructorOwnerType
            })
            .expect("the implicit constructor call has one nominal result projection")
            .output_slot();

        let constructor = fixture
            .service
            .resolve_reference(constructor_reference, &CancellationToken::new())
            .expect("the implicit constructor reference is source-readable");
        assert!(constructor.binding().targets().is_empty());
        assert!(constructor.binding().witnesses().is_empty());
        assert_eq!(constructor.binding().completion(), &expected_completion);
        assert_eq!(
            constructor.projected_frontiers(),
            &[TypedFrontierState::new(
                result_slot,
                [ResolutionSlotValue::runtime(
                    ResolutionTypeRef::new(product, 0),
                    false,
                )],
                expected_completion.clone(),
            )]
        );
        assert_eq!(constructor.completion(), &expected_completion);

        let changed_definition = java_callable_definition_at(
            &fixture,
            source.find("changed").expect("changed declaration"),
        );
        let changed_position = source.rfind(".changed").expect("chained changed call") + 1;
        let changed_site = positioned_site_at(
            &fixture.facts,
            changed_position,
            ResolutionIdentifierRole::Reference,
            ResolutionNamespace::Callable,
        );
        let changed_reference = lowered_semantic_at(
            &fixture.lexical,
            changed_site,
            LoweredSemanticRole::Reference,
        );
        let changed = fixture
            .service
            .resolve_reference(changed_reference, &CancellationToken::new())
            .expect("the chained call is source-readable");
        assert_eq!(changed.binding().targets(), &[changed_definition]);
        assert_eq!(changed.binding().witnesses().len(), 1);
        assert!(
            changed
                .binding()
                .witnesses()
                .iter()
                .all(|witness| witness.target() == changed_definition)
        );
        assert_eq!(changed.completion(), &expected_completion);
        assert_eq!(
            changed.callable_receiver_dispositions(),
            &[FactCallableReceiverTargetDisposition::new(
                changed_definition,
                FactCallableReceiverDisposition::external(),
            )],
            "the constructor result closes only the runtime receiver category while binding evidence remains incomplete"
        );

        let mut metrics = FactReverseResolutionMetrics::default();
        let reverse = fixture
            .service
            .references_to_with_metrics(changed_definition, &CancellationToken::new(), &mut metrics)
            .expect("the chained target is reverse-readable");
        assert_eq!(reverse.references(), &[changed_reference]);
        assert_eq!(reverse.witnesses().len(), 1);
        assert!(
            reverse
                .witnesses()
                .iter()
                .all(|witness| witness.target() == changed_definition)
        );
        assert_eq!(metrics.full_fact_evaluation_count(), 1);
        assert_eq!(metrics.published_reference_count(), 1);
    }

    #[test]
    fn java_default_construction_proves_an_exact_public_superclass_chain() {
        let source = "package java.lang; public class Object { public static class Generated { \
                          public static class BaseWorker {} \
                          public static class Module extends BaseWorker {} \
                          public static Module make() { return new Module(); } \
                      } }";
        let fixture = parsed_java_service_fixture(source, b"java-default-construction-proof");
        let module_site = positioned_site_at(
            &fixture.facts,
            source.find("Module extends").expect("Module declaration"),
            ResolutionIdentifierRole::Declaration,
            ResolutionNamespace::Type,
        );
        let module = lowered_semantic_at(
            &fixture.lexical,
            module_site,
            LoweredSemanticRole::Definition,
        );
        let base_site = positioned_site_at(
            &fixture.facts,
            source
                .find("BaseWorker {}")
                .expect("BaseWorker declaration"),
            ResolutionIdentifierRole::Declaration,
            ResolutionNamespace::Type,
        );
        let base =
            lowered_semantic_at(&fixture.lexical, base_site, LoweredSemanticRole::Definition);
        let object_site = positioned_site_at(
            &fixture.facts,
            source.find("Object {").unwrap(),
            ResolutionIdentifierRole::Declaration,
            ResolutionNamespace::Type,
        );
        let object = lowered_semantic_at(
            &fixture.lexical,
            object_site,
            LoweredSemanticRole::Definition,
        );
        let root_edge = fixture
            .typed
            .supertypes()
            .iter()
            .find(|edge| {
                edge.definition() == base
                    && edge.kind() == ResolutionSupertypeKind::ImplicitSuperclass
            })
            .expect("BaseWorker retains its implicit Object edge");
        let constructor_position =
            source.rfind("new Module").expect("Module construction") + "new ".len();
        let constructor_site = positioned_site_at(
            &fixture.facts,
            constructor_position,
            ResolutionIdentifierRole::Reference,
            ResolutionNamespace::Constructor,
        );
        let constructor_reference = lowered_semantic_at(
            &fixture.lexical,
            constructor_site,
            LoweredSemanticRole::Reference,
        );
        let obligation = fixture
            .typed
            .call_obligations()
            .iter()
            .find(|obligation| obligation.callee_reference() == constructor_reference)
            .expect("the default construction has one call obligation");
        let route = fixture
            .typed
            .qualified_routes()
            .iter()
            .find(|route| route.reference() == constructor_reference)
            .expect("the default construction has one constructor route");
        let superclass = fixture
            .typed
            .supertypes()
            .iter()
            .find(|supertype| {
                supertype.definition() == module
                    && supertype.kind() == ResolutionSupertypeKind::Superclass
            })
            .expect("Module has one explicit superclass frontier");
        let discharged = fixture
            .typed
            .property_gaps()
            .iter()
            .filter(|gap| {
                matches!(gap.definition(), definition if definition == module || definition == base || definition == object)
                    && matches!(
                        gap.kind(),
                        ResolutionGapKind::ImplicitConstructor
                            | ResolutionGapKind::UnsupportedHierarchyTraversal
                    )
            })
            .map(|gap| gap.reason_semantic())
            .collect::<BTreeSet<_>>();
        assert_eq!(
            discharged.len(),
            5,
            "three constructor markers and two represented superclass frontiers"
        );
        let dependency_completion = ResolutionCompletion::incomplete(
            discharged
                .iter()
                .copied()
                .map(ResolutionIncompleteReason::UnsupportedSemantic),
        );
        let mut call_reasons = discharged.clone();
        call_reasons.insert(obligation.applicability_reason());
        let call_completion = ResolutionCompletion::incomplete(
            call_reasons
                .iter()
                .copied()
                .map(ResolutionIncompleteReason::UnsupportedSemantic),
        );
        let states = [
            (
                root_edge.frontier(),
                TypedFrontierState::new(
                    root_edge.frontier(),
                    [ResolutionSlotValue::type_object(ResolutionTypeRef::new(
                        object, 0,
                    ))],
                    dependency_completion.clone(),
                ),
            ),
            (
                route.qualifier_slot(),
                TypedFrontierState::new(
                    route.qualifier_slot(),
                    [ResolutionSlotValue::type_object(ResolutionTypeRef::new(
                        module, 0,
                    ))],
                    dependency_completion.clone(),
                ),
            ),
            (
                superclass.frontier(),
                TypedFrontierState::new(
                    superclass.frontier(),
                    [ResolutionSlotValue::type_object(ResolutionTypeRef::new(
                        base, 0,
                    ))],
                    dependency_completion,
                ),
            ),
        ]
        .into_iter()
        .collect::<HashMap<_, _>>();
        let cancellation = CancellationToken::new();
        let mut session = preloaded_session(&fixture.service, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut evaluation =
            FactEvaluation::new(&mut session, &mut hierarchy, constructor_reference);
        match evaluation
            .prove_default_construction(obligation, true, &shared_map(&states), &call_completion)
            .expect("preloaded default-construction proof is infallible")
        {
            SemanticDischargeProof::Proven(actual) => assert_eq!(actual, discharged),
            proof => panic!("exact default-construction chain was not proven: {proof:?}"),
        }

        let mut missing_root = states.clone();
        missing_root.remove(&root_edge.frontier());
        assert!(
            matches!(
                evaluation
                    .prove_default_construction(
                        obligation,
                        true,
                        &shared_map(&missing_root),
                        &call_completion,
                    )
                    .unwrap(),
                SemanticDischargeProof::Unproven
            ),
            "a missing Object dependency cannot prove construction"
        );

        let unrelated = SemanticId::for_test(b"unrelated-default-construction-frontier");
        let open_call = call_completion.combine(&incomplete(unrelated));
        assert!(matches!(
            evaluation
                .prove_default_construction(obligation, true, &shared_map(&states), &open_call)
                .expect("preloaded open default-construction proof is infallible"),
            SemanticDischargeProof::Unproven
        ));
        let mut open_states = states.clone();
        let superclass_state = &states[&superclass.frontier()];
        open_states.insert(
            superclass.frontier(),
            TypedFrontierState::new(
                superclass.frontier(),
                superclass_state.possible_values().to_vec(),
                superclass_state
                    .completion()
                    .combine(&incomplete(unrelated)),
            ),
        );
        assert!(matches!(
            evaluation
                .prove_default_construction(
                    obligation,
                    true,
                    &shared_map(&open_states),
                    &call_completion,
                )
                .expect("preloaded open superclass proof is infallible"),
            SemanticDischargeProof::Unproven
        ));

        // A closed-state theorem oracle is not a claim that the whole parsed
        // fixed point has closed these dependencies. Exercise its positive
        // discharge through the actual framed post-reference phase as well.
        let observed = ObservedBatchSource::new(&fixture.service.source);
        let mut session =
            FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut artifacts = ForwardCandidateArtifactCache::default();
        let mut evaluation =
            FactEvaluation::new(&mut session, &mut hierarchy, constructor_reference);
        let call_read = evaluation
            .session
            .calls_for_references(&[constructor_reference])
            .unwrap();
        let calls = evaluation.accept_session_read(call_read).unwrap();
        let [call] = calls.as_slice() else {
            panic!("the constructor has exactly one source obligation");
        };
        let mut task = DemandFactEvaluationTask::new(evaluation.into_checkpoint_state());
        task.phase = DemandFactEvaluationPhase::References;
        task.states = shared_map(&states);
        task.references = Some(DemandReferenceEvaluationFrame {
            references: vec![constructor_reference],
            cursor: 1,
            routes: HashMap::default(),
            calls: [(constructor_reference, *call)].into_iter().collect(),
            answers: [(
                constructor_reference,
                std::sync::Arc::new(ResolutionAnswer::new(
                    Vec::new(),
                    Vec::new(),
                    call_completion,
                )),
            )]
            .into_iter()
            .collect(),
            active: None,
            qualified: None,
            root_metadata: None,
            lexical_hierarchy: None,
        });
        assert!(matches!(
            task.poll_with_readiness(
                &mut session,
                &mut hierarchy,
                &mut artifacts,
                &mut |_| panic!("post-reference constructor proof cannot request candidates"),
            )
            .unwrap(),
            DemandFactEvaluationPoll::Continue
        ));
        assert_eq!(
            *task.answers[&constructor_reference],
            ResolutionAnswer::new(Vec::new(), Vec::new(), ResolutionCompletion::Complete),
            "the framed post-reference phase must discharge the exact closed-state chain"
        );
        assert_eq!(observed.forward_match_calls.get(), 0);
        assert_eq!(observed.path_hydration_calls.get(), 0);
    }

    #[test]
    fn java_direct_owner_exact_primitive_proof_keeps_unrelated_frontiers_open() {
        let source = "public class Generated { \
                          public static class BaseWorker {} \
                          public static class Module00000 extends BaseWorker { \
                              public int changed(int value) { return value; } \
                          } \
                          public int predecessor(Module00000 previous, int value) { \
                              return previous.changed(value); \
                          } \
                      }";
        let fixture = parsed_java_service_fixture(source, b"java-direct-owner-primitive-proof");
        let module_site = positioned_site_at(
            &fixture.facts,
            source
                .find("Module00000 extends")
                .expect("Module00000 declaration"),
            ResolutionIdentifierRole::Declaration,
            ResolutionNamespace::Type,
        );
        let module = lowered_semantic_at(
            &fixture.lexical,
            module_site,
            LoweredSemanticRole::Definition,
        );
        let target = java_callable_definition_at(
            &fixture,
            source.find("changed(int").expect("changed declaration"),
        );
        let call_position = source.rfind("changed(value)").expect("changed call");
        let call_site = positioned_site_at(
            &fixture.facts,
            call_position,
            ResolutionIdentifierRole::Reference,
            ResolutionNamespace::Callable,
        );
        let call_reference =
            lowered_semantic_at(&fixture.lexical, call_site, LoweredSemanticRole::Reference);
        let obligation = fixture
            .typed
            .call_obligations()
            .iter()
            .find(|obligation| obligation.callee_reference() == call_reference)
            .expect("the direct-owner call has one applicability obligation");
        let signature = fixture
            .typed
            .callable_signatures()
            .iter()
            .find(|signature| signature.definition() == target)
            .expect("the direct-owner target has one signature");
        let receiver_slot = obligation
            .receiver_slot()
            .expect("the qualified call has a receiver slot");
        let receiver_transfers = fixture
            .typed
            .transfers()
            .iter()
            .filter(|transfer| {
                transfer.kind() == ResolutionTypeTransferKind::Receiver
                    && transfer.rule().target_slot() == receiver_slot
            })
            .collect::<Vec<_>>();
        let [receiver_transfer] = receiver_transfers.as_slice() else {
            panic!("the explicit receiver has one source transfer")
        };
        let receiver_projections = fixture
            .typed
            .projections()
            .iter()
            .filter(|projection| projection.output_slot() == receiver_transfer.source_slot())
            .collect::<Vec<_>>();
        let [receiver_projection] = receiver_projections.as_slice() else {
            panic!("the explicit receiver source has one binding projection")
        };
        assert_eq!(
            receiver_projection.kind(),
            BindingProjectionKind::TargetTypeOrDeclaredValueType
        );
        let receiver_reference = receiver_projection.reference();
        let parameter_site = positioned_site_at(
            &fixture.facts,
            source.find("previous,").expect("previous declaration"),
            ResolutionIdentifierRole::Declaration,
            ResolutionNamespace::Value,
        );
        let parameter = lowered_semantic_at(
            &fixture.lexical,
            parameter_site,
            LoweredSemanticRole::Definition,
        );
        let hierarchy_reasons = fixture
            .typed
            .property_gaps()
            .iter()
            .filter(|gap| {
                gap.definition() == module
                    && gap.kind() == ResolutionGapKind::UnsupportedHierarchyTraversal
            })
            .map(|gap| gap.reason_semantic())
            .collect::<BTreeSet<_>>();
        assert_eq!(hierarchy_reasons.len(), 1);
        let receiver_completion = ResolutionCompletion::incomplete(
            hierarchy_reasons
                .iter()
                .copied()
                .map(ResolutionIncompleteReason::UnsupportedSemantic),
        );
        let primitive = fixture
            .typed
            .intrinsic_seeds()
            .iter()
            .find(|seed| seed.kind() == IntrinsicTypeKind::Primitive)
            .and_then(|seed| seed.frontier().possible_values().first())
            .map(|value| value.ty())
            .expect("the source-owned int syntax has an intrinsic identity");
        let argument_slot = obligation.argument_slots()[0];
        let parameter_slot = signature.parameters()[0].slot();
        let states = [
            (
                receiver_slot,
                TypedFrontierState::new(
                    receiver_slot,
                    [ResolutionSlotValue::runtime(
                        ResolutionTypeRef::new(module, 0),
                        false,
                    )],
                    receiver_completion.clone(),
                ),
            ),
            (
                argument_slot,
                TypedFrontierState::new(
                    argument_slot,
                    [ResolutionSlotValue::runtime(primitive, false)],
                    ResolutionCompletion::Complete,
                ),
            ),
            (
                parameter_slot,
                TypedFrontierState::new(
                    parameter_slot,
                    [ResolutionSlotValue::runtime(primitive, false)],
                    ResolutionCompletion::Complete,
                ),
            ),
        ]
        .into_iter()
        .collect::<HashMap<_, _>>();
        let mut call_reasons = hierarchy_reasons.clone();
        call_reasons.insert(obligation.applicability_reason());
        let call_completion = ResolutionCompletion::incomplete(
            call_reasons
                .iter()
                .copied()
                .map(ResolutionIncompleteReason::UnsupportedSemantic),
        );
        let cancellation = CancellationToken::new();
        let lexical_answer = BatchResolutionEngine::new(&fixture.service.source)
            .resolve_reference(ResolutionQuery::new(receiver_reference), &cancellation)
            .expect("the receiver's lexical binding is source-readable");
        assert_eq!(lexical_answer.targets(), &[parameter]);
        assert_eq!(
            lexical_answer.completion(),
            &ResolutionCompletion::Complete,
            "the nearer value route must exactly shadow the TypeOrValue type route"
        );
        let mut session = preloaded_session(&fixture.service, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut evaluation = FactEvaluation::new(&mut session, &mut hierarchy, call_reference);
        assert!(
            evaluation
                .lexical_answers
                .insert(
                    receiver_reference,
                    std::sync::Arc::new(lexical_answer.clone())
                )
                .is_none()
        );
        match evaluation
            .prove_direct_owner_exact_primitive_dominance(
                target,
                obligation,
                signature,
                &shared_map(&states),
                &call_completion,
            )
            .expect("preloaded direct-owner proof is infallible")
        {
            SemanticDischargeProof::Proven(actual) => assert_eq!(actual, hierarchy_reasons),
            proof => panic!("exact direct-owner primitive call was not proven: {proof:?}"),
        }

        assert_eq!(
            evaluation
                .explicit_receiver_runtime_category_closed(receiver_slot, &shared_map(&states))
                .expect("preloaded receiver-category proof is infallible"),
            Some(true),
            "an exact value-only TypeOrValue binding closes the receiver category"
        );
        let unrelated = SemanticId::for_test(b"unrelated-direct-owner-frontier");

        let mut missing_session = preloaded_session(&fixture.service, &cancellation);
        let mut missing_hierarchy = HierarchyOperationArena::default();
        let mut missing_answer =
            FactEvaluation::new(&mut missing_session, &mut missing_hierarchy, call_reference);
        assert_eq!(
            missing_answer
                .explicit_receiver_runtime_category_closed(receiver_slot, &shared_map(&states))
                .expect("preloaded missing-answer proof is infallible"),
            Some(false),
            "a missing lexical answer cannot close a TypeOrValue category"
        );

        let mut open_session = preloaded_session(&fixture.service, &cancellation);
        let mut open_hierarchy = HierarchyOperationArena::default();
        let mut open_answer =
            FactEvaluation::new(&mut open_session, &mut open_hierarchy, call_reference);
        assert!(
            open_answer
                .lexical_answers
                .insert(
                    receiver_reference,
                    std::sync::Arc::new(ResolutionAnswer::new(
                        lexical_answer.targets().to_vec(),
                        lexical_answer.witnesses().to_vec(),
                        incomplete(unrelated),
                    )),
                )
                .is_none()
        );
        assert_eq!(
            open_answer
                .explicit_receiver_runtime_category_closed(receiver_slot, &shared_map(&states))
                .expect("preloaded open-answer proof is infallible"),
            Some(false),
            "an open lexical target set cannot close a TypeOrValue category"
        );

        let mut empty_session = preloaded_session(&fixture.service, &cancellation);
        let mut empty_hierarchy = HierarchyOperationArena::default();
        let mut empty_answer =
            FactEvaluation::new(&mut empty_session, &mut empty_hierarchy, call_reference);
        assert!(
            empty_answer
                .lexical_answers
                .insert(
                    receiver_reference,
                    std::sync::Arc::new(ResolutionAnswer::new(
                        Vec::new(),
                        Vec::new(),
                        ResolutionCompletion::Complete,
                    )),
                )
                .is_none()
        );
        assert_eq!(
            empty_answer
                .explicit_receiver_runtime_category_closed(receiver_slot, &shared_map(&states))
                .expect("preloaded empty-answer proof is infallible"),
            Some(false),
            "an exact negative lexical answer cannot explain a runtime receiver"
        );

        let mut type_session = preloaded_session(&fixture.service, &cancellation);
        let mut type_hierarchy = HierarchyOperationArena::default();
        let mut type_answer =
            FactEvaluation::new(&mut type_session, &mut type_hierarchy, call_reference);
        assert!(
            type_answer
                .lexical_answers
                .insert(
                    receiver_reference,
                    std::sync::Arc::new(ResolutionAnswer::new(
                        [module],
                        Vec::new(),
                        ResolutionCompletion::Complete,
                    )),
                )
                .is_none()
        );
        assert_eq!(
            type_answer
                .explicit_receiver_runtime_category_closed(receiver_slot, &shared_map(&states))
                .expect("preloaded type-answer proof is infallible"),
            Some(false),
            "a selected member-scope target retains the type-object category"
        );

        let open_call = call_completion.combine(&incomplete(unrelated));
        assert!(matches!(
            evaluation
                .prove_direct_owner_exact_primitive_dominance(
                    target,
                    obligation,
                    signature,
                    &shared_map(&states),
                    &open_call,
                )
                .expect("preloaded open direct-owner proof is infallible"),
            SemanticDischargeProof::Unproven
        ));
        let mut type_object_receiver = states.clone();
        type_object_receiver.insert(
            receiver_slot,
            TypedFrontierState::new(
                receiver_slot,
                [ResolutionSlotValue::type_object(ResolutionTypeRef::new(
                    module, 0,
                ))],
                receiver_completion,
            ),
        );
        assert_eq!(
            evaluation
                .explicit_receiver_runtime_category_closed(
                    receiver_slot,
                    &shared_map(&type_object_receiver)
                )
                .expect("preloaded type-object receiver proof is infallible"),
            Some(false)
        );

        let cancelled = CancellationToken::new();
        let mut cancelled_session = preloaded_session(&fixture.service, &cancelled);
        let mut cancelled_hierarchy = HierarchyOperationArena::default();
        let mut cancelled_evaluation = FactEvaluation::new(
            &mut cancelled_session,
            &mut cancelled_hierarchy,
            call_reference,
        );
        assert!(
            cancelled_evaluation
                .lexical_answers
                .insert(receiver_reference, std::sync::Arc::new(lexical_answer))
                .is_none()
        );
        cancelled.cancel();
        assert_eq!(
            cancelled_evaluation
                .explicit_receiver_runtime_category_closed(receiver_slot, &shared_map(&states))
                .expect("cancelled receiver-category reads remain infallible"),
            None,
            "cancellation must discard the staged category proof"
        );
        assert!(cancelled_evaluation.cancellation_observed);
    }

    #[test]
    fn java_constructor_result_closes_only_the_explicit_receiver_category() {
        let source = "public class Generated { \
                          public static class Module { \
                              public int changed(int value) { return value; } \
                          } \
                          public int run() { return new Module().changed(1); } \
                      }";
        let fixture = parsed_java_service_fixture(source, b"java-constructor-receiver-category");
        let module_site = positioned_site_at(
            &fixture.facts,
            source.find("Module {").expect("Module declaration"),
            ResolutionIdentifierRole::Declaration,
            ResolutionNamespace::Type,
        );
        let module = lowered_semantic_at(
            &fixture.lexical,
            module_site,
            LoweredSemanticRole::Definition,
        );
        let call_position = source.rfind("changed(1)").expect("changed call");
        let call_site = positioned_site_at(
            &fixture.facts,
            call_position,
            ResolutionIdentifierRole::Reference,
            ResolutionNamespace::Callable,
        );
        let call_reference =
            lowered_semantic_at(&fixture.lexical, call_site, LoweredSemanticRole::Reference);
        let receiver_slot = fixture
            .typed
            .call_obligations()
            .iter()
            .find(|obligation| obligation.callee_reference() == call_reference)
            .and_then(LoweredCallApplicabilityObligation::receiver_slot)
            .expect("the chained call has an explicit receiver slot");
        let unrelated = SemanticId::for_test(b"unrelated-constructor-receiver-owner");
        let states = [(
            receiver_slot,
            TypedFrontierState::new(
                receiver_slot,
                [ResolutionSlotValue::runtime(
                    ResolutionTypeRef::new(module, 0),
                    false,
                )],
                incomplete(unrelated),
            ),
        )]
        .into_iter()
        .collect::<HashMap<_, _>>();
        let cancellation = CancellationToken::new();
        let mut session = preloaded_session(&fixture.service, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut evaluation = FactEvaluation::new(&mut session, &mut hierarchy, call_reference);
        assert_eq!(
            evaluation
                .explicit_receiver_runtime_category_closed(receiver_slot, &shared_map(&states))
                .expect("preloaded receiver-category proof is infallible"),
            Some(true),
            "an open constructor result may gain runtime owners but no type-object category"
        );

        let type_object_states = [(
            receiver_slot,
            TypedFrontierState::new(
                receiver_slot,
                [ResolutionSlotValue::type_object(ResolutionTypeRef::new(
                    module, 0,
                ))],
                incomplete(unrelated),
            ),
        )]
        .into_iter()
        .collect::<HashMap<_, _>>();
        assert_eq!(
            evaluation
                .explicit_receiver_runtime_category_closed(
                    receiver_slot,
                    &shared_map(&type_object_states)
                )
                .expect("preloaded type-object category proof is infallible"),
            Some(false)
        );
    }

    #[test]
    fn java_default_construction_near_misses_remain_incomplete() {
        // The abstract-superclass case is deliberately conservative: JLS
        // supplies Base's default constructor, but this tranche has no
        // separate source-owned row for constructor existence versus direct
        // instantiability, so constructing Product cannot yet be proven.
        for (label, source) in [
            (
                b"record".as_slice(),
                "public record Product() { static Product make() { return new Product(); } }",
            ),
            (
                b"direct-abstract".as_slice(),
                "public abstract class Product { static Product make() { return new Product(); } }",
            ),
            (
                b"abstract-superclass".as_slice(),
                "public abstract class Base {} public class Product extends Base { static Product make() { return new Product(); } }",
            ),
            (
                b"inner".as_slice(),
                "public class Outer { public class Product {} Product make() { return new Product(); } }",
            ),
            (
                b"explicit-super-constructor".as_slice(),
                "public class Base { public Base() {} } public class Product extends Base { static Product make() { return new Product(); } }",
            ),
        ] {
            let fixture = parsed_java_service_fixture(source, label);
            let constructor_position =
                source.rfind("new Product").expect("Product construction") + "new ".len();
            let (answer, applicability_reason) =
                resolve_java_constructor_call_at(&fixture, constructor_position);
            assert_incomplete_with_reason(answer.binding().completion(), applicability_reason);
            assert_incomplete_with_reason(answer.completion(), applicability_reason);
        }
    }

    #[test]
    fn java_ambiguous_constructor_qualifier_preserves_each_nominal_runtime_value() {
        let mut facts = java_chain_facts();
        let second_type = facts
            .identifiers
            .iter_mut()
            .find(|identifier| {
                identifier.site == ResolutionSiteId::new(1)
                    && identifier.role == ResolutionIdentifierRole::Declaration
                    && identifier.namespace == ResolutionNamespace::Type
            })
            .expect("the synthetic Java fixture has a second type declaration");
        second_type.name = ResolutionNameId::new(0);
        facts.gaps.push(ResolutionGapFact {
            site: ResolutionSiteId::new(1),
            kind: ResolutionGapKind::ImplicitConstructor,
        });
        let fixture = java_fixture_from_facts(facts);
        let mut expected_types = vec![fixture.definitions[&0], fixture.definitions[&1]];
        expected_types.sort_unstable();

        let qualifier = fixture
            .service
            .resolve_reference(fixture.references[&17], &CancellationToken::new())
            .expect("the ambiguous constructor qualifier is source-readable");
        assert_eq!(qualifier.binding().targets(), expected_types);

        let constructor_reference = fixture.references[&18];
        let constructor = fixture
            .service
            .resolve_reference(constructor_reference, &CancellationToken::new())
            .expect("the explicitly and implicitly constructed types are source-readable");
        assert_eq!(constructor.binding().targets(), &[fixture.definitions[&6]]);
        let result_slot = fixture
            .typed
            .projections()
            .iter()
            .find(|projection| {
                projection.reference() == constructor_reference
                    && projection.kind() == BindingProjectionKind::TargetConstructorOwnerType
            })
            .expect("the constructor has one nominal result projection")
            .output_slot();
        let mut expected_values = expected_types
            .into_iter()
            .map(|definition| {
                ResolutionSlotValue::runtime(ResolutionTypeRef::new(definition, 0), false)
            })
            .collect::<Vec<_>>();
        expected_values.sort_unstable();
        assert_eq!(constructor.projected_frontiers().len(), 1);
        assert_eq!(constructor.projected_frontiers()[0].slot(), result_slot);
        assert_eq!(
            constructor.projected_frontiers()[0].possible_values(),
            expected_values
        );

        let implicit_constructor_reason = fixture
            .typed
            .property_gaps()
            .iter()
            .find(|gap| {
                gap.definition() == fixture.definitions[&1]
                    && gap.kind() == ResolutionGapKind::ImplicitConstructor
            })
            .expect("the second ambiguous type owns its implicit-constructor evidence")
            .reason_semantic();
        assert_incomplete_with_reason(
            constructor.binding().completion(),
            implicit_constructor_reason,
        );
        assert_incomplete_with_reason(
            constructor.projected_frontiers()[0].completion(),
            implicit_constructor_reason,
        );
        assert_incomplete_with_reason(constructor.completion(), implicit_constructor_reason);
    }

