    #[test]
    fn hierarchy_publication_generation_hides_partial_state_until_atomic_commit() {
        let shape = HierarchyLookupShape::new(
            SemanticId::for_test(b"atomic-hierarchy-lookup"),
            ResolutionNamespace::Value,
            QualifierCategory::Runtime,
            0,
        );
        let owner = SemanticId::for_test(b"atomic-hierarchy-owner");
        let key = HierarchyNodeKey { shape, owner };
        let cycle = PartialPathId::for_test(b"atomic-hierarchy-cycle");
        let summary = HierarchyStructuralSummary {
            candidate_distance: None,
            candidates: None,
            evidence: HierarchyEvidence::Complete,
            transfer: HierarchyEvidence::Complete,
            retains_global_evidence: false,
        };
        let mut arena = HierarchyOperationArena::default();

        let cancelled_generation = arena.begin_publication();
        arena.stage_summary(cancelled_generation, key, summary.clone());
        arena.stage_closure_owner(cancelled_generation, owner);
        arena.stage_cycle(cancelled_generation, owner, cycle);
        assert!(!arena.contains_summary(key));
        assert!(!arena.closure_contains(owner));
        assert_eq!(arena.cycle(owner), None);

        let retry_generation = arena.begin_publication();
        arena.stage_summary(retry_generation, key, summary);
        arena.stage_closure_owner(retry_generation, owner);
        arena.stage_cycle(retry_generation, owner, cycle);
        arena.commit_publication(retry_generation);
        assert!(arena.contains_summary(key));
        assert!(arena.closure_contains(owner));
        assert_eq!(arena.cycle(owner), Some(cycle));
    }

    #[test]
    fn hierarchy_selection_uses_one_global_minimum_across_all_roots() {
        let fixture = java_fixture();
        let cancellation = CancellationToken::new();
        let mut session = preloaded_session(&fixture.service, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut evaluation =
            FactEvaluation::new(&mut session, &mut hierarchy, fixture.references[&8]);
        let shape = HierarchyLookupShape::new(
            SemanticId::for_test(b"global-minimum-lookup"),
            ResolutionNamespace::Value,
            QualifierCategory::Runtime,
            0,
        );
        let far_root = SemanticId::for_test(b"global-minimum-far-root");
        let near_root = SemanticId::for_test(b"global-minimum-near-root");
        let far_candidate = SemanticId::for_test(b"global-minimum-far-candidate");
        let near_candidate = SemanticId::for_test(b"global-minimum-near-candidate");
        let far_reason = SemanticId::for_test(b"global-minimum-far-reason");
        let near_reason = SemanticId::for_test(b"global-minimum-near-reason");
        {
            let hierarchy = &mut *evaluation.hierarchy;
            let far_atom = hierarchy
                .evidence
                .one(far_reason, incomplete(far_reason), &mut || false)
                .expect("atom construction is uncancelled");
            let near_atom = hierarchy
                .evidence
                .one(near_reason, incomplete(near_reason), &mut || false)
                .expect("atom construction is uncancelled");
            let far_expression = hierarchy.candidates.here(far_candidate);
            let near_expression = hierarchy.candidates.here(near_candidate);
            let far_evidence = hierarchy.evidence.shift(far_atom, 4);
            let near_evidence = hierarchy.evidence.shift(near_atom, 2);
            let generation = hierarchy.begin_publication();
            hierarchy.stage_summary(
                generation,
                HierarchyNodeKey {
                    shape,
                    owner: far_root,
                },
                HierarchyStructuralSummary {
                    candidate_distance: Some(2),
                    candidates: Some(far_expression),
                    evidence: far_evidence,
                    transfer: HierarchyEvidence::Complete,
                    retains_global_evidence: true,
                },
            );
            hierarchy.stage_summary(
                generation,
                HierarchyNodeKey {
                    shape,
                    owner: near_root,
                },
                HierarchyStructuralSummary {
                    candidate_distance: Some(1),
                    candidates: Some(near_expression),
                    evidence: near_evidence,
                    transfer: HierarchyEvidence::Complete,
                    retains_global_evidence: true,
                },
            );
            hierarchy.commit_publication(generation);
        }
        let roots = [
            HierarchyRoot {
                owner: far_root,
                value: ResolutionSlotValue::runtime(ResolutionTypeRef::new(far_root, 0), false),
                route_ordinal: 0,
            },
            HierarchyRoot {
                owner: near_root,
                value: ResolutionSlotValue::runtime(ResolutionTypeRef::new(near_root, 0), false),
                route_ordinal: 1,
            },
        ];
        let selection = match evaluation
            .cached_hierarchy_selection(shape, &roots)
            .expect("cached hierarchy selection is infallible")
            .expect("both root summaries are cached")
        {
            HierarchySelectionState::Pending => panic!("uncancelled selection cannot be pending"),
            HierarchySelectionState::Ready(selection) => selection,
        };
        assert_eq!(selection.owners.len(), 1);
        assert_eq!(selection.owners[0].owner, near_candidate);
        assert_eq!(selection.owners[0].root.owner, near_root);
        assert_eq!(
            evaluation
                .hierarchy
                .evidence
                .flatten(&selection.evidence, u32::MAX, &mut || false)
                .expect("flatten is uncancelled"),
            incomplete(near_reason)
        );
    }

    #[test]
    fn convergent_roots_keep_distinct_origins_but_one_suffix_evidence_atom() {
        let fixture = java_fixture();
        let cancellation = CancellationToken::new();
        let mut session = preloaded_session(&fixture.service, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut evaluation =
            FactEvaluation::new(&mut session, &mut hierarchy, fixture.references[&8]);
        let shape = HierarchyLookupShape::new(
            SemanticId::for_test(b"convergent-root-lookup"),
            ResolutionNamespace::Value,
            QualifierCategory::Runtime,
            0,
        );
        let roots = [
            SemanticId::for_test(b"convergent-root-a"),
            SemanticId::for_test(b"convergent-root-b"),
        ];
        let references = [
            SemanticId::for_test(b"convergent-edge-a"),
            SemanticId::for_test(b"convergent-edge-b"),
        ];
        let shared = SemanticId::for_test(b"convergent-shared-owner");
        let first = ResolutionIncompleteReason::UnsupportedSemantic(SemanticId::for_test(
            b"convergent-suffix-first",
        ));
        let second = ResolutionIncompleteReason::UnsupportedSemantic(SemanticId::for_test(
            b"convergent-suffix-second",
        ));
        let suffix_completion =
            ResolutionCompletion::Incomplete(vec![second, first, second].into_boxed_slice().into());
        {
            let hierarchy = &mut *evaluation.hierarchy;
            let suffix = hierarchy
                .evidence
                .one(
                    SemanticId::for_test(b"convergent-shared-suffix-atom"),
                    suffix_completion.clone(),
                    &mut || false,
                )
                .expect("atom construction is uncancelled");
            let here = hierarchy.candidates.here(shared);
            let generation = hierarchy.begin_publication();
            for ordinal in 0..2 {
                let candidate = hierarchy.candidates.via(references[ordinal], shared, here);
                let evidence = hierarchy.evidence.shift(suffix.clone(), 2);
                hierarchy.stage_summary(
                    generation,
                    HierarchyNodeKey {
                        shape,
                        owner: roots[ordinal],
                    },
                    HierarchyStructuralSummary {
                        candidate_distance: Some(1),
                        candidates: Some(candidate),
                        evidence,
                        transfer: HierarchyEvidence::Complete,
                        retains_global_evidence: true,
                    },
                );
            }
            hierarchy.commit_publication(generation);
        }
        let root_values = [
            HierarchyRoot {
                owner: roots[0],
                value: ResolutionSlotValue::runtime(ResolutionTypeRef::new(roots[0], 0), false),
                route_ordinal: 0,
            },
            HierarchyRoot {
                owner: roots[1],
                value: ResolutionSlotValue::runtime(ResolutionTypeRef::new(roots[1], 0), false),
                route_ordinal: 1,
            },
        ];
        let selection = match evaluation
            .cached_hierarchy_selection(shape, &root_values)
            .expect("cached hierarchy selection is infallible")
            .expect("both root summaries are cached")
        {
            HierarchySelectionState::Pending => panic!("uncancelled selection cannot be pending"),
            HierarchySelectionState::Ready(selection) => selection,
        };
        assert_eq!(selection.owners.len(), 2);
        assert!(selection.owners.iter().all(|owner| owner.owner == shared));
        assert_ne!(selection.owners[0].root, selection.owners[1].root);
        assert_ne!(selection.owners[0].ancestry, selection.owners[1].ancestry);
        assert_eq!(
            evaluation
                .hierarchy
                .evidence
                .flatten(&selection.evidence, u32::MAX, &mut || false)
                .expect("flatten is uncancelled"),
            suffix_completion
        );
    }

    #[test]
    fn reverse_hierarchy_candidate_membership_reuses_a_shared_deep_suffix() {
        let target = SemanticId::for_test(b"reverse-membership-shared-target");
        let depth = 257_usize;
        let root_count = 73_usize;
        let mut candidates = HierarchyCandidateArena::default();
        let mut suffix = candidates.here(target);
        for ordinal in 0..depth {
            suffix = candidates.via(
                SemanticId::for_test(
                    [
                        b"reverse-membership-suffix-reference".as_slice(),
                        &u64::try_from(ordinal)
                            .expect("test depth fits u64")
                            .to_le_bytes(),
                    ]
                    .concat(),
                ),
                SemanticId::for_test(b"reverse-membership-suffix-owner"),
                suffix,
            );
        }
        let mut roots = Vec::with_capacity(root_count);
        for ordinal in 0..root_count {
            roots.push(
                candidates.via(
                    SemanticId::for_test(
                        [
                            b"reverse-membership-root-reference".as_slice(),
                            &u64::try_from(ordinal)
                                .expect("test root ordinal fits u64")
                                .to_le_bytes(),
                        ]
                        .concat(),
                    ),
                    SemanticId::for_test(b"reverse-membership-root-owner"),
                    suffix,
                ),
            );
        }

        let mut visits = 0_usize;
        let mut selected_pairs = 0_usize;
        for expression in roots {
            let (contains, current_visits) = candidates
                .contains_owner(expression, target, &mut || false)
                .expect("uncancelled membership traversal completes");
            assert!(contains);
            selected_pairs += usize::from(contains);
            visits += current_visits;
        }
        assert_eq!(selected_pairs, root_count);
        assert_eq!(visits, depth + 1 + root_count);
        assert_eq!(
            candidates.owner_membership.len(),
            depth + 1 + root_count,
            "every shared candidate-expression node is memoized once for the exact owner"
        );
    }

    #[test]
    fn convergent_qualified_roots_fan_two_origins_from_one_exact_suffix_replay() {
        let source = "public class Fixture { public static class Shared { public int x; } public static class A extends Shared {} public static class B extends Shared {} public static class Use { public int f(A a) { return a.x; } } }";
        let fixture = parsed_java_service_fixture(source, b"convergent-qualified-root-replay");
        let reference = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Reference,
        )[0];
        let target = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let shared = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "Shared",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let root_a = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "A",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let root_b = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "B",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let route_id = *fixture.service.typed.qualified_route_ids_by_reference[&reference]
            .iter()
            .find(|&&route_id| {
                fixture.service.typed.qualified_routes[route_id]
                    .row
                    .namespace()
                    == ResolutionNamespace::Value
            })
            .expect("the field reference has one value route");
        let route = fixture.service.typed.selected_source_route(route_id);
        let lookup = route.row().lookup();
        let qualifier_slot = route.row().qualifier_slot();
        let shared_scope = fixture.service.typed.member_scope_by_definition[&shared];
        let first = ResolutionIncompleteReason::UnsupportedSemantic(SemanticId::for_test(
            b"convergent-qualified-suffix-first",
        ));
        let second = ResolutionIncompleteReason::UnsupportedSemantic(SemanticId::for_test(
            b"convergent-qualified-suffix-second",
        ));
        let suffix_completion =
            ResolutionCompletion::Incomplete(vec![second, first, second].into_boxed_slice().into());
        let observed = ObservedBatchSource::with_forward_branch_completion_at_node(
            &fixture.service.source,
            lookup,
            shared_scope,
            suffix_completion.clone(),
        );
        let cancellation = CancellationToken::new();
        let mut session =
            FactReadSession::from_split_sources(&observed, &fixture.service, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut evaluation = FactEvaluation::new(&mut session, &mut hierarchy, reference);
        let routes = prime_qualified_reference_seed_for_test(
            &mut evaluation,
            reference,
            std::slice::from_ref(&route),
        );
        let previous_states = [(
            qualifier_slot,
            TypedFrontierState::new(
                qualifier_slot,
                [
                    ResolutionSlotValue::runtime(ResolutionTypeRef::new(root_a, 0), false),
                    ResolutionSlotValue::runtime(ResolutionTypeRef::new(root_b, 0), false),
                ],
                ResolutionCompletion::Complete,
            ),
        )]
        .into_iter()
        .collect::<HashMap<_, _>>();

        let answer = evaluation
            .resolve_qualified(reference, &routes, &shared_map(&previous_states), None)
            .expect("qualified hierarchy replay is infallible")
            .expect("the uncancelled qualified hierarchy replay completes");

        assert_eq!(answer.targets(), &[target]);
        assert_eq!(answer.completion(), &suffix_completion);
        assert_eq!(answer.witnesses().len(), 2);
        assert!(
            answer
                .witnesses()
                .iter()
                .all(|witness| witness.completion() == &ResolutionCompletion::Complete),
            "the shared request-branch operand belongs once to the aggregate, not to either origin path"
        );
        let origin_identities = answer
            .witnesses()
            .iter()
            .map(|witness| match witness.steps().first() {
                Some(WitnessStep::Candidate {
                    semantic,
                    outcome: CandidateOutcome::Selected,
                }) => *semantic,
                other => {
                    panic!("qualified origin witness starts with a selected marker: {other:?}")
                }
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(origin_identities.len(), 2);
    }

    #[test]
    fn qualified_hierarchy_retries_when_a_later_round_adds_the_receiver_owner() {
        let source = "public class Fixture { public static class Base { public int x; } public static class Leaf extends Base {} public static class Use { public int f(Leaf v) { return v.x; } } }";
        let fixture = parsed_java_service_fixture(source, b"late-qualified-hierarchy-owner");
        let reference = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Reference,
        )[0];
        let target = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let leaf = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "Leaf",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let route_id = fixture.service.typed.qualified_route_ids_by_reference[&reference][0];
        let route = fixture.service.typed.selected_source_route(route_id);
        let qualifier_slot = route.row().qualifier_slot();
        let observed = ObservedBatchSource::new(&fixture.service.source);
        let cancellation = CancellationToken::new();
        let mut session =
            FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut evaluation = FactEvaluation::new(&mut session, &mut hierarchy, reference);
        let routes = prime_qualified_reference_seed_for_test(
            &mut evaluation,
            reference,
            std::slice::from_ref(&route),
        );
        assert_eq!(
            observed.reference_seed_batch_queries.borrow().as_slice(),
            &[vec![reference]],
            "the manual replay establishes its exact production plural-seed precondition once"
        );
        let early_states = [(
            qualifier_slot,
            TypedFrontierState::new(
                qualifier_slot,
                Vec::<ResolutionSlotValue>::new(),
                ResolutionCompletion::Complete,
            ),
        )]
        .into_iter()
        .collect::<HashMap<_, _>>();
        let early = evaluation
            .resolve_qualified(reference, &routes, &shared_map(&early_states), None)
            .expect("early qualified round is infallible")
            .expect("early qualified round completes without a receiver owner");
        assert!(early.targets().is_empty());
        assert!(evaluation.hierarchy.edge_nodes.is_empty());

        // The later round supplies only the receiver. Route-free supertype
        // targets come from the immutable plural lexical answer, never from a
        // transient TargetTypeIdentity frontier in `previous_states`.
        let later_states = [(
            qualifier_slot,
            TypedFrontierState::new(
                qualifier_slot,
                [ResolutionSlotValue::runtime(
                    ResolutionTypeRef::new(leaf, 0),
                    false,
                )],
                ResolutionCompletion::Complete,
            ),
        )]
        .into_iter()
        .collect::<HashMap<_, _>>();
        let later = evaluation
            .resolve_qualified(reference, &routes, &shared_map(&later_states), None)
            .expect("later qualified round is infallible")
            .expect("later qualified round completes after its receiver appears");
        assert_eq!(later.targets(), &[target]);
        assert_eq!(later.completion(), &ResolutionCompletion::Complete);
        let hierarchy = &*evaluation.hierarchy;
        assert!(!hierarchy.reference_answers.is_empty());
        assert!(
            hierarchy
                .edge_nodes
                .values()
                .flat_map(|node| node.edges.iter())
                .any(|edge| !edge.targets.is_empty())
        );
    }

    #[test]
    fn type_or_value_shared_qualifier_completion_is_owned_once_and_reaches_witnesses() {
        let source = "public class Fixture { public static class A { public static class x {} public static int x; } public static class Use { public Object y = A.x; } }";
        let fixture = parsed_java_service_fixture(source, b"shared-qualifier-exact-box");
        let reference = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Reference,
        )[0];
        let route_ids = &fixture.service.typed.qualified_route_ids_by_reference[&reference];
        assert_eq!(route_ids.len(), 2);
        let qualifier_slots = route_ids
            .iter()
            .map(|&route_id| {
                fixture.service.typed.qualified_routes[route_id]
                    .row
                    .qualifier_slot()
            })
            .collect::<BTreeSet<_>>();
        assert_eq!(qualifier_slots.len(), 1);
        let qualifier_slot = *qualifier_slots
            .first()
            .expect("the two routes share one qualifier slot");
        let first = ResolutionIncompleteReason::UnsupportedSemantic(SemanticId::for_test(
            b"shared-qualifier-first",
        ));
        let second = ResolutionIncompleteReason::UnsupportedSemantic(SemanticId::for_test(
            b"shared-qualifier-second",
        ));
        let qualifier_completion =
            ResolutionCompletion::Incomplete(vec![second, first, second].into_boxed_slice().into());
        let stable_states = stable_typed_states_for_reference(&fixture, reference);
        let qualifier_values = stable_states
            .get(&qualifier_slot)
            .expect("the actual fixed point publishes the shared qualifier")
            .possible_values()
            .to_vec();
        assert!(
            !qualifier_values.is_empty(),
            "the shared qualifier law has a concrete type-object receiver"
        );
        let previous_states = [(
            qualifier_slot,
            TypedFrontierState::new(
                qualifier_slot,
                qualifier_values,
                qualifier_completion.clone(),
            ),
        )]
        .into_iter()
        .collect::<HashMap<_, _>>();
        let routes = route_ids
            .iter()
            .map(|&route_id| fixture.service.typed.selected_source_route(route_id))
            .collect::<Vec<_>>();
        assert_eq!(routes.len(), 2);
        let cancellation = CancellationToken::new();
        let mut session = preloaded_session(&fixture.service, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut evaluation = FactEvaluation::new(&mut session, &mut hierarchy, reference);
        let routes = prime_qualified_reference_seed_for_test(&mut evaluation, reference, &routes);
        let answer = evaluation
            .resolve_qualified(reference, &routes, &shared_map(&previous_states), None)
            .expect("shared-qualifier hierarchy resolution is infallible")
            .expect("shared-qualifier hierarchy resolution is uncancelled");
        assert_eq!(answer.completion(), &qualifier_completion);
        assert_eq!(answer.witnesses().len(), 1);
        assert!(
            answer
                .witnesses()
                .iter()
                .all(|witness| witness.completion() == &qualifier_completion)
        );
    }

    #[test]
    fn mixed_hierarchy_and_nonhierarchy_origins_transfer_qualifiers_independently() {
        let source = "public class Fixture { public static class Base { public int x; } public static class Leaf extends Base {} public static class Use { public int f(Leaf v) { return v.x; } } }";
        let fixture = parsed_java_service_fixture(source, b"mixed-hierarchy-origin-transfer");
        let reference = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Reference,
        )[0];
        let target = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let base = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "Base",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let leaf = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "Leaf",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let route_id = *fixture.service.typed.qualified_route_ids_by_reference[&reference]
            .iter()
            .find(|&&route_id| {
                fixture.service.typed.qualified_routes[route_id]
                    .row
                    .namespace()
                    == ResolutionNamespace::Value
            })
            .expect("the field reference has one value route");
        let hierarchy_route = fixture.service.typed.selected_source_route(route_id);
        let hierarchy_slot = hierarchy_route.row().qualifier_slot();
        let nonhierarchy_slot = SemanticId::for_test(b"mixed-nonhierarchy-qualifier-slot");
        let leaf_hierarchy_gaps = fixture
            .typed
            .property_gaps()
            .iter()
            .filter(|gap| {
                gap.definition() == leaf
                    && gap.kind() == ResolutionGapKind::UnsupportedHierarchyTraversal
            })
            .collect::<Vec<_>>();
        assert_eq!(leaf_hierarchy_gaps.len(), 1);
        let nonhierarchy_reason = leaf_hierarchy_gaps[0].reason_semantic();
        assert_eq!(
            fixture.service.typed.gap_reason_provenance_by_reason[&nonhierarchy_reason].origin(),
            LoweringGapOrigin::Extracted(ResolutionGapKind::UnsupportedHierarchyTraversal),
            "the shared test reason has real structural hierarchy-transfer authority"
        );
        let base_row = hierarchy_route.row();
        let nonhierarchy_route = SourceSelectedQualifiedRoute::new(
            hierarchy_route.fragment(),
            hierarchy_route.reference_node(),
            LoweredQualifiedSeededRoute::new(
                base_row.reference(),
                nonhierarchy_slot,
                base_row.lookup(),
                base_row.namespace(),
                base_row
                    .precedence_ordinal()
                    .checked_add(1)
                    .expect("the synthetic route ordinal fits u32"),
                base_row.projection_output_slot(),
                base_row.projection_kind(),
                SemanticId::for_test(b"mixed-nonhierarchy-coarse-gap"),
            ),
        );
        let qualifier_completion = incomplete(nonhierarchy_reason);
        {
            let hierarchy_only_states = [(
                hierarchy_slot,
                TypedFrontierState::new(
                    hierarchy_slot,
                    [ResolutionSlotValue::runtime(
                        ResolutionTypeRef::new(leaf, 0),
                        false,
                    )],
                    qualifier_completion.clone(),
                ),
            )]
            .into_iter()
            .collect::<HashMap<_, _>>();
            let observed = ObservedBatchSource::new(&fixture.service.source);
            let cancellation = CancellationToken::new();
            let mut session =
                FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
            let mut hierarchy = HierarchyOperationArena::default();
            let mut evaluation = FactEvaluation::new(&mut session, &mut hierarchy, reference);
            let routes = prime_qualified_reference_seed_for_test(
                &mut evaluation,
                reference,
                &[hierarchy_route],
            );
            assert_eq!(
                observed.reference_seed_batch_queries.borrow().as_slice(),
                &[vec![reference]],
                "the hierarchy-only replay establishes one exact plural seed"
            );
            let hierarchy_only = evaluation
                .resolve_qualified(
                    reference,
                    &routes,
                    &shared_map(&hierarchy_only_states),
                    None,
                )
                .expect("hierarchy-only qualified replay is infallible")
                .expect("hierarchy-only qualified replay completes");
            assert_eq!(hierarchy_only.targets(), &[target]);
            assert!(!hierarchy_only.completion().contains_reason(
                ResolutionIncompleteReason::UnsupportedSemantic(nonhierarchy_reason),
            ));
            assert!(!hierarchy_only.witnesses().is_empty());
            assert!(hierarchy_only.witnesses().iter().all(|witness| {
                !witness.completion().contains_reason(
                    ResolutionIncompleteReason::UnsupportedSemantic(nonhierarchy_reason),
                )
            }));
        }
        let previous_states = [
            (
                hierarchy_slot,
                TypedFrontierState::new(
                    hierarchy_slot,
                    [ResolutionSlotValue::runtime(
                        ResolutionTypeRef::new(leaf, 0),
                        false,
                    )],
                    qualifier_completion.clone(),
                ),
            ),
            (
                nonhierarchy_slot,
                TypedFrontierState::new(
                    nonhierarchy_slot,
                    [ResolutionSlotValue::runtime(
                        ResolutionTypeRef::new(base, 1),
                        false,
                    )],
                    qualifier_completion.clone(),
                ),
            ),
        ]
        .into_iter()
        .collect::<HashMap<_, _>>();
        let observed = ObservedBatchSource::new(&fixture.service.source);
        let cancellation = CancellationToken::new();
        let mut session =
            FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut evaluation = FactEvaluation::new(&mut session, &mut hierarchy, reference);
        let routes = prime_qualified_reference_seed_for_test(
            &mut evaluation,
            reference,
            &[hierarchy_route, nonhierarchy_route],
        );
        assert_eq!(
            observed.reference_seed_batch_queries.borrow().as_slice(),
            &[vec![reference]],
            "both same-reference origins share one exact plural seed outcome"
        );
        let answer = evaluation
            .resolve_qualified(reference, &routes, &shared_map(&previous_states), None)
            .expect("mixed qualified replay is infallible")
            .expect("mixed qualified replay completes");

        assert_eq!(answer.targets(), &[target]);
        assert!(answer.completion().contains_reason(
            ResolutionIncompleteReason::UnsupportedSemantic(nonhierarchy_reason),
        ));
        assert_eq!(
            match answer.completion() {
                ResolutionCompletion::Complete => 0,
                ResolutionCompletion::Incomplete(reasons) => reasons
                    .iter()
                    .filter(|&&reason| {
                        reason
                            == ResolutionIncompleteReason::UnsupportedSemantic(nonhierarchy_reason)
                    })
                    .count(),
            },
            1,
            "the mixed aggregate retains exactly the nonhierarchy-owned occurrence"
        );
        assert!(answer.witnesses().len() >= 2);
        let hierarchy_reason_owners = answer
            .witnesses()
            .iter()
            .filter(|witness| {
                witness.completion().contains_reason(
                    ResolutionIncompleteReason::UnsupportedSemantic(nonhierarchy_reason),
                )
            })
            .count();
        assert_eq!(hierarchy_reason_owners, 1);
        assert!(answer.witnesses().iter().any(|witness| {
            !witness
                .completion()
                .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(
                    nonhierarchy_reason,
                ))
        }));
    }

