    #[test]
    fn generated_changed_integer_arguments_reach_applicability_as_complete_runtime_ints() {
        let source = "class A { int changed(int value) { return value; } int use() { changed(0); changed(1); changed(2); changed(3); return changed(4); } }";
        let fixture = parsed_java_service_fixture(source, b"java-changed-integer-applicability");
        let declaration = java_callable_definition_at(
            &fixture,
            source.find("changed(int").expect("changed declaration"),
        );
        let literal_facts = fixture
            .facts
            .intrinsic_type_seeds
            .iter()
            .filter(|seed| {
                let slot = fixture.facts.type_slots[seed.output.get() as usize];
                fixture.facts.sites[slot.site.get() as usize].kind == ResolutionSiteKind::Literal
            })
            .collect::<Vec<_>>();
        assert_eq!(literal_facts.len(), 5);
        assert!(literal_facts.iter().all(|seed| {
            seed.kind == IntrinsicTypeKind::Primitive
                && fixture.facts.names[seed.name.get() as usize].spelling == "int"
        }));
        let runtime_literal_values = fixture
            .typed
            .intrinsic_seeds()
            .iter()
            .filter(|seed| seed.kind() == IntrinsicTypeKind::Primitive)
            .filter_map(|seed| match seed.frontier().possible_values() {
                [value @ ResolutionSlotValue::Runtime { .. }]
                    if seed.frontier().completion() == &ResolutionCompletion::Complete =>
                {
                    Some(*value)
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(runtime_literal_values.len(), 5);
        assert!(
            runtime_literal_values
                .windows(2)
                .all(|pair| pair[0] == pair[1]),
            "all five generated integer literals must carry the same runtime int identity"
        );
        let runtime_int = runtime_literal_values[0];

        for literal in 0..=4 {
            let call = format!("changed({literal})");
            let position = source.find(&call).expect("changed call");
            let site = positioned_site_at(
                &fixture.facts,
                position,
                ResolutionIdentifierRole::Reference,
                ResolutionNamespace::Callable,
            );
            let reference =
                lowered_semantic_at(&fixture.lexical, site, LoweredSemanticRole::Reference);
            let obligation = fixture
                .typed
                .call_obligations()
                .iter()
                .find(|obligation| obligation.callee_reference() == reference)
                .expect("changed call applicability obligation");
            assert_eq!(obligation.argument_slots().len(), 1);
            let states = stable_typed_states_for_reference(&fixture, reference);
            let argument = states
                .get(&obligation.argument_slots()[0])
                .expect("changed call argument frontier");
            assert_eq!(argument.possible_values(), &[runtime_int]);
            assert_eq!(argument.completion(), &ResolutionCompletion::Complete);

            let answer = fixture
                .service
                .resolve_reference(reference, &CancellationToken::new())
                .expect("preload reads are infallible");
            assert_eq!(answer.binding().targets(), &[declaration]);
            assert!(!answer.completion().contains_reason(
                ResolutionIncompleteReason::UnsupportedSemantic(obligation.applicability_reason(),)
            ));
        }
    }

    #[test]
    fn experimental_fact_dependencies_suspend_without_replaying_reference_setup() {
        let fixture = java_fixture();
        let reference = fixture.references[&8];
        assert!(
            !fixture
                .service
                .typed
                .qualified_route_ids_by_reference
                .contains_key(&reference)
        );
        let cancellation = CancellationToken::new();
        let mut eager_session = preloaded_session(&fixture.service, &cancellation);
        let mut eager_hierarchy = HierarchyOperationArena::default();
        let mut eager_artifacts = ForwardCandidateArtifactCache::default();
        let mut eager = FactEvaluation::new_with_forward_artifacts(
            &mut eager_session,
            &mut eager_hierarchy,
            &mut eager_artifacts,
            reference,
        );
        let expected = eager.run().unwrap();
        let expected_work = eager.work;
        let mut observed = ObservedBatchSource::new(&fixture.service.source);
        // The oracle below is the eager evaluator's work counter, and the
        // eager evaluator never fills the operation's demanded-reference memo:
        // it does not run the frames that write it. A source that names no
        // selection memoizes nothing, which is what keeps the two counters
        // comparable. What this test pins is that a suspended task resumes
        // without replaying its reference setup, not what the memo costs.
        observed.selection_authority = None;
        let mut session =
            FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut artifacts = ForwardCandidateArtifactCache::default();
        let initial =
            FactEvaluation::new(&mut session, &mut hierarchy, reference).into_checkpoint_state();
        let mut task = DemandFactEvaluationTask::new(initial);
        let mut suspended = false;
        for _ in 0..64 {
            match task
                .poll_with_readiness(&mut session, &mut hierarchy, &mut artifacts, &mut |_| {
                    Ok(DemandForwardReadiness::AwaitingDependencies)
                })
                .unwrap()
            {
                DemandFactEvaluationPoll::Continue => {}
                DemandFactEvaluationPoll::AwaitingDependencies => {
                    suspended = true;
                    break;
                }
                _ => panic!("ordinary lexical root must reach candidate readiness"),
            }
        }
        assert!(suspended);
        let work = task.evaluation.as_ref().unwrap().work;
        let seed_reads = observed.reference_seed_lookups.get();
        let match_reads = observed.forward_match_calls.get();
        let typed_rows = (
            session.cache.call_rows.rows.len(),
            session.cache.route_rows.rows.len(),
        );
        let cursor = task.references.as_ref().unwrap().cursor;
        let pending = task
            .references
            .as_ref()
            .unwrap()
            .active
            .as_ref()
            .unwrap()
            .pending_requests()
            .iter()
            .map(|request| request.endpoint().clone())
            .collect::<Vec<_>>();
        assert!(!pending.is_empty());
        assert!(
            !task
                .evaluation
                .as_ref()
                .unwrap()
                .lexical_answers
                .contains_key(&reference)
        );
        for _ in 0..4 {
            assert!(matches!(
                task.poll_with_readiness(
                    &mut session,
                    &mut hierarchy,
                    &mut artifacts,
                    &mut |requests| {
                        assert_eq!(
                            requests
                                .iter()
                                .map(|request| request.endpoint().clone())
                                .collect::<Vec<_>>(),
                            pending
                        );
                        Ok(DemandForwardReadiness::AwaitingDependencies)
                    }
                )
                .unwrap(),
                DemandFactEvaluationPoll::AwaitingDependencies
            ));
            assert_eq!(task.evaluation.as_ref().unwrap().work, work);
            assert_eq!(observed.reference_seed_lookups.get(), seed_reads);
            assert_eq!(observed.forward_match_calls.get(), match_reads);
            assert_eq!(
                (
                    session.cache.call_rows.rows.len(),
                    session.cache.route_rows.rows.len()
                ),
                typed_rows
            );
            assert_eq!(task.references.as_ref().unwrap().cursor, cursor);
        }
        for _ in 0..512 {
            match task
                .poll_with_readiness(&mut session, &mut hierarchy, &mut artifacts, &mut |_| {
                    Ok(DemandForwardReadiness::Ready)
                })
                .unwrap()
            {
                DemandFactEvaluationPoll::Continue => {}
                DemandFactEvaluationPoll::Ready(actual) => {
                    assert_eq!(*actual, expected);
                    assert_eq!(task.evaluation.as_ref().unwrap().work, expected_work);
                    return;
                }
                _ => panic!("closed ordinary fixture must not suspend or fall back"),
            }
        }
        panic!("resumed ordinary root did not terminate");
    }

    #[test]
    fn experimental_fact_dependencies_cancel_pending_batch_without_negative_publication() {
        let fixture = java_fixture();
        let reference = fixture.references[&8];
        let gap = SemanticId::for_test(b"pending-lexical-seed-evidence");
        let mut observed = ObservedBatchSource::new(&fixture.service.source);
        observed.reference_seed_completion = Some((reference, incomplete(gap)));
        let cancellation = CancellationToken::new();
        let mut session =
            FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut artifacts = ForwardCandidateArtifactCache::default();
        let initial =
            FactEvaluation::new(&mut session, &mut hierarchy, reference).into_checkpoint_state();
        let mut task = DemandFactEvaluationTask::new(initial);
        let mut waiting = false;
        for _ in 0..64 {
            match task
                .poll_with_readiness(&mut session, &mut hierarchy, &mut artifacts, &mut |_| {
                    Ok(DemandForwardReadiness::AwaitingDependencies)
                })
                .unwrap()
            {
                DemandFactEvaluationPoll::Continue => {}
                DemandFactEvaluationPoll::AwaitingDependencies => {
                    waiting = true;
                    break;
                }
                _ => panic!("seed evidence must reach the pending lexical boundary"),
            }
        }
        assert!(waiting);
        assert!(!task.pending_requests().is_empty());
        assert!(
            !task
                .evaluation
                .as_ref()
                .unwrap()
                .lexical_answers
                .contains_key(&reference)
        );
        cancellation.cancel();
        let DemandFactEvaluationPoll::Ready(answer) = task
            .poll_with_readiness(&mut session, &mut hierarchy, &mut artifacts, &mut |_| {
                panic!("cancelled batch cannot ask for dependency readiness")
            })
            .unwrap()
        else {
            panic!("pending cancellation must produce an evidence-bearing terminal")
        };
        assert!(answer.binding().targets().is_empty());
        assert!(
            answer
                .completion()
                .contains_reason(ResolutionIncompleteReason::Cancelled)
        );
        assert!(
            answer
                .completion()
                .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(gap))
        );
        assert!(
            !task
                .evaluation
                .as_ref()
                .unwrap()
                .lexical_answers
                .contains_key(&reference)
        );
    }

    #[test]
    fn experimental_fact_task_budget_cancellation_drains_retained_batch_evidence() {
        for read_page in [false, true] {
            let fixture = java_fixture();
            let reference = fixture.references[&8];
            let seed_gap = SemanticId::for_test(b"scheduler-cancel-seed-evidence");
            let page_gap = SemanticId::for_test(b"scheduler-cancel-page-evidence");
            let mut observed = ObservedBatchSource::new(&fixture.service.source);
            observed.reference_seed_completion = Some((reference, incomplete(seed_gap)));
            observed.forward_match_completion = Some(incomplete(page_gap));
            let cancellation = CancellationToken::new();
            let budget = ResolutionSession::bounded(
                ReceiverAnalysisBudget {
                    max_scope_nodes: usize::MAX,
                    max_summary_expansions: 128,
                    ..ReceiverAnalysisBudget::default()
                },
                Some(&cancellation),
            );
            // Deliberately retain the caller token: scheduler budget exhaustion
            // must not require cancelling it to drain an already suspended task.
            let mut session = FactReadSession::from_split_sources_bounded(
                &observed,
                &fixture.service,
                &[],
                &cancellation,
                &budget,
            );
            let mut hierarchy = HierarchyOperationArena::default();
            let mut artifacts = ForwardCandidateArtifactCache::default();
            let initial = FactEvaluation::new(&mut session, &mut hierarchy, reference)
                .into_checkpoint_state();
            let mut task = DemandFactEvaluationTask::new(initial);
            let mut reached_boundary = false;
            for _ in 0..128 {
                let outcome = task
                    .poll_with_readiness(&mut session, &mut hierarchy, &mut artifacts, &mut |_| {
                        Ok(if read_page {
                            DemandForwardReadiness::Ready
                        } else {
                            DemandForwardReadiness::AwaitingDependencies
                        })
                    })
                    .unwrap();
                match outcome {
                    DemandFactEvaluationPoll::AwaitingDependencies => {
                        reached_boundary = true;
                        break;
                    }
                    DemandFactEvaluationPoll::Continue => {
                        if read_page && observed.forward_match_calls.get() > 0 {
                            reached_boundary = true;
                            break;
                        }
                    }
                    _ => panic!("ordinary reference must reach its lexical page boundary"),
                }
            }
            assert!(reached_boundary);
            assert!(task.references.as_ref().unwrap().active.is_some());
            assert!(task.evaluation.as_ref().unwrap().lexical_answers.is_empty());
            let source_reads = || {
                (
                    observed.reference_seed_lookups.get(),
                    observed.forward_match_calls.get(),
                    observed.endpoint_classification_calls.get(),
                    observed.path_hydration_calls.get(),
                )
            };
            let reads_before_cancel = source_reads();
            while budget.summary_step() {}
            let work = budget.finish(()).work();
            assert!(matches!(
                budget.finish(()),
                BoundedResolution::Exceeded { .. }
            ));
            assert!(!cancellation.is_cancelled());
            let answer = task.cancel(&mut session, &mut hierarchy);
            assert!(!cancellation.is_cancelled());
            assert_eq!(source_reads(), reads_before_cancel);
            assert_eq!(budget.finish(()).work(), work);
            assert!(answer.binding().targets().is_empty());
            assert!(answer.binding().witnesses().is_empty());
            assert!(answer.projected_frontiers().is_empty());
            for completion in [answer.binding().completion(), answer.completion()] {
                assert!(completion.contains_reason(ResolutionIncompleteReason::Cancelled));
                assert!(
                    completion
                        .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(seed_gap))
                );
                assert_eq!(
                    completion
                        .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(page_gap)),
                    read_page
                );
            }
            assert_eq!(task.phase, DemandFactEvaluationPhase::Terminal);
            assert!(task.pending_requests().is_empty());
            assert!(task.references.is_none());
            assert!(task.answers.is_empty());
            assert!(task.states.is_empty());
            assert!(task.evaluation.as_ref().unwrap().lexical_answers.is_empty());
            assert!(
                task.evaluation
                    .as_ref()
                    .unwrap()
                    .binding_metrics
                    .worklist_rounds()
                    > 0
            );
        }
    }

    #[test]
    fn experimental_call_frames_preserve_full_refinement_and_late_demands() {
        for (source, call, namespace, late_parameter) in [
            (
                "class C { static void f() {} static void caller() { f(); } }",
                "f();",
                ResolutionNamespace::Callable,
                false,
            ),
            (
                "class A { public void f(int x) {} void g(A a) { a.f(1); } }",
                "f(1)",
                ResolutionNamespace::Callable,
                true,
            ),
            (
                "class A { public static void f(boolean x) {} private static void f() {} public static void g() { A.f(true); } }",
                "f(true)",
                ResolutionNamespace::Callable,
                true,
            ),
            (
                "public class Generated { public static class BaseWorker {} public static class Module extends BaseWorker {} public static Module make() { return new Module(); } }",
                "Module();",
                ResolutionNamespace::Constructor,
                false,
            ),
            (
                "class A { void f(boolean x) {} void g(int x) { f(x); } }",
                "f(x)",
                ResolutionNamespace::Callable,
                true,
            ),
        ] {
            let fixture = parsed_java_service_fixture(source, b"experimental-full-call-refinement");
            let site = positioned_site_at(
                &fixture.facts,
                source.rfind(call).unwrap(),
                ResolutionIdentifierRole::Reference,
                namespace,
            );
            let reference =
                lowered_semantic_at(&fixture.lexical, site, LoweredSemanticRole::Reference);
            if namespace == ResolutionNamespace::Constructor {
                let obligation = fixture
                    .typed
                    .call_obligations()
                    .iter()
                    .find(|call| call.callee_reference() == reference)
                    .unwrap();
                assert!(
                    obligation
                        .eligible_rules()
                        .contains(&ResolutionEngineRuleKind::DefaultConstruction)
                );
                let expected = fixture
                    .service
                    .resolve_reference(reference, &CancellationToken::new())
                    .unwrap();
                assert!(
                    expected.binding().targets().is_empty(),
                    "default construction is targetless"
                );
                assert!(
                    expected.completion().contains_reason(
                        ResolutionIncompleteReason::UnsupportedSemantic(
                            obligation.applicability_reason()
                        )
                    ),
                    "the whole parsed fixture retains its conservative applicability frontier; the closed-state superclass proof is checked separately"
                );
            }
            let late = assert_experimental_call_matches_eager(&fixture.service, reference);
            if late_parameter {
                assert!(
                    late,
                    "call parameter demands must be discovered after lexical answers: {source}"
                );
            }
        }
        let fixture = java_fixture();
        for reference in [
            fixture.references[&11],
            fixture.references[&12],
            fixture.references[&18],
        ] {
            assert_experimental_call_matches_eager(&fixture.service, reference);
        }
    }

    #[test]
    fn experimental_call_cancellation_retains_unconsumed_obligation_completion() {
        let source = "class C { static void f() {} static void caller() { f(); } }";
        let mut fixture = parsed_java_service_fixture(source, b"experimental-pending-call-ledger");
        let site = positioned_site_at(
            &fixture.facts,
            source.rfind("f();").unwrap(),
            ResolutionIdentifierRole::Reference,
            ResolutionNamespace::Callable,
        );
        let reference = lowered_semantic_at(&fixture.lexical, site, LoweredSemanticRole::Reference);
        let pending_reason = SemanticId::for_test(b"pending-call-row-only-completion");
        let original = &fixture.service.typed.call_obligation_by_reference[&reference];
        let changed = LoweredCallApplicabilityObligation::new(
            original.call(),
            original.callee_reference(),
            original.receiver_slot(),
            original.result_slot(),
            original.argument_slots().to_vec(),
            original.eligible_rules().to_vec(),
            original.explicit_type_argument_count(),
            original.applicability_reason(),
            original.completion().combine(&incomplete(pending_reason)),
        );
        fixture
            .service
            .typed
            .call_obligation_by_reference
            .insert(reference, changed);
        let cancellation = CancellationToken::new();
        let observed = ObservedBatchSource::new(&fixture.service.source);
        let mut session =
            FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut artifacts = ForwardCandidateArtifactCache::default();
        let initial =
            FactEvaluation::new(&mut session, &mut hierarchy, reference).into_checkpoint_state();
        let mut task = DemandFactEvaluationTask::new(initial);
        let mut suspended = false;
        for _ in 0..128 {
            match task
                .poll_with_readiness(&mut session, &mut hierarchy, &mut artifacts, &mut |_| {
                    Ok(DemandForwardReadiness::AwaitingDependencies)
                })
                .unwrap()
            {
                DemandFactEvaluationPoll::Continue => {}
                DemandFactEvaluationPoll::AwaitingDependencies => {
                    suspended = true;
                    break;
                }
                _ => panic!("call must suspend before applicability consumes its obligation"),
            }
        }
        assert!(suspended);
        assert!(
            task.references
                .as_ref()
                .unwrap()
                .calls
                .contains_key(&reference)
        );
        assert_eq!(observed.forward_match_calls.get(), 0);
        let seed_reads =
            observed.reference_seed_lookups.get() + observed.reference_seed_batch_lookups.get();
        let answer = task.cancel(&mut session, &mut hierarchy);
        assert!(!cancellation.is_cancelled());
        assert_eq!(observed.forward_match_calls.get(), 0);
        assert_eq!(observed.path_hydration_calls.get(), 0);
        assert_eq!(
            observed.reference_seed_lookups.get() + observed.reference_seed_batch_lookups.get(),
            seed_reads
        );
        for completion in [answer.completion(), answer.binding().completion()] {
            assert!(completion.contains_reason(ResolutionIncompleteReason::Cancelled));
            assert!(
                completion.contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(
                    pending_reason
                ))
            );
        }
    }

    fn assert_experimental_call_matches_eager(
        service: &PreloadedFactResolutionService,
        reference: SemanticId,
    ) -> bool {
        let cancellation = CancellationToken::new();
        let expected = service.resolve_reference(reference, &cancellation).unwrap();
        let observed = ObservedBatchSource::new(&service.source);
        let mut session = FactReadSession::for_preloaded_service(service, &observed, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut artifacts = ForwardCandidateArtifactCache::default();
        let initial =
            FactEvaluation::new(&mut session, &mut hierarchy, reference).into_checkpoint_state();
        let mut task = DemandFactEvaluationTask::new(initial);
        let mut release_next = false;
        let mut late_demands = false;
        let mut saw_calls = false;
        let mut suspensions = 0;
        for _ in 0..4096 {
            let finishing = task
                .references
                .as_ref()
                .is_some_and(|frame| frame.cursor == frame.references.len());
            saw_calls |= task
                .references
                .as_ref()
                .is_some_and(|frame| !frame.calls.is_empty());
            let prior_demands = (
                task.evaluation.as_ref().unwrap().demanded_references.len(),
                task.evaluation.as_ref().unwrap().demanded_slots.len(),
            );
            let candidate_reads = observed.forward_match_calls.get();
            let release = std::mem::take(&mut release_next);
            let mut admitted = false;
            let outcome = task
                .poll_with_readiness(&mut session, &mut hierarchy, &mut artifacts, &mut |_| {
                    admitted |= release;
                    Ok(if release {
                        DemandForwardReadiness::Ready
                    } else {
                        DemandForwardReadiness::AwaitingDependencies
                    })
                })
                .unwrap();
            if observed.forward_match_calls.get() != candidate_reads {
                assert!(
                    admitted,
                    "every candidate read must cross the frame's readiness gate"
                );
            }
            if finishing {
                assert_eq!(
                    observed.forward_match_calls.get(),
                    candidate_reads,
                    "post-reference applicability must not run an unframed lexical query"
                );
                let demands = (
                    task.evaluation.as_ref().unwrap().demanded_references.len(),
                    task.evaluation.as_ref().unwrap().demanded_slots.len(),
                );
                late_demands |= demands != prior_demands;
            }
            match outcome {
                DemandFactEvaluationPoll::Continue => {}
                DemandFactEvaluationPoll::AwaitingHierarchyReferences(references) => {
                    panic!(
                        "fixture unexpectedly requires qualified supertype tasks: {references:?}"
                    )
                }
                DemandFactEvaluationPoll::AwaitingDemandedReference(reference) => {
                    unreachable!("a granted claim never suspends a reference: {reference:?}")
                }
                DemandFactEvaluationPoll::AwaitingDependencies => {
                    suspensions += 1;
                    let work = task.evaluation.as_ref().unwrap().work;
                    let reads = || {
                        (
                            observed.reference_seed_batch_lookups.get(),
                            observed.forward_match_calls.get(),
                            observed.path_hydration_calls.get(),
                        )
                    };
                    let before = reads();
                    let endpoints = task
                        .pending_requests()
                        .iter()
                        .map(|request| request.endpoint().clone())
                        .collect::<Vec<_>>();
                    assert!(!endpoints.is_empty());
                    for _ in 0..2 {
                        assert!(matches!(
                            task.poll_with_readiness(
                                &mut session,
                                &mut hierarchy,
                                &mut artifacts,
                                &mut |_| Ok(DemandForwardReadiness::AwaitingDependencies)
                            )
                            .unwrap(),
                            DemandFactEvaluationPoll::AwaitingDependencies
                        ));
                        assert_eq!(task.evaluation.as_ref().unwrap().work, work);
                        assert_eq!(reads(), before);
                        assert_eq!(
                            task.pending_requests()
                                .iter()
                                .map(|request| request.endpoint().clone())
                                .collect::<Vec<_>>(),
                            endpoints
                        );
                    }
                    release_next = true;
                }
                DemandFactEvaluationPoll::Ready(actual) => {
                    assert!(saw_calls && suspensions > 0);
                    assert_eq!(*actual, expected);
                    return late_demands;
                }
            }
        }
        panic!("framed call did not terminate");
    }

    #[test]
    fn experimental_qualified_frames_suspend_direct_and_suffix_without_replaying_work() {
        let fixture = java_fixture();
        // TypeOrValue lowers to Value before Type. The direct Field match for
        // a.f uses hierarchy-local lookup before the seeded lexical suffix;
        // the source namespace does not make this a nonhierarchy fixture.
        let reference = fixture.references[&9];
        let cancellation = CancellationToken::new();
        let expected = fixture
            .service
            .resolve_reference(reference, &cancellation)
            .unwrap();
        assert!(!expected.binding().targets().is_empty());
        let observed = ObservedBatchSource::new(&fixture.service.source);
        let mut session =
            FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut artifacts = ForwardCandidateArtifactCache::default();
        let initial =
            FactEvaluation::new(&mut session, &mut hierarchy, reference).into_checkpoint_state();
        let mut task = DemandFactEvaluationTask::new(initial);
        let mut suspended_direct = false;
        let mut suspended_hierarchy = false;
        let mut suspended_suffix = false;
        for _ in 0..1024 {
            let qualified = task
                .references
                .as_ref()
                .and_then(|frame| frame.qualified.as_ref());
            let suffix = qualified.is_some_and(|frame| frame.replay.is_some());
            let hierarchy_local = qualified.is_some_and(|frame| frame.hierarchy_group.is_some());
            let suspend = qualified.is_some()
                && if suffix {
                    !suspended_suffix
                } else if hierarchy_local {
                    !suspended_hierarchy
                } else {
                    !suspended_direct
                };
            let result = task
                .poll_with_readiness(&mut session, &mut hierarchy, &mut artifacts, &mut |_| {
                    Ok(if suspend {
                        DemandForwardReadiness::AwaitingDependencies
                    } else {
                        DemandForwardReadiness::Ready
                    })
                })
                .unwrap();
            match result {
                DemandFactEvaluationPoll::Continue => {}
                DemandFactEvaluationPoll::AwaitingHierarchyReferences(references) => {
                    panic!(
                        "fixture unexpectedly requires qualified supertype tasks: {references:?}"
                    )
                }
                DemandFactEvaluationPoll::AwaitingDemandedReference(reference) => {
                    unreachable!("a granted claim never suspends a reference: {reference:?}")
                }
                DemandFactEvaluationPoll::AwaitingDependencies => {
                    assert!(suspend);
                    let work = task.evaluation.as_ref().unwrap().work;
                    let source_reads = || {
                        (
                            observed.reference_seed_batch_lookups.get(),
                            observed.forward_match_calls.get(),
                            observed.path_hydration_calls.get(),
                        )
                    };
                    let reads = source_reads();
                    let endpoints = task
                        .pending_requests()
                        .iter()
                        .map(|request| request.endpoint().clone())
                        .collect::<Vec<_>>();
                    assert!(!endpoints.is_empty());
                    for _ in 0..3 {
                        assert!(matches!(
                            task.poll_with_readiness(
                                &mut session,
                                &mut hierarchy,
                                &mut artifacts,
                                &mut |_| Ok(DemandForwardReadiness::AwaitingDependencies)
                            )
                            .unwrap(),
                            DemandFactEvaluationPoll::AwaitingDependencies
                        ));
                        assert_eq!(task.evaluation.as_ref().unwrap().work, work);
                        assert_eq!(source_reads(), reads);
                        assert_eq!(
                            task.pending_requests()
                                .iter()
                                .map(|request| request.endpoint().clone())
                                .collect::<Vec<_>>(),
                            endpoints
                        );
                    }
                    if suffix {
                        suspended_suffix = true;
                    } else if hierarchy_local {
                        suspended_hierarchy = true;
                    } else {
                        suspended_direct = true;
                    }
                }
                DemandFactEvaluationPoll::Ready(actual) => {
                    assert!(suspended_direct && suspended_hierarchy && suspended_suffix);
                    assert_eq!(*actual, expected);
                    return;
                }
            }
        }
        panic!("qualified frame did not terminate");
    }

    #[test]
    fn experimental_qualified_cancellation_retains_pending_replay_operands() {
        let fixture = java_fixture();
        // Reach the suffix only after the real a.f hierarchy-local phase.
        let reference = fixture.references[&9];
        let seed_gap = SemanticId::for_test(b"qualified-cancel-seed");
        let page_gap = SemanticId::for_test(b"qualified-cancel-page");
        let pending_gap = SemanticId::for_test(b"qualified-cancel-pending-plan");
        let mut observed = ObservedBatchSource::new(&fixture.service.source);
        observed.reference_seed_completion = Some((reference, incomplete(seed_gap)));
        observed.forward_match_completion = Some(incomplete(page_gap));
        let cancellation = CancellationToken::new();
        let mut session =
            FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut artifacts = ForwardCandidateArtifactCache::default();
        let initial =
            FactEvaluation::new(&mut session, &mut hierarchy, reference).into_checkpoint_state();
        let mut task = DemandFactEvaluationTask::new(initial);
        for _ in 0..1024 {
            let suffix = task
                .references
                .as_ref()
                .and_then(|frame| frame.qualified.as_ref())
                .is_some_and(|frame| frame.replay.is_some());
            match task
                .poll_with_readiness(&mut session, &mut hierarchy, &mut artifacts, &mut |_| {
                    Ok(if suffix {
                        DemandForwardReadiness::AwaitingDependencies
                    } else {
                        DemandForwardReadiness::Ready
                    })
                })
                .unwrap()
            {
                DemandFactEvaluationPoll::Continue => {}
                DemandFactEvaluationPoll::AwaitingDependencies => {
                    assert!(suffix);
                    // This phase-owned operand has not yet been merged into a
                    // completed qualified answer. Cancellation must drain it.
                    task.references
                        .as_mut()
                        .unwrap()
                        .qualified
                        .as_mut()
                        .unwrap()
                        .replay
                        .as_mut()
                        .unwrap()
                        .plan
                        .omitted_completion = incomplete(pending_gap);
                    let reads = (
                        observed.forward_match_calls.get(),
                        observed.path_hydration_calls.get(),
                    );
                    let answer = task.cancel(&mut session, &mut hierarchy);
                    assert!(!cancellation.is_cancelled());
                    assert_eq!(
                        (
                            observed.forward_match_calls.get(),
                            observed.path_hydration_calls.get()
                        ),
                        reads
                    );
                    assert!(answer.binding().targets().is_empty());
                    for completion in [answer.binding().completion(), answer.completion()] {
                        assert!(completion.contains_reason(ResolutionIncompleteReason::Cancelled));
                        for gap in [seed_gap, page_gap, pending_gap] {
                            assert!(
                                completion.contains_reason(
                                    ResolutionIncompleteReason::UnsupportedSemantic(gap)
                                ),
                                "missing retained operand {gap}"
                            );
                        }
                    }
                    assert!(task.pending_requests().is_empty());
                    assert!(task.evaluation.as_ref().unwrap().lexical_answers.is_empty());
                    return;
                }
                _ => panic!("qualified cancellation fixture must reach suffix suspension"),
            }
        }
        panic!("qualified suffix never suspended");
    }

    #[test]
    fn experimental_hierarchy_local_resume_reuses_concurrently_published_keys() {
        let fixture = parsed_java_service_fixture(
            "class C { int x; } class D { int x; } class Use { int get(C c) { return c.x; } }",
            b"experimental-interleaved-hierarchy",
        );
        let reference = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Reference,
        )[0];
        let owners = ["C", "D"].map(|name| {
            lowered_semantics_named(
                &fixture.facts,
                &fixture.lexical,
                name,
                ResolutionIdentifierRole::Declaration,
            )[0]
        });
        let route_id = fixture.service.typed.qualified_route_ids_by_reference[&reference][0];
        let route = fixture.service.typed.selected_source_route(route_id);
        let shape = HierarchyLookupShape::new(
            route.row().lookup(),
            ResolutionNamespace::Value,
            QualifierCategory::Runtime,
            0,
        );
        let keys = owners.map(|owner| HierarchyNodeKey { shape, owner });
        let observed = ObservedBatchSource::new(&fixture.service.source);
        let cancellation = CancellationToken::new();
        let mut session =
            FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut artifacts = ForwardCandidateArtifactCache::default();
        let mut evaluation = FactEvaluation::new_with_forward_artifacts(
            &mut session,
            &mut hierarchy,
            &mut artifacts,
            reference,
        );
        let mut first = DemandHierarchyLocalFrame::new(&mut evaluation, &keys[..1]).unwrap();
        let mut second = DemandHierarchyLocalFrame::new(&mut evaluation, &keys).unwrap();
        assert!(matches!(
            second
                .poll(&mut evaluation, &mut |_| panic!(
                    "staging precedes readiness"
                ))
                .unwrap(),
            DemandHierarchyLocalPoll::Continue
        ));
        assert!(matches!(
            second
                .poll(&mut evaluation, &mut |_| Ok(
                    DemandForwardReadiness::AwaitingDependencies
                ))
                .unwrap(),
            DemandHierarchyLocalPoll::AwaitingDependencies
        ));
        let mut first_done = false;
        for _ in 0..8 {
            match first
                .poll(&mut evaluation, &mut |_| Ok(DemandForwardReadiness::Ready))
                .unwrap()
            {
                DemandHierarchyLocalPoll::Continue => {}
                DemandHierarchyLocalPoll::Ready(true) => {
                    first_done = true;
                    break;
                }
                _ => panic!("first local frame must exhaust"),
            }
        }
        assert!(first_done);
        let first_definitions = evaluation.hierarchy.local_nodes[&keys[0]]
            .direct_definitions
            .clone();
        assert_eq!(first_definitions.len(), 1);
        let reads = observed.forward_match_requests.borrow().len();
        let remaining_scope = fixture.service.typed.member_scope_by_definition[&owners[1]];
        let mut second_done = false;
        for _ in 0..8 {
            match second
                .poll(&mut evaluation, &mut |_| Ok(DemandForwardReadiness::Ready))
                .unwrap()
            {
                DemandHierarchyLocalPoll::Continue => {}
                DemandHierarchyLocalPoll::Ready(true) => {
                    second_done = true;
                    break;
                }
                _ => panic!("second local frame must exhaust without overwriting the first key"),
            }
        }
        assert!(second_done);
        assert_eq!(
            evaluation.hierarchy.local_nodes[&keys[0]].direct_definitions,
            first_definitions
        );
        assert_eq!(
            evaluation.hierarchy.local_nodes[&keys[1]]
                .direct_definitions
                .len(),
            1
        );
        let requests = observed.forward_match_requests.borrow();
        assert!(!requests[reads..].is_empty());
        assert!(
            requests[reads..]
                .iter()
                .flatten()
                .all(|endpoint| endpoint.node() == remaining_scope)
        );
    }

    #[test]
    fn experimental_hierarchy_local_frames_match_field_and_nested_type_answers() {
        for (source, spelling) in [
            (
                "class C { int x; } class Use { int get(C c) { return c.x; } }",
                "x",
            ),
            (
                "class C { static class Nested {} } class Use { C.Nested value; }",
                "Nested",
            ),
        ] {
            let fixture = parsed_java_service_fixture(source, b"experimental-direct-hierarchy");
            let reference = lowered_semantics_named(
                &fixture.facts,
                &fixture.lexical,
                spelling,
                ResolutionIdentifierRole::Reference,
            )[0];
            let cancellation = CancellationToken::new();
            let expected = fixture
                .service
                .resolve_reference(reference, &cancellation)
                .unwrap();
            assert!(!expected.binding().targets().is_empty());
            let observed = ObservedBatchSource::new(&fixture.service.source);
            let mut session =
                FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
            let mut hierarchy = HierarchyOperationArena::default();
            let mut artifacts = ForwardCandidateArtifactCache::default();
            let initial = FactEvaluation::new(&mut session, &mut hierarchy, reference)
                .into_checkpoint_state();
            let mut task = DemandFactEvaluationTask::new(initial);
            let mut suspended = false;
            let mut finished = false;
            for _ in 0..1024 {
                let local = task
                    .references
                    .as_ref()
                    .and_then(|frame| frame.qualified.as_ref())
                    .is_some_and(|frame| frame.hierarchy_group.is_some());
                match task
                    .poll_with_readiness(&mut session, &mut hierarchy, &mut artifacts, &mut |_| {
                        Ok(if local && !suspended {
                            DemandForwardReadiness::AwaitingDependencies
                        } else {
                            DemandForwardReadiness::Ready
                        })
                    })
                    .unwrap()
                {
                    DemandFactEvaluationPoll::Continue => {}
                    DemandFactEvaluationPoll::AwaitingHierarchyReferences(references) => {
                        panic!(
                            "fixture unexpectedly requires qualified supertype tasks: {references:?}"
                        )
                    }
                    DemandFactEvaluationPoll::AwaitingDemandedReference(reference) => {
                        unreachable!("a granted claim never suspends a reference: {reference:?}")
                    }
                    DemandFactEvaluationPoll::AwaitingDependencies => {
                        assert!(local);
                        let work = task.evaluation.as_ref().unwrap().work;
                        let reads = || {
                            (
                                observed.forward_match_calls.get(),
                                observed.path_hydration_calls.get(),
                                observed.endpoint_classification_calls.get(),
                            )
                        };
                        let before = reads();
                        let endpoints = task
                            .pending_requests()
                            .iter()
                            .map(|request| request.endpoint().clone())
                            .collect::<Vec<_>>();
                        assert!(!endpoints.is_empty());
                        for _ in 0..3 {
                            assert!(matches!(
                                task.poll_with_readiness(
                                    &mut session,
                                    &mut hierarchy,
                                    &mut artifacts,
                                    &mut |_| Ok(DemandForwardReadiness::AwaitingDependencies)
                                )
                                .unwrap(),
                                DemandFactEvaluationPoll::AwaitingDependencies
                            ));
                            assert_eq!(task.evaluation.as_ref().unwrap().work, work);
                            assert_eq!(reads(), before);
                            assert_eq!(
                                task.pending_requests()
                                    .iter()
                                    .map(|request| request.endpoint().clone())
                                    .collect::<Vec<_>>(),
                                endpoints
                            );
                        }
                        suspended = true;
                    }
                    DemandFactEvaluationPoll::Ready(actual) => {
                        assert!(suspended);
                        assert_eq!(*actual, expected);
                        assert!(!hierarchy.local_nodes.is_empty());
                        assert!(hierarchy.edge_nodes.is_empty());
                        finished = true;
                        break;
                    }
                }
            }
            assert!(
                finished,
                "direct hierarchy fixture did not complete: {source}"
            );
        }
    }

    #[test]
    fn experimental_hierarchy_closure_frames_reuse_a_peer_published_scc() {
        let fixture = parsed_java_service_fixture(
            "class A extends B {} class B extends A {}",
            b"experimental-overlapping-scc",
        );
        let [a, b] = ["A", "B"].map(|name| {
            lowered_semantics_named(
                &fixture.facts,
                &fixture.lexical,
                name,
                ResolutionIdentifierRole::Declaration,
            )[0]
        });
        let cancellation = CancellationToken::new();
        let observed = ObservedBatchSource::new(&fixture.service.source);
        let mut session =
            FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut artifacts = ForwardCandidateArtifactCache::default();
        let mut evaluation = FactEvaluation::new_with_forward_artifacts(
            &mut session,
            &mut hierarchy,
            &mut artifacts,
            a,
        );
        let mut first =
            DemandHierarchyClosureFrame::new(&mut evaluation, &BTreeSet::from([a])).unwrap();
        let mut second =
            DemandHierarchyClosureFrame::new(&mut evaluation, &BTreeSet::from([b])).unwrap();
        let mut suspended = false;
        for _ in 0..128 {
            match first
                .poll(&mut evaluation, &mut |_| {
                    Ok(DemandForwardReadiness::AwaitingDependencies)
                })
                .unwrap()
            {
                DemandHierarchyLocalPoll::Continue => {}
                DemandHierarchyLocalPoll::AwaitingDependencies => {
                    suspended = true;
                    break;
                }
                _ => panic!("the first closure must suspend on its supertype reference"),
            }
        }
        assert!(suspended);
        for frame in [&mut second, &mut first] {
            let mut finished = false;
            for _ in 0..512 {
                match frame
                    .poll(&mut evaluation, &mut |_| Ok(DemandForwardReadiness::Ready))
                    .unwrap()
                {
                    DemandHierarchyLocalPoll::Continue => {}
                    DemandHierarchyLocalPoll::Ready(true) => {
                        finished = true;
                        break;
                    }
                    _ => panic!("an overlapping live SCC closure must complete"),
                }
            }
            assert!(finished);
            assert!(evaluation.hierarchy.closure_contains(a));
            assert!(evaluation.hierarchy.closure_contains(b));
            assert!(evaluation.hierarchy.cycle(a).is_some());
            assert_eq!(evaluation.hierarchy.cycle(a), evaluation.hierarchy.cycle(b));
        }
        assert_eq!(evaluation.hierarchy.edge_nodes.len(), 2);
    }

    #[test]
    fn experimental_hierarchy_reference_frames_reuse_peer_publication_before_admission() {
        for stage_seeds in [false, true] {
            let fixture = java_fixture();
            let shared = fixture.references[&7];
            let unique = fixture.references[&8];
            let mut references = [shared, unique];
            references.sort_unstable();
            let cancellation = CancellationToken::new();
            let observed = ObservedBatchSource::new(&fixture.service.source);
            let mut session =
                FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
            let mut hierarchy = HierarchyOperationArena::default();
            let mut artifacts = ForwardCandidateArtifactCache::default();
            let mut evaluation = FactEvaluation::new_with_forward_artifacts(
                &mut session,
                &mut hierarchy,
                &mut artifacts,
                shared,
            );
            let mut frame =
                DemandHierarchyReferenceFrame::new(&mut evaluation, &references).unwrap();
            if stage_seeds {
                assert!(matches!(
                    frame
                        .poll(&mut evaluation, &mut |_| panic!(
                            "seed preparation cannot read candidates"
                        ))
                        .unwrap(),
                    DemandHierarchyLocalPoll::Continue
                ));
                assert!(!frame.seeds.is_empty());
            }
            // Complete the shared operand through the independent eager
            // controller after this frame has frozen its original missing set.
            assert!(
                evaluation
                    .ensure_hierarchy_reference_answers(&[shared])
                    .unwrap()
            );
            let shared_answer = evaluation.hierarchy.reference_answers[&shared].clone();
            let seed_reads = observed.reference_seed_batch_queries.borrow().len();
            let mut finished = false;
            for _ in 0..128 {
                match frame
                    .poll(&mut evaluation, &mut |_| Ok(DemandForwardReadiness::Ready))
                    .unwrap()
                {
                    DemandHierarchyLocalPoll::Continue => {}
                    DemandHierarchyLocalPoll::Ready(true) => {
                        finished = true;
                        break;
                    }
                    _ => panic!("live peer-reuse frame must complete"),
                }
            }
            assert!(finished);
            let queries = observed.reference_seed_batch_queries.borrow();
            assert!(
                queries[seed_reads..]
                    .iter()
                    .flatten()
                    .all(|reference| *reference == unique)
            );
            assert_eq!(queries.len() - seed_reads, usize::from(!stage_seeds));
            assert_eq!(
                evaluation.hierarchy.reference_answers[&shared],
                shared_answer
            );
            assert!(
                !evaluation.hierarchy.reference_answers[&unique]
                    .targets()
                    .is_empty()
            );
            assert_eq!(evaluation.hierarchy.reference_answers.len(), 2);
        }
    }

    #[test]
    fn experimental_inherited_hierarchy_frames_match_eager_and_never_replay_waits() {
        for (source, spelling, expect_target) in [
            (
                "class Base { int x; } class C extends Base {} class Use { int get(C c) { return c.x; } }",
                "x",
                true,
            ),
            (
                "class Base { static class Nested {} } class C extends Base {} class Use { C.Nested value; }",
                "Nested",
                true,
            ),
            (
                "class A extends B {} class B extends A {} class Use { int get(A a) { return a.missing; } }",
                "missing",
                false,
            ),
        ] {
            let fixture = parsed_java_service_fixture(source, b"experimental-inherited-hierarchy");
            let reference = lowered_semantics_named(
                &fixture.facts,
                &fixture.lexical,
                spelling,
                ResolutionIdentifierRole::Reference,
            )[0];
            let cancellation = CancellationToken::new();
            let expected = fixture
                .service
                .resolve_reference(reference, &cancellation)
                .unwrap();
            assert_eq!(!expected.binding().targets().is_empty(), expect_target);
            let observed = ObservedBatchSource::new(&fixture.service.source);
            let mut session =
                FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
            let mut hierarchy = HierarchyOperationArena::default();
            let mut artifacts = ForwardCandidateArtifactCache::default();
            let initial = FactEvaluation::new(&mut session, &mut hierarchy, reference)
                .into_checkpoint_state();
            let mut task = DemandFactEvaluationTask::new(initial);
            let mut release_next = false;
            let mut suspended_references = false;
            let mut suspended_members = false;
            let mut finished = false;
            for _ in 0..4096 {
                let inherited = task
                    .references
                    .as_ref()
                    .and_then(|frame| frame.qualified.as_ref())
                    .and_then(|frame| frame.hierarchy_group.as_ref())
                    .and_then(|group| group.inherited.as_ref());
                let reference_phase = inherited.is_some_and(|frame| frame.closure.is_some());
                let member_phase = inherited.is_some_and(|frame| frame.summaries.is_some());
                let release = std::mem::take(&mut release_next);
                match task
                    .poll_with_readiness(&mut session, &mut hierarchy, &mut artifacts, &mut |_| {
                        Ok(if release {
                            DemandForwardReadiness::Ready
                        } else {
                            DemandForwardReadiness::AwaitingDependencies
                        })
                    })
                    .unwrap()
                {
                    DemandFactEvaluationPoll::Continue => {}
                    DemandFactEvaluationPoll::AwaitingHierarchyReferences(references) => {
                        panic!(
                            "fixture unexpectedly requires qualified supertype tasks: {references:?}"
                        )
                    }
                    DemandFactEvaluationPoll::AwaitingDemandedReference(reference) => {
                        unreachable!("a granted claim never suspends a reference: {reference:?}")
                    }
                    DemandFactEvaluationPoll::AwaitingDependencies => {
                        assert!(!release);
                        suspended_references |= reference_phase;
                        suspended_members |= member_phase;
                        let work = task.evaluation.as_ref().unwrap().work;
                        let reads = || {
                            (
                                observed.reference_seed_batch_lookups.get(),
                                observed.forward_match_calls.get(),
                                observed.path_hydration_calls.get(),
                                observed.endpoint_classification_calls.get(),
                            )
                        };
                        let before = reads();
                        let endpoints = task
                            .pending_requests()
                            .iter()
                            .map(|request| request.endpoint().clone())
                            .collect::<Vec<_>>();
                        assert!(!endpoints.is_empty());
                        for _ in 0..3 {
                            assert!(matches!(
                                task.poll_with_readiness(
                                    &mut session,
                                    &mut hierarchy,
                                    &mut artifacts,
                                    &mut |_| Ok(DemandForwardReadiness::AwaitingDependencies)
                                )
                                .unwrap(),
                                DemandFactEvaluationPoll::AwaitingDependencies
                            ));
                            assert_eq!(task.evaluation.as_ref().unwrap().work, work);
                            assert_eq!(reads(), before);
                            assert_eq!(
                                task.pending_requests()
                                    .iter()
                                    .map(|request| request.endpoint().clone())
                                    .collect::<Vec<_>>(),
                                endpoints
                            );
                        }
                        release_next = true;
                    }
                    DemandFactEvaluationPoll::Ready(actual) => {
                        assert!(
                            suspended_references,
                            "supertype references must suspend: {source}"
                        );
                        if expect_target {
                            assert!(
                                suspended_members,
                                "inherited members must suspend: {source}"
                            );
                        }
                        assert_eq!(*actual, expected, "{source}");
                        assert!(!hierarchy.edge_nodes.is_empty());
                        assert!(!hierarchy.committed_publications.is_empty());
                        finished = true;
                        break;
                    }
                }
            }
            assert!(
                finished,
                "inherited hierarchy fixture did not terminate: {source}"
            );
        }
    }

    #[test]
    fn experimental_inherited_cancellation_drains_the_active_supertype_batch() {
        for read_page in [false, true] {
            let fixture = parsed_java_service_fixture(
                "class Base { int x; } class C extends Base {} class Use { int get(C c) { return c.x; } }",
                b"experimental-inherited-cancellation",
            );
            let reference = lowered_semantics_named(
                &fixture.facts,
                &fixture.lexical,
                "x",
                ResolutionIdentifierRole::Reference,
            )[0];
            let supertype = lowered_semantics_named(
                &fixture.facts,
                &fixture.lexical,
                "Base",
                ResolutionIdentifierRole::Reference,
            )[0];
            let seed_gap = SemanticId::for_test(b"inherited-active-seed-gap");
            let page_gap = SemanticId::for_test(b"inherited-active-page-gap");
            let mut observed = ObservedBatchSource::new(&fixture.service.source);
            observed.reference_seed_completion = Some((supertype, incomplete(seed_gap)));
            // The first superclass page starts at the identity seed, before
            // pushing its Base lookup symbol. Match that exact source node,
            // not a later symbol-stack shape that this test never reads.
            observed.forward_branch_node = Some(
                fixture
                    .service
                    .source
                    .reference_seed(ResolutionQuery::new(supertype), &CancellationToken::new())
                    .unwrap()
                    .expect("the superclass reference has an exact seed")
                    .node(),
            );
            observed.forward_branch_completion = Some(incomplete(page_gap));
            let cancellation = CancellationToken::new();
            let mut session =
                FactReadSession::for_preloaded_service(&fixture.service, &observed, &cancellation);
            let mut hierarchy = HierarchyOperationArena::default();
            let mut artifacts = ForwardCandidateArtifactCache::default();
            let initial = FactEvaluation::new(&mut session, &mut hierarchy, reference)
                .into_checkpoint_state();
            let mut task = DemandFactEvaluationTask::new(initial);
            let mut suspended = false;
            for _ in 0..4096 {
                let inherited = task
                    .references
                    .as_ref()
                    .and_then(|frame| frame.qualified.as_ref())
                    .and_then(|frame| frame.hierarchy_group.as_ref())
                    .and_then(|group| group.inherited.as_ref())
                    .is_some_and(|frame| frame.closure.is_some());
                match task
                    .poll_with_readiness(&mut session, &mut hierarchy, &mut artifacts, &mut |_| {
                        Ok(if inherited {
                            DemandForwardReadiness::AwaitingDependencies
                        } else {
                            DemandForwardReadiness::Ready
                        })
                    })
                    .unwrap()
                {
                    DemandFactEvaluationPoll::Continue => {}
                    DemandFactEvaluationPoll::AwaitingDependencies => {
                        assert!(inherited);
                        suspended = true;
                        break;
                    }
                    _ => panic!("supertype lookup must reach its dependency boundary"),
                }
            }
            assert!(suspended);
            if read_page {
                let before = observed.forward_match_calls.get();
                let mut read = false;
                for _ in 0..16 {
                    assert!(matches!(
                        task.poll_with_readiness(
                            &mut session,
                            &mut hierarchy,
                            &mut artifacts,
                            &mut |_| Ok(DemandForwardReadiness::Ready)
                        )
                        .unwrap(),
                        DemandFactEvaluationPoll::Continue
                    ));
                    if observed.forward_match_calls.get() > before {
                        read = true;
                        break;
                    }
                }
                assert!(read);
            }
            assert!(!hierarchy.reference_answers.contains_key(&supertype));
            let active = task
                .references
                .as_ref()
                .unwrap()
                .qualified
                .as_ref()
                .unwrap()
                .hierarchy_group
                .as_ref()
                .unwrap()
                .inherited
                .as_ref()
                .unwrap()
                .closure
                .as_ref()
                .unwrap()
                .edges
                .as_ref()
                .unwrap()
                .references
                .as_ref()
                .unwrap();
            assert!(
                active.active.is_some(),
                "the seed and any page evidence remain owned by the live batch"
            );
            let reads = || {
                (
                    observed.reference_seed_batch_lookups.get(),
                    observed.forward_match_calls.get(),
                    observed.path_hydration_calls.get(),
                    observed.endpoint_classification_calls.get(),
                )
            };
            let before = reads();
            let answer = task.cancel(&mut session, &mut hierarchy);
            assert_eq!(reads(), before);
            assert!(!cancellation.is_cancelled());
            assert!(answer.binding().targets().is_empty());
            assert!(task.pending_requests().is_empty());
            for completion in [answer.completion(), answer.binding().completion()] {
                assert!(completion.contains_reason(ResolutionIncompleteReason::Cancelled));
                assert!(
                    completion
                        .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(seed_gap))
                );
                assert_eq!(
                    completion
                        .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(page_gap)),
                    read_page
                );
            }
            assert!(!hierarchy.reference_answers.contains_key(&supertype));
        }
    }

    #[test]
    fn experimental_fact_frame_matches_eager_rounds_and_releases_resource_borrows() {
        let fixture = java_fixture();
        for reference in [fixture.references[&8], fixture.references[&9]] {
            let cancellation = CancellationToken::new();
            let mut eager_session = preloaded_session(&fixture.service, &cancellation);
            let mut eager_hierarchy = HierarchyOperationArena::default();
            let mut eager_artifacts = ForwardCandidateArtifactCache::default();
            let mut eager = FactEvaluation::new_with_forward_artifacts(
                &mut eager_session,
                &mut eager_hierarchy,
                &mut eager_artifacts,
                reference,
            );
            let expected = eager.run().unwrap();
            let expected_work = eager.work;
            let mut session = preloaded_session(&fixture.service, &cancellation);
            let mut hierarchy = HierarchyOperationArena::default();
            let mut artifacts = ForwardCandidateArtifactCache::default();
            let initial = FactEvaluation::new(&mut session, &mut hierarchy, reference)
                .into_checkpoint_state();
            let mut task = DemandFactEvaluationTask::new(initial);
            let mut actual = None;
            for _ in 0..64 {
                // Move the frame between polls. No session/hierarchy reference
                // survives inside it, unlike a parked FactEvaluation borrow.
                let mut arena = vec![task];
                task = arena.pop().unwrap();
                match task
                    .poll(&mut session, &mut hierarchy, &mut artifacts)
                    .unwrap()
                {
                    DemandFactEvaluationPoll::Continue => {}
                    DemandFactEvaluationPoll::AwaitingHierarchyReferences(references) => {
                        panic!(
                            "fixture unexpectedly requires qualified supertype tasks: {references:?}"
                        )
                    }
                    DemandFactEvaluationPoll::AwaitingDemandedReference(reference) => {
                        unreachable!("a granted claim never suspends a reference: {reference:?}")
                    }
                    DemandFactEvaluationPoll::AwaitingDependencies => {
                        panic!("synchronous frame cannot suspend")
                    }
                    DemandFactEvaluationPoll::Ready(answer) => {
                        actual = Some(answer);
                        break;
                    }
                }
            }
            assert_eq!(
                *actual.expect("bounded fixture reaches a terminal round"),
                expected
            );
            assert_eq!(task.phase, DemandFactEvaluationPhase::Terminal);
            assert_eq!(task.evaluation.as_ref().unwrap().work, expected_work);
        }
    }

    #[test]
    fn experimental_fact_frame_retains_late_demand_growth_before_certification() {
        let source = "class B {} class A { void f(B x) {} void g(B argument) { f(argument); } }";
        let fixture = parsed_java_service_fixture(source, b"stepped-late-parameter-demand");
        let site = positioned_site_at(
            &fixture.facts,
            source.rfind("f(argument)").unwrap(),
            ResolutionIdentifierRole::Reference,
            ResolutionNamespace::Callable,
        );
        let reference = lowered_semantic_at(&fixture.lexical, site, LoweredSemanticRole::Reference);
        let cancellation = CancellationToken::new();
        let mut eager_session = preloaded_session(&fixture.service, &cancellation);
        let mut eager_hierarchy = HierarchyOperationArena::default();
        let expected = FactEvaluation::new(&mut eager_session, &mut eager_hierarchy, reference)
            .run()
            .unwrap();
        let mut session = preloaded_session(&fixture.service, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut artifacts = ForwardCandidateArtifactCache::default();
        let initial =
            FactEvaluation::new(&mut session, &mut hierarchy, reference).into_checkpoint_state();
        let mut task = DemandFactEvaluationTask::new(initial);
        assert!(matches!(
            task.poll(&mut session, &mut hierarchy, &mut artifacts)
                .unwrap(),
            DemandFactEvaluationPoll::Continue
        ));
        let initial_epoch = task.demand_epoch;
        assert!(matches!(
            task.poll(&mut session, &mut hierarchy, &mut artifacts)
                .unwrap(),
            DemandFactEvaluationPoll::Continue
        ));
        assert!(task.demand_epoch.0 > initial_epoch.0);
        assert!(task.demand_epoch.1 > initial_epoch.1);
        assert!(
            task.cycle.is_none(),
            "demand-growing round cannot certify the old epoch"
        );
        for _ in 0..64 {
            if let DemandFactEvaluationPoll::Ready(actual) = task
                .poll(&mut session, &mut hierarchy, &mut artifacts)
                .unwrap()
            {
                assert_eq!(*actual, expected);
                return;
            }
        }
        panic!("late-demand fixture failed to terminate");
    }

    #[test]
    fn experimental_fact_frame_cancellation_between_steps_retains_root_evidence() {
        let fixture = java_fixture();
        let reference = fixture.references[&9];
        let reason = SemanticId::for_test(b"stepped-root-cancellation-evidence");
        let cancellation = CancellationToken::new();
        let mut eager_session = preloaded_session(&fixture.service, &cancellation);
        let mut eager_hierarchy = HierarchyOperationArena::default();
        let mut eager = FactEvaluation::from_lexical_answer(
            &mut eager_session,
            &mut eager_hierarchy,
            reference,
            ResolutionAnswer::new(Vec::new(), Vec::new(), incomplete(reason)),
        );
        assert!(eager.initialize_root_demands().unwrap());
        let mut session = preloaded_session(&fixture.service, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut artifacts = ForwardCandidateArtifactCache::default();
        let initial = FactEvaluation::from_lexical_answer(
            &mut session,
            &mut hierarchy,
            reference,
            ResolutionAnswer::new(Vec::new(), Vec::new(), incomplete(reason)),
        )
        .into_checkpoint_state();
        let mut task = DemandFactEvaluationTask::new(initial);
        assert!(matches!(
            task.poll(&mut session, &mut hierarchy, &mut artifacts)
                .unwrap(),
            DemandFactEvaluationPoll::Continue
        ));
        cancellation.cancel();
        let expected = eager.run().unwrap();
        let DemandFactEvaluationPoll::Ready(answer) = task
            .poll(&mut session, &mut hierarchy, &mut artifacts)
            .unwrap()
        else {
            panic!("cancelled frame must terminate, never become pending or absent")
        };
        assert!(answer.binding().targets().is_empty());
        assert_eq!(*answer, expected);
        assert!(
            answer
                .completion()
                .contains_reason(ResolutionIncompleteReason::Cancelled)
        );
        assert!(
            answer
                .completion()
                .contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(reason))
        );
    }

    #[test]
    fn late_callable_parameter_projection_advances_the_demand_epoch() {
        let source = "class B {} class A { void f(B x) {} void g(B argument) { f(argument); } }";
        let fixture = parsed_java_service_fixture(source, b"late-callable-parameter-demand-epoch");
        let declaration = java_callable_definition_at(
            &fixture,
            source.find("void f").expect("method f") + "void ".len(),
        );
        let call_site = positioned_site_at(
            &fixture.facts,
            source.rfind("f(argument)").expect("call f"),
            ResolutionIdentifierRole::Reference,
            ResolutionNamespace::Callable,
        );
        let call_reference =
            lowered_semantic_at(&fixture.lexical, call_site, LoweredSemanticRole::Reference);
        let parameter_slot = fixture
            .typed
            .callable_signatures()
            .iter()
            .find(|signature| signature.definition() == declaration)
            .expect("the selected callable has one signature")
            .parameters()[0]
            .slot();
        let mut pending = vec![parameter_slot];
        let mut seen = HashSet::default();
        let mut late_reference = None;
        while let Some(slot) = pending.pop() {
            if !seen.insert(slot) {
                continue;
            }
            if let Some(projection) = fixture.service.typed.projection_by_output.get(&slot) {
                late_reference = Some(projection.reference());
                break;
            }
            pending.extend(
                fixture
                    .service
                    .typed
                    .transfers_by_target
                    .get(&slot)
                    .into_iter()
                    .flatten()
                    .map(LoweredTypeTransfer::source_slot),
            );
        }
        let late_reference = late_reference
            .expect("the callee parameter type is produced through a type-reference projection");
        assert_ne!(late_reference, call_reference);

        let cancellation = CancellationToken::new();
        let mut session = preloaded_session(&fixture.service, &cancellation);
        let mut hierarchy = HierarchyOperationArena::default();
        let mut previous_answers = HashMap::default();
        let mut previous_states = HashMap::default();
        let mut epoch_guard_observed = false;
        for _ in 0..16 {
            let mut evaluation = FactEvaluation::new(&mut session, &mut hierarchy, call_reference);
            assert!(
                evaluation
                    .initialize_root_demands()
                    .expect("the call root is source-readable")
            );
            let round = evaluation
                .evaluate_round(&previous_answers, &previous_states)
                .expect("the late-demand round is source-readable")
                .expect("the live round is not cancelled");
            assert!(evaluation.demanded_references.contains(&late_reference));
            assert!(
                !round.answers.contains_key(&late_reference),
                "the parameter projection is discovered after this round's reference evaluation"
            );
            let maps_equal = round.answers == previous_answers && round.states == previous_states;
            if maps_equal {
                assert!(
                    !round.stable,
                    "demand growth alone must prevent a false fixed point"
                );
                epoch_guard_observed = true;
                break;
            }
            previous_answers = round.answers;
            previous_states = round.states;
        }
        assert!(
            epoch_guard_observed,
            "the fresh late-demand transition reaches map equality within the bounded fixture"
        );

        let answer = fixture
            .service
            .resolve_reference(call_reference, &CancellationToken::new())
            .expect("a normal subsequent round resolves the late projection");
        assert_eq!(answer.binding().targets(), &[declaration]);
        for (kind, semantic) in [
            (b"unresolved-slot-dependency".as_slice(), parameter_slot),
            (
                b"unresolved-reference-dependency".as_slice(),
                late_reference,
            ),
        ] {
            assert!(
                !answer.completion().contains_reason(
                    ResolutionIncompleteReason::UnsupportedSemantic(service_reason(
                        &hierarchy,
                        kind,
                        &[semantic.as_bytes().as_slice()],
                    ))
                ),
                "the late dependency gets a normal evaluation round before forced-gap fallback"
            );
        }
    }

