    #[test]
    fn go_unnamed_and_variadic_parameters_preserve_inventory_and_partial_applicability() {
        let source = r#"package p

func F(int) {}
func V(values ...int) {}
func use(x int) {
    F(x)
    V(x)
}
"#;
        let fixture = parsed_go_service_fixture(source, b"go-omitted-call-parameters");
        for (declaration_text, call_text) in [("F(int)", "F(x)"), ("V(values", "V(x)")] {
            let (callable_site, callable) = go_callable_definition_at(
                &fixture,
                source
                    .find(declaration_text)
                    .unwrap_or_else(|| panic!("missing Go declaration {declaration_text}")),
            );
            let signature_reason = fixture
                .lexical
                .gaps()
                .iter()
                .find(|gap| {
                    gap.site() == callable_site
                        && gap.origin()
                            == LoweringGapOrigin::Extracted(
                                ResolutionGapKind::UnsupportedCallApplicability,
                            )
                })
                .map(|gap| gap.reason_semantic());
            let signature = fixture
                .typed
                .callable_signatures()
                .iter()
                .find(|signature| signature.definition() == callable)
                .unwrap_or_else(|| panic!("missing signature header for {declaration_text}"));
            if declaration_text == "F(int)" {
                assert_eq!(signature.parameters().len(), 1);
                assert!(signature_reason.is_none());
                assert_eq!(signature.completion(), &ResolutionCompletion::Complete);
            } else {
                assert!(signature.parameters().is_empty());
                assert_incomplete_with_reason(
                    signature.completion(),
                    signature_reason.expect("variadic signature inventory remains incomplete"),
                );
            }

            let (answer, applicability_reason) = resolve_go_call_at(
                &fixture,
                source
                    .rfind(call_text)
                    .unwrap_or_else(|| panic!("missing Go call {call_text}")),
            );
            assert_eq!(answer.binding().targets(), &[callable]);
            assert_eq!(
                answer.binding().completion(),
                &ResolutionCompletion::Complete,
                "Go call name binding is argument-independent"
            );
            assert!(matches!(
                answer.completion(),
                ResolutionCompletion::Incomplete(_)
            ));
            assert!(
                !answer.completion().contains_reason(
                    ResolutionIncompleteReason::UnsupportedSemantic(applicability_reason)
                ),
                "the Go name-binding rule discharges only call applicability: {answer:?}"
            );
        }
    }

    #[test]
    fn go_component_transfers_project_sequence_map_and_channel_members() {
        let source = r#"package p

type Other struct{}
type Item struct { Field Other }
type itemStorage []Item
type Items itemStorage
type itemMap map[Item]Item
type Mapping itemMap
type itemChannel chan Item
type Stream itemChannel
const MapKey = "key"
var indexed = map[string]int{MapKey: 1}

func use(items Items, mapping Mapping, stream Stream) {
	for _, element := range items { _ = element.Field }
	for key, value := range mapping { _ = key.Field; _ = value.Field }
	for value := range stream { _ = value.Field }
}
"#;
        let fixture = parsed_go_service_fixture(source, b"go-component-transfer-projections");
        let field_declaration = positioned_site_at(
            &fixture.facts,
            source.find("Field Other").expect("field declaration"),
            ResolutionIdentifierRole::Declaration,
            ResolutionNamespace::Value,
        );
        let field = lowered_semantic_at(
            &fixture.lexical,
            field_declaration,
            LoweredSemanticRole::Definition,
        );
        let cancellation = CancellationToken::new();
        for (position, _) in source.match_indices("Field").skip(1) {
            let reference_site = positioned_site_at(
                &fixture.facts,
                position,
                ResolutionIdentifierRole::Reference,
                ResolutionNamespace::Value,
            );
            let reference = lowered_semantic_at(
                &fixture.lexical,
                reference_site,
                LoweredSemanticRole::Reference,
            );
            let answer = fixture
                .service
                .resolve_reference(reference, &cancellation)
                .expect("preloaded component projection resolves without storage errors");
            assert_eq!(
                answer.binding().targets(),
                &[field],
                "Field at {position}: {answer:?}"
            );
            assert_eq!(
                answer.binding().completion(),
                &ResolutionCompletion::Complete,
                "Field at {position}: {answer:?}"
            );
        }

        let map_key_definition_site = positioned_site_at(
            &fixture.facts,
            source.find("MapKey =").expect("map-key value declaration"),
            ResolutionIdentifierRole::Declaration,
            ResolutionNamespace::Value,
        );
        let map_key_definition = lowered_semantic_at(
            &fixture.lexical,
            map_key_definition_site,
            LoweredSemanticRole::Definition,
        );
        let map_key_reference_site = positioned_site_at(
            &fixture.facts,
            source.find("MapKey:").expect("map-key expression"),
            ResolutionIdentifierRole::Reference,
            ResolutionNamespace::Value,
        );
        let map_key_reference = lowered_semantic_at(
            &fixture.lexical,
            map_key_reference_site,
            LoweredSemanticRole::Reference,
        );
        let answer = fixture
            .service
            .resolve_reference(map_key_reference, &cancellation)
            .expect("map-key expression resolves through its selected lexical branch");
        assert_eq!(
            answer.binding().targets(),
            &[map_key_definition],
            "map key at {}: {answer:?}",
            source.find("MapKey:").expect("map-key expression")
        );
    }

    #[test]
    fn go_universe_binds_only_after_source_scopes_and_source_names_shadow_it() {
        let builtin_source = r#"package p

func use(values []int) int { _ = new(int); return len(values) }
"#;
        let builtin = parsed_go_service_fixture(builtin_source, b"go-universe-len");
        let builtin_reference = go_reference_at(
            &builtin,
            builtin_source
                .find("len(values)")
                .expect("builtin call site"),
        );
        let cancellation = CancellationToken::new();
        let seed = BatchResolutionFragmentSource::reference_seed(
            &builtin.service,
            ResolutionQuery::new(builtin_reference),
            &cancellation,
        )
        .expect("Go source seed read succeeds")
        .expect("the Go reference has a source seed");
        assert_eq!(
            seed.site_metadata()
                .and_then(FactReferenceSiteMetadata::go_spelling_namespace),
            Some(ResolutionNamespace::TypeOrValue)
        );
        assert_eq!(
            seed.site_metadata()
                .map(FactReferenceSiteMetadata::site_kind),
            Some(ResolutionSiteKind::CallableReference)
        );
        let builtin_site = positioned_site_at(
            &builtin.facts,
            builtin_source
                .find("len(values)")
                .expect("builtin call site"),
            ResolutionIdentifierRole::Reference,
            ResolutionNamespace::TypeOrValue,
        );
        assert!(builtin.facts.gaps.iter().any(|gap| {
            gap.site == builtin_site && gap.kind == ResolutionGapKind::UnsupportedCallApplicability
        }));
        assert_eq!(
            BatchResolutionFragmentSource::go_lookup_spelling(
                &builtin.service,
                builtin_reference,
                ResolutionNamespace::TypeOrValue,
                &cancellation,
            )
            .expect("Go spelling read succeeds")
            .as_deref(),
            Some("len")
        );
        assert!(BatchResolutionFragmentSource::supports_go_universe(
            &builtin.service
        ));
        let direct_binding = BatchResolutionEngine::new(&builtin.service)
            .resolve_reference(ResolutionQuery::new(builtin_reference), &cancellation)
            .expect("Go universe lexical binding resolves without storage errors");
        let intrinsic_len = go_intrinsic_identity(ResolutionNamespace::Callable, "len");
        assert_eq!(
            direct_binding.targets(),
            &[intrinsic_len],
            "Go universe binding failed: seed={seed:?}; answer={direct_binding:?}; facts gaps={:?}; lexical gaps={:?}",
            builtin.facts.gaps,
            builtin.lexical.gaps()
        );
        assert_eq!(direct_binding.completion(), &ResolutionCompletion::Complete);
        let new_reference = go_reference_at(
            &builtin,
            builtin_source
                .find("new(int)")
                .expect("unshadowed builtin new"),
        );
        let new_answer = builtin
            .service
            .resolve_reference(new_reference, &cancellation)
            .expect("Go universe new resolves without storage errors");
        assert_eq!(
            new_answer.binding().targets(),
            &[go_intrinsic_identity(ResolutionNamespace::Callable, "new")]
        );
        assert_eq!(
            new_answer.binding().completion(),
            &ResolutionCompletion::Complete
        );
        assert!(new_answer.callable_receiver_dispositions().is_empty());
        let builtin_answer = builtin
            .service
            .resolve_reference(builtin_reference, &cancellation)
            .expect("Go universe binding resolves without storage errors");
        assert_eq!(
            builtin_answer.binding().targets(),
            &[intrinsic_len],
            "Go universe binding answer: {builtin_answer:?}; lexical gaps={:?}",
            builtin.lexical.gaps()
        );
        assert!(
            builtin_answer.callable_receiver_dispositions().is_empty(),
            "an unqualified Go function call has no receiver: {builtin_answer:?}"
        );
        assert_eq!(
            builtin_answer.binding().completion(),
            &ResolutionCompletion::Complete,
            "the predeclared callable is a complete FactResolution binding: {builtin_answer:?}; gaps={:?}; lexical gaps={:?}",
            builtin.facts.gaps,
            builtin.lexical.gaps()
        );

        let shadowed_source = r#"package p

func len(values []int) int { return 1 }
func new(value int) *int { return &value }
func use(values []int) { _ = len(values); _ = new(1) }
"#;
        let shadowed = parsed_go_service_fixture(shadowed_source, b"go-universe-shadowed-len");
        let declaration = go_callable_definition_at(
            &shadowed,
            shadowed_source
                .find("func len")
                .expect("shadowing function declaration")
                + "func ".len(),
        )
        .1;
        let call = go_reference_at(
            &shadowed,
            shadowed_source
                .rfind("len(values)")
                .expect("shadowing function call"),
        );
        let answer = shadowed
            .service
            .resolve_reference(call, &CancellationToken::new())
            .expect("source shadow resolution succeeds");
        assert_eq!(answer.binding().targets(), &[declaration]);
        // The source declaration must win lexical lookup even though the
        // separate invocation-applicability gap can keep the call partial.
        assert_ne!(answer.binding().targets(), &[intrinsic_len]);
        let new_declaration = go_callable_definition_at(
            &shadowed,
            shadowed_source
                .find("func new")
                .expect("user new declaration")
                + "func ".len(),
        )
        .1;
        let shadowed_new = go_reference_at(
            &shadowed,
            shadowed_source.rfind("new(1)").expect("shadowed new call"),
        );
        let new_answer = shadowed
            .service
            .resolve_reference(shadowed_new, &CancellationToken::new())
            .expect("source new shadow resolution succeeds");
        assert_eq!(new_answer.binding().targets(), &[new_declaration]);
    }

    #[test]
    fn go_range_projection_uses_sequence_string_and_integer_rules() {
        let source = r#"package p

type Count int
type Text string
type Item struct{}
type itemStorage []Item
type Items itemStorage
type Mapping map[string]Item
type Feed chan Item

func use(count Count, text Text, items Items, mapping Mapping, feed Feed) {
	for integerIndex := range count { _ = integerIndex }
	for stringIndex, character := range text { _, _ = stringIndex, character }
	for sequenceIndex, element := range items { _, _ = sequenceIndex, element }
	for mapKey, mapValue := range mapping { _, _ = mapKey, mapValue }
	for channelValue := range feed { _ = channelValue }
}
"#;
        let fixture = parsed_go_service_fixture(source, b"go-range-universe-projections");
        let count_definition = lowered_semantic_at(
            &fixture.lexical,
            positioned_site_at(
                &fixture.facts,
                source.find("Count int").expect("Count declaration"),
                ResolutionIdentifierRole::Declaration,
                ResolutionNamespace::Type,
            ),
            LoweredSemanticRole::Definition,
        );
        let item_definition = lowered_semantic_at(
            &fixture.lexical,
            positioned_site_at(
                &fixture.facts,
                source.find("Item struct").expect("Item declaration"),
                ResolutionIdentifierRole::Declaration,
                ResolutionNamespace::Type,
            ),
            LoweredSemanticRole::Definition,
        );
        let int_reference = go_reference_at(
            &fixture,
            source.find("Count int").expect("Count underlying int") + "Count ".len(),
        );
        let cancellation = CancellationToken::new();
        let int_seed = BatchResolutionFragmentSource::reference_seed(
            &fixture.service,
            ResolutionQuery::new(int_reference),
            &cancellation,
        )
        .expect("Go type-name seed read succeeds")
        .expect("the predeclared int has a source seed");
        let int_spelling = BatchResolutionFragmentSource::go_lookup_spelling(
            &fixture.service,
            int_reference,
            ResolutionNamespace::Type,
            &cancellation,
        )
        .expect("Go type spelling read succeeds");
        let int_answer = fixture
            .service
            .resolve_reference(int_reference, &cancellation)
            .expect("predeclared int resolves without storage errors");
        assert_eq!(
            int_answer.binding().targets(),
            &[go_intrinsic_identity(ResolutionNamespace::Type, "int")],
            "the Count underlying type binds to Go's intrinsic int; seed={int_seed:?}, spelling={int_spelling:?}, gaps={:?}, answer={int_answer:?}",
            fixture.lexical.gaps()
        );
        assert_eq!(
            int_answer.binding().completion(),
            &ResolutionCompletion::Complete
        );
        for (spelling, expected) in [
            ("integerIndex", count_definition),
            (
                "stringIndex",
                go_intrinsic_identity(ResolutionNamespace::Type, "int"),
            ),
            (
                "character",
                go_intrinsic_identity(ResolutionNamespace::Type, "rune"),
            ),
            (
                "sequenceIndex",
                go_intrinsic_identity(ResolutionNamespace::Type, "int"),
            ),
            ("element", item_definition),
            (
                "mapKey",
                go_intrinsic_identity(ResolutionNamespace::Type, "string"),
            ),
            ("mapValue", item_definition),
            ("channelValue", item_definition),
        ] {
            let position = source
                .rmatch_indices(spelling)
                .next()
                .unwrap_or_else(|| panic!("missing Go range use {spelling}"))
                .0;
            assert_eq!(
                go_value_type_at(&fixture, position),
                expected,
                "range binder {spelling} has the Go spec type"
            );
        }
    }

