    #[test]
    fn java_extractor_smoke_resolves_a_returned_local_without_source_reinterpretation() {
        use brokk_bifrost_core::analyzer::ProjectFile;
        use brokk_bifrost_jvm::java::declarations::parse_java_file;
        use tree_sitter::Parser;

        let source = "class A {} class Use { A f() { A a = null; return a; } }";
        let mut parser = Parser::new();
        parser
            .set_language(&tree_sitter_java::LANGUAGE.into())
            .expect("Java grammar");
        let tree = parser.parse(source, None).expect("Java fixture tree");
        let root = std::env::current_dir()
            .expect("current directory")
            .join("fact-resolution-java-extractor-smoke");
        let file = ProjectFile::new(root, "src/Fixture.java");
        let facts = parse_java_file(&file, source, &tree).resolution_facts;

        let class_a_position = source.find("class A").expect("class A") + "class ".len();
        let local_a_position = source.find("A a =").expect("local declaration") + "A ".len();
        let return_a_position =
            source.find("return a").expect("return expression") + "return ".len();
        let site_at = |position: usize, role: ResolutionIdentifierRole| {
            facts
                .identifiers
                .iter()
                .find(|identifier| {
                    identifier.role == role
                        && facts
                            .sites
                            .iter()
                            .find(|site| site.id == identifier.site)
                            .expect("identifier site row")
                            .start_byte
                            == position
                })
                .unwrap_or_else(|| panic!("no {role:?} identifier at byte {position}"))
                .site
        };
        let class_a_site = site_at(class_a_position, ResolutionIdentifierRole::Declaration);
        let local_a_site = site_at(local_a_position, ResolutionIdentifierRole::Declaration);
        let return_a_site = site_at(return_a_position, ResolutionIdentifierRole::Reference);

        let smoke_fragment = BindingFragmentId::for_test(b"java-extractor-resolution-smoke");
        let lexical =
            crate::analyzer::resolution::lower_for_test(smoke_fragment, Language::Java, &facts)
                .lexical()
                .clone();
        let semantic_at = |site: ResolutionSiteId, role: LoweredSemanticRole| {
            lexical
                .semantics()
                .iter()
                .find(|semantic| semantic.site() == site && semantic.role() == role)
                .expect("lowered semantic for positioned Java fact")
                .semantic()
        };
        let class_a = semantic_at(class_a_site, LoweredSemanticRole::Definition);
        let local_a = semantic_at(local_a_site, LoweredSemanticRole::Definition);
        let return_a = semantic_at(return_a_site, LoweredSemanticRole::Reference);
        let typed =
            crate::analyzer::resolution::lower_for_test(smoke_fragment, Language::Java, &facts)
                .typed()
                .clone();
        let service = PreloadedFactResolutionService::from_lowered_fragments([lexical], [typed]);

        let answer = service
            .resolve_reference(return_a, &CancellationToken::new())
            .expect("preload reads are infallible");
        assert_eq!(answer.binding().targets(), &[local_a]);
        assert_eq!(
            only_projected_value(&answer),
            ResolutionSlotValue::runtime(ResolutionTypeRef::new(class_a, 0), false)
        );
        if let ResolutionCompletion::Incomplete(reasons) = answer.completion() {
            assert!(
                !reasons.is_empty(),
                "incomplete extractor smoke must retain exact evidence"
            );
        }
    }

    #[test]
    fn java_extractor_void_call_discharges_placement_and_result_applicability() {
        use brokk_bifrost_core::analyzer::ProjectFile;
        use brokk_bifrost_jvm::java::declarations::parse_java_file;
        use tree_sitter::Parser;

        let source = "abstract class C { abstract void f(); void g() { f(); } }";
        let mut parser = Parser::new();
        parser
            .set_language(&tree_sitter_java::LANGUAGE.into())
            .expect("Java grammar");
        let tree = parser.parse(source, None).expect("Java fixture tree");
        let root = std::env::current_dir()
            .expect("current directory")
            .join("fact-resolution-java-void-call");
        let file = ProjectFile::new(root, "src/Fixture.java");
        let facts = parse_java_file(&file, source, &tree).resolution_facts;

        let declaration_position =
            source.find("void f();").expect("void declaration") + "void ".len();
        let call_position = source.rfind("f();").expect("f call");
        let site_at =
            |position: usize, role: ResolutionIdentifierRole, namespace: ResolutionNamespace| {
                facts
                    .identifiers
                    .iter()
                    .find(|identifier| {
                        identifier.role == role
                            && identifier.namespace == namespace
                            && facts
                                .sites
                                .iter()
                                .find(|site| site.id == identifier.site)
                                .expect("identifier site row")
                                .start_byte
                                == position
                    })
                    .unwrap_or_else(|| {
                        panic!("no {role:?} {namespace:?} identifier at byte {position}")
                    })
                    .site
            };
        let declaration_site = site_at(
            declaration_position,
            ResolutionIdentifierRole::Declaration,
            ResolutionNamespace::Callable,
        );
        let call_reference_site = site_at(
            call_position,
            ResolutionIdentifierRole::Reference,
            ResolutionNamespace::Callable,
        );
        assert!(
            facts
                .calls
                .iter()
                .any(|call| call.callee == call_reference_site),
            "the positioned callable reference must be the structured call callee"
        );

        let void_fragment = BindingFragmentId::for_test(b"java-extractor-void-call");
        let lexical =
            crate::analyzer::resolution::lower_for_test(void_fragment, Language::Java, &facts)
                .lexical()
                .clone();
        let semantic_at = |site: ResolutionSiteId, role: LoweredSemanticRole| {
            lexical
                .semantics()
                .iter()
                .find(|semantic| semantic.site() == site && semantic.role() == role)
                .expect("lowered semantic for positioned Java fact")
                .semantic()
        };
        let declaration = semantic_at(declaration_site, LoweredSemanticRole::Definition);
        let call_reference = semantic_at(call_reference_site, LoweredSemanticRole::Reference);
        let reason_for = |kind| {
            lexical
                .gaps()
                .iter()
                .find(|gap| gap.origin() == LoweringGapOrigin::Extracted(kind))
                .unwrap_or_else(|| panic!("missing {kind:?} lowering gap"))
                .reason_semantic()
        };
        let hierarchy_reason = reason_for(ResolutionGapKind::UnsupportedHierarchyTraversal);
        let placement_reason = reason_for(ResolutionGapKind::UnsupportedPlacementBoundary);
        let typed =
            crate::analyzer::resolution::lower_for_test(void_fragment, Language::Java, &facts)
                .typed()
                .clone();
        let visibility_reason = typed
            .property_gaps()
            .iter()
            .find(|gap| {
                gap.definition() == declaration
                    && gap.kind() == ResolutionGapKind::UnsupportedVisibility
            })
            .expect("the package-private callable has exact declaration visibility evidence")
            .reason_semantic();
        let obligation = typed
            .call_obligations()
            .iter()
            .find(|obligation| obligation.callee_reference() == call_reference)
            .expect("lowered call-applicability obligation");
        let applicability_reason = obligation.applicability_reason();
        let result_slot = obligation.result_slot();
        let service = PreloadedFactResolutionService::from_lowered_fragments([lexical], [typed]);

        let answer = service
            .resolve_reference(call_reference, &CancellationToken::new())
            .expect("preload reads are infallible");
        assert_eq!(answer.binding().targets(), &[declaration]);
        // C's only supertype is the implicit java.lang.Object, which declares
        // no method named `f` (JLS 4.3.2), so no inherited overload can tie
        // the direct method: its hierarchy stage contributes no reason.
        let semantic_completion =
            ResolutionCompletion::incomplete([ResolutionIncompleteReason::UnsupportedSemantic(
                visibility_reason,
            )]);
        assert!(!answer.binding().completion().contains_reason(
            ResolutionIncompleteReason::UnsupportedSemantic(hierarchy_reason)
        ));
        assert_eq!(answer.binding().completion(), &semantic_completion);
        assert_eq!(answer.projected_frontiers().len(), 1);
        let result = &answer.projected_frontiers()[0];
        assert_eq!(result.slot(), result_slot);
        assert!(result.possible_values().is_empty());
        assert_eq!(result.completion(), &semantic_completion);
        assert_eq!(answer.completion(), &semantic_completion);
        assert!(!answer.completion().contains_reason(
            ResolutionIncompleteReason::UnsupportedSemantic(applicability_reason)
        ));
        for completion in [
            answer.binding().completion(),
            result.completion(),
            answer.completion(),
        ] {
            assert!(
                !completion.contains_reason(ResolutionIncompleteReason::UnsupportedSemantic(
                    placement_reason
                ))
            );
        }
    }

    #[test]
    fn void_no_value_does_not_bypass_unresolved_applicability() {
        let source = "abstract class C { abstract void f(); static void g() { f(); } }";
        let fixture = parsed_java_service_fixture(source, b"java-void-call-independent-gap");
        let call_site = positioned_site_at(
            &fixture.facts,
            source.rfind("f();").expect("static call f"),
            ResolutionIdentifierRole::Reference,
            ResolutionNamespace::Callable,
        );
        let reference =
            lowered_semantic_at(&fixture.lexical, call_site, LoweredSemanticRole::Reference);
        let obligation = fixture
            .typed
            .call_obligations()
            .iter()
            .find(|obligation| obligation.callee_reference() == reference)
            .expect("void call obligation");
        let implicit_receiver_reason = fixture
            .lexical
            .gaps()
            .iter()
            .find(|gap| {
                gap.site() == call_site
                    && gap.origin()
                        == LoweringGapOrigin::Extracted(
                            ResolutionGapKind::UnsupportedImplicitReceiver,
                        )
            })
            .expect("static call implicit receiver gap")
            .reason_semantic();
        let answer = fixture
            .service
            .resolve_reference(reference, &CancellationToken::new())
            .expect("preload reads are infallible");
        let result = answer
            .projected_frontiers()
            .iter()
            .find(|frontier| frontier.slot() == obligation.result_slot())
            .expect("void result frontier");
        assert!(result.possible_values().is_empty());
        assert_incomplete_with_reason(result.completion(), implicit_receiver_reason);
        assert!(matches!(
            result.completion(),
            ResolutionCompletion::Incomplete(reasons)
                if reasons.contains(&ResolutionIncompleteReason::UnsupportedSemantic(
                    obligation.applicability_reason()
                ))
        ));
    }

    #[test]
    fn applicability_discharge_preserves_cancellation() {
        let applicability = SemanticId::for_test(b"pending-call-applicability");
        let completion = ResolutionCompletion::incomplete([
            ResolutionIncompleteReason::UnsupportedSemantic(applicability),
            ResolutionIncompleteReason::Cancelled,
        ]);
        assert_eq!(
            completion_without_unsupported_semantic(&completion, applicability),
            ResolutionCompletion::incomplete([ResolutionIncompleteReason::Cancelled])
        );
    }

    fn detector_snapshot(label: u8) -> EvaluationSnapshot {
        let references = [SemanticId::for_test([label])].into_iter().collect();
        snapshot(
            &references,
            &HashSet::default(),
            &HashMap::default(),
            &HashMap::default(),
        )
    }

    fn detected_period(labels: &[u8]) -> Option<usize> {
        let (&first, rest) = labels.split_first().expect("cycle fixture has an origin");
        let mut detector = ExactCycleDetector::new(detector_snapshot(first));
        let cancellation = CancellationToken::new();
        let mut work = 0;
        rest.iter().find_map(|&label| {
            match detector.observe(detector_snapshot(label), &cancellation, &mut work) {
                CycleObservation::Continue => None,
                CycleObservation::Repeated(period) => Some(period),
                CycleObservation::Cancelled => panic!("uncancelled detector fixture cancelled"),
            }
        })
    }

    #[test]
    fn exact_brent_certificate_detects_periods_one_two_and_three() {
        assert_eq!(detected_period(&[0, 0]), Some(1));
        assert_eq!(detected_period(&[0, 1, 0, 1]), Some(2));
        assert_eq!(detected_period(&[0, 1, 2, 0, 1, 2, 0]), Some(3));
    }

