    #[test]
    fn member_owner_metadata_is_classified_once_before_origin_fanout() {
        const ORIGIN_COUNT: usize = 32;
        const PROPERTY_COUNT: usize = 257;

        let mut source =
            String::from("public class Fixture { public static class Shared { public int x; }");
        for ordinal in 0..ORIGIN_COUNT {
            source.push_str(&format!(
                " public static class R{ordinal} extends Shared {{}}"
            ));
        }
        source.push_str(" public static class Use { public int f(R0 v) { return v.x; } } }");
        let mut fixture =
            parsed_java_service_fixture(&source, b"linear-member-owner-classification");
        let reference = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Reference,
        )[0];
        let target = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "x",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let shared = lowered_semantics_named(
            &fixture.facts,
            &fixture.lexical,
            "Shared",
            ResolutionIdentifierRole::Declaration,
        )[0];
        let route_id = fixture.service.typed.qualified_route_ids_by_reference[&reference][0];
        let route = fixture.service.typed.selected_source_route(route_id);
        let qualifier_slot = route.row().qualifier_slot();
        let valid = fixture.service.typed.member_owners_by_definition[&target][0];
        let mut properties = vec![valid];
        for ordinal in 1..PROPERTY_COUNT {
            let conflicting_owner =
                SemanticId::for_test(format!("linear-member-owner-conflict-{ordinal}").as_bytes());
            assert_ne!(conflicting_owner, valid.owner_definition());
            properties.push(LoweredMemberOwnerProperty::new(
                target,
                conflicting_owner,
                valid.owner_scope_head(),
                valid.kind(),
                valid.access(),
                valid.qualifier_compatibility(),
            ));
        }
        properties.sort_by_key(|property| {
            (
                property.owner_definition(),
                property.owner_scope_head(),
                member_kind_rank(property.kind()),
                property.access(),
                qualifier_compatibility_rank(property.qualifier_compatibility()),
            )
        });
        fixture
            .service
            .typed
            .member_owners_by_definition
            .insert(target, properties);

        let mut values = Vec::with_capacity(ORIGIN_COUNT);
        for ordinal in 0..ORIGIN_COUNT {
            let root = lowered_semantics_named(
                &fixture.facts,
                &fixture.lexical,
                &format!("R{ordinal}"),
                ResolutionIdentifierRole::Declaration,
            )[0];
            values.push(ResolutionSlotValue::runtime(
                ResolutionTypeRef::new(root, 0),
                false,
            ));
        }
        let previous_states = [(
            qualifier_slot,
            TypedFrontierState::new(qualifier_slot, values, ResolutionCompletion::Complete),
        )]
        .into_iter()
        .collect::<HashMap<_, _>>();
        let cancellation = CancellationToken::new();
        let mut session = FactReadSession::from_split_sources(
            &fixture.service.source,
            &fixture.service,
            &cancellation,
        );
        let mut hierarchy = HierarchyOperationArena::default();
        let mut evaluation = FactEvaluation::new(&mut session, &mut hierarchy, reference);
        let routes = prime_qualified_reference_seed_for_test(
            &mut evaluation,
            reference,
            std::slice::from_ref(&route),
        );
        let answer = evaluation
            .resolve_qualified(reference, &routes, &shared_map(&previous_states), None)
            .expect("hostile metadata resolution is infallible")
            .expect("hostile metadata resolution is uncancelled");

        let route = fixture.service.typed.qualified_routes[route_id].row;
        let reason = hierarchy_member_owner_reason(
            &hierarchy,
            HierarchyNodeKey {
                shape: HierarchyLookupShape::new(
                    route.lookup(),
                    route.namespace(),
                    QualifierCategory::Runtime,
                    0,
                ),
                owner: shared,
            },
            target,
        );
        assert!(answer.targets().is_empty());
        assert!(answer.witnesses().is_empty());
        assert_eq!(answer.completion(), &incomplete(reason));
        assert_eq!(
            hierarchy.metadata_work,
            HierarchyMetadataWork {
                row_visits: PROPERTY_COUNT,
                definition_classifications: 1,
                match_checks: ORIGIN_COUNT + 1,
                replay_step_copies: 0,
            }
        );
    }

